/* 平成25年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h25.committeeSessions.push(...[{"id":"h25-20131004-4","meetingId":"h25-c-settlement","date":"2013年10月4日","dateIso":"2013-10-04","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を178件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問・要望","question":"２点、お伺いしたいと思います。３款民生費１項社会福祉費２目高齢福祉費、成果報告書の１２４ページ、認知症高齢者の支援とケアの充実についてと、同じく３項生活保護費、１３６ページ、１３７ページについてお伺いをしたいと思います。１点目の認知症高齢者の支援とケアの充実、これの目的とその事業内容について、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"徘徊される高齢者の家族支援としてＧＰＳの探索システムや、高齢者のケアのために困っているケアマネジャーや事業所の方に対しての認知症専門チームによるカンファレンス等がこの中に計上されているものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"松澤委員","kind":"質問","question":"実は、私の町会でこんなことがありました。もう３カ月、４カ月たってもわからない。ところが４カ月たったら、突然ぽそっと自分の名前を言った。平成２２年が新規申し込み３人、平成２３年６人、平成２４年４人。何でこんなに便利なものというか、これは家族にとっては親にそういうのをつけるのが負担なのかもしれませんけれども、これが何で増えていかないのか、それについてお聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それと、実際に周知については、在宅支援センターのケアマネジャーがその高齢者の状態や家族の状態を見ながらお勧めはしているのですけれども、費用の関係や、あと体につけるというところでの抵抗感とか、そういうところでなかなか申請まで行きついていないという状態です。","voiceIndex":6,"id":"exchange-002"},{"speaker":"松澤委員","kind":"質問・要望","question":"これは本当にできるだけ周知していだいて、これをつけることによって本当に助かるのですよということを知らせていただきたいと思います。料金についてもそんなに高くないですよね。それと認知症、これは成果報告書の中ではたった１行なのですね。やはり、これから認知症というのは大きな問題になっていくと思いますので、今後の認知症の施策の展開について、お聞きしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"今後につきましては、そのサポーター研修を受けた方の中から、地域の中で活躍できる方をピックアップして、キャラバンメイトになっていただくということで、こちらはキャラバンメイト養成研修というのも開かれていますので、そういうところに参加をさせながら、それで、あと。","voiceIndex":8,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問・要望","question":"わかりました。２点目にまいります。生活保護費。この年は生活保護についていろいろと話題の多い年でしたよね。この問題の中で、品川区もいろいろ考えてきたと思いますけれども、生活保護の給付の適正化についてどのように施策を展開してきたのかということと、不正受給の実態について、お教えいただきたいと思います。","respondent":"竹田生活福祉課長","answer":"生活保護の２点についてのお尋ねです。どのように取り組んできたかですが、昨年３月に品川区就業センターが開設したことにより、受給者とともに私どもの指導員が就業センターまで同行することが可能になりましたので、確実に職業紹介に結びついております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問","question":"時間がないですけれども、８月１日から基準が引き下げられましたね。これについては本会議等々で質問がありましたけれども、今度、秋には申請手続を厳格化する生活保護法改正案と、生活困窮者向けの自立支援法が成立すると言われていますけれども、その動向がわかりましたら。","respondent":"竹田生活福祉課長","answer":"秋に国会に上程されて、審議される予定です。","voiceIndex":12,"id":"exchange-005"},{"speaker":"つる委員","kind":"質問","question":"１２６ページ自立支援サービス、１２７ページ障害者まつりなど、それから１２４ページ高齢福祉費、時間があれば１２５ページの熱中症等予防対策事業に行きたいと思います。１２６ページの自立支援サービスです。障害を持つ親の子育て支援の観点でお尋ねしたいと思います。居宅介護、重度訪問介護のサービス提供の中で、育児支援を受けられている方について、状況を教えてください。","respondent":"中山障害者福祉課長","answer":"今の自立支援サービスの介護人派遣のうち、育児支援サービスを受けられている方がいらっしゃるかというお尋ねですけれども、育児支援を実際に給付されている方が、およそ３名ほどいらっしゃいます。","voiceIndex":15,"id":"exchange-006"},{"speaker":"つる委員","kind":"質問","question":"３名ということで、ありがとうあります。この居宅介護、重度訪問介護の中で、子どもの世話に支援を受けられるという、今、対応していただいているこの趣旨の周知方法は、どういう形で行っているのか、教えてください。","respondent":"中山障害者福祉課長","answer":"実際の周知の方法ですが、障害者の方が、例えばこちらの区の窓口であるとか、あるいは生活支援センターのほうに困り感ということで、実際にご相談いただいた中で、どういったサービスを組み立てて生活を続けていくことができるかということを、相談の中でやっているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"意見","question":"という形で、積極的にそういったホームページで掲載だとか、また品川区独自のチラシをつくって、そういった方たちに事前に周知をするということも必要なのではないかと思います。なので、都道府県に対する通知ですけれども、その辺が品川区として掲示できるかどうかも含めて、また独自のチラシができるかどうかを含めて、この辺についてお考えをお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、例えば赤ちゃんを出産するという前準備の保健センターとの連携の中でも、そういったご相談をいただきながら、この６月に生まれたお子さんについても今まで対応してきたところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"次に行きます。１２７ページ、障害者まつりなどです。こうした契機を活かしたこの障害者まつり、福祉まつりとかいろいろな名称があると思いますが、難病患者とか希少疾病の患者団体などに、参加を促進するようにしたほうがいいのではないかと思いますけれども、これまでの参加実績だとか周知方法、この辺の現状を教えてください。","respondent":"中山障害者福祉課長","answer":"今までの実績として、難病患者の方の会が参加したということはございませんが、実行委員会形式でボランティアを含めて開催しているものですので、そういったお声があれば、ぜひこちらのほうにお声かけいただければと考えています。","voiceIndex":21,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"この間の「２４時間テレビ」でも、私もそうした方たちのダンスとかを見ましたけれども、ちょっと話が飛びますが、昨年の第４回定例会で、本当に全会派の皆様に全会一致で採択をしていただきました、あのウルトラ・オーファンドラッグ開発促進・支援のための法整備等を求める意見書の提出に関する請願、これは全会一致で採択をいただきました。これは要望的なことです。次に行きます。","respondent":"永尾高齢者福祉課長","answer":"耳の遠くなった方に対しての対応ですけれども、委員のご質問のシニアサインというのは、ちょっとわかっておりません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"なので、ちょっとこれは今現在ご認識がなかったということですが、リーダーの本も出版されているので、別にそういったところから研究をしていただくことも含めて、コミュニケーションツールとしては非常に有効ではないかということで、私は思っていますけれども、このシニアサイン、例えばご家庭で介護に従事されている方、今後そういった流れになっていくとは思いますけれども。","respondent":"永尾高齢者福祉課長","answer":"高齢者の方のコミュニケーションがとれないことによって、虐待につながったりするということで、区のほうでもいろいろな事業をやっているところですけれども、委員ご提案のシニアサインにつきましても、もうちょっとこちらのほうで調査いたしまして。","voiceIndex":25,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"ぜひ、よろしくお願いいたします。期間を空けて、状況をまたお教えいただければと思います。次に行きます。１２５ページ、熱中症等予防対策事業です。今年も暑い夏でありました。そうした中で、品川区としてもクールスポット、避暑シェルター、お休みどころというところでやっていただいておりますけれども、その周知方法はどういうふうにして取り組まれているか、教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"避暑シェルターですけれども、区内６２カ所に設置した避暑シェルターです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"この間、ちょっと世田谷区に用事があって行ったときに、世田谷区の施設に行きましたらば、世田谷区も同じような取り組みをやっていて、その地域ごとの、品川区で言うところの避暑シェルターに当たるもののマップをつくって、世田谷区は「せたがや涼風マップ」ということで地域別につくっているのですが、なかなか経費の問題もあると思いますが、この辺も含めた周知方法のお考えがもしあれば、教えてください。","respondent":"工藤総務課長","answer":"避暑シェルターのマップに関するご提案です。私どもも来年度に向けまして、どのような形で周知するかという部分は、先ほど申し上げましたホームページ、広報、のぼり等の周知に加えまして、どういった形で周知していくかは検討さていただきたいと考えています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな取り組みをやっていると思いますけれども、世田谷区のこういったマップもぜひ参考にしていただきたいと思います。ちょっと時間がありますので、１３５ページ、児童センター運営費に絡めて、全部の児童センターでは実施していないと思いますけれども、大井倉田児童センターでしたか、おもちゃの広場で、おもちゃで遊べる取り組みをやっていると思うのですが、その辺の状況を教えてください。","respondent":"伊崎子育て支援課長","answer":"おもちゃの広場ですが、大井倉田児童センターで毎週金曜日、午前１０時から１２時までやっております。それから、後地児童センターでも、毎週土曜日の１０時から２時半までという形で実施をしております。","voiceIndex":31,"id":"exchange-014"},{"speaker":"つる委員","kind":"提案","question":"ある自治体では「おもちゃ図書館」とかという言い方で、単純にお子さんに遊んでいただくだけではなくて、障害があるお子さんとか、健常のお子さんとかも含めて、いろいろな形で交流をしてもらったり、あとはそこにお医者さんに来てもらって、あとはいろいろな理学療法士とかがいろいろな相談業務をやっているとか、そういうことも絡めて取り組んでいるようなところもあるそうなので、そうしたことを含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"本日はこの民生費の中で、１２４ページの中ほどより少し下にあります、高齢者の趣味・健康づくり事業３９５万円余からの質問をいたします。シニアのためのいきいきガイドのパンフレットには、「健康な６５歳から健康で活動的な８５歳へ」とあります。１、好奇心を持つ。２、よく笑い、よく笑わせる。３、生きがいを持つ。４、自分を知り、健康観を持って生きる。お答えいただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"ただいまのシニアのためのいきいきガイドの理念の、健康な６５歳から健康で活動的な８５歳へのリーフレットの七つの項目のほうを読み上げていただきました。私ども、元気高齢者の方々には、このリーフレットをもとに、さまざまな事業への提案ということで行っているところです。","voiceIndex":35,"id":"exchange-016"},{"speaker":"木村委員","kind":"質問・要望","question":"そういう目で、高齢者の方々を見守っていただきたいと考えています。多分、これはひとり暮らし用の料理だと思いますけれども、男性が料理教室に参加するには、先ほど言いました１人用の自分の食べ物だと思いますけれども、つくること、それ以外に何か狙いがあるのかどうか。この料理教室を行うことによって何かを願っているのかどうか、言い方はちょっと変ですけれども、お答えいただけたらと思います。","respondent":"白鳥高齢者いきがい課長","answer":"同じ境遇の方がいらっしゃいますので、そういう方々と仲間づくり、交流に発展していっていただければという思いの中で、この事業を展開しています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"木村委員","kind":"質問・要望","question":"年齢を重ねていくことによって、いろいろな機能が衰えていきますけれども、少なからず本当に体の機能とか能力を低下させてしまうのです。気持ち的に前向きな人、そして明るい人ほど、元気に人生を楽しんでいるのではないかと私自身も感じていますが、皆様はどのようにそのことに対して捉えているか、お聞かせいただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"さまざまな事業に参加をしていただく。そのそれぞれの思いの中で、自分に合ったものに参加していただくということは、大変大切なことだろうと考えています。","voiceIndex":39,"id":"exchange-018"},{"speaker":"木村委員","kind":"意見","question":"高齢者はそのような環境になかなか出てこないというのか、特に男性はそういうところにはなかなか参加をしないと思いますけれども、女性のほうがほとんどそういう意味では活発的で、外出をすることは以前からもよく言われております。どのようにしたら、男性をこういうイベントやサークルなどに参加をさせることができるか、そういう秘策がありますか。何か考えているかどうか、お聞かせください。","respondent":"白鳥高齢者いきがい課長","answer":"大変難しい質問かと思いますけれども、やはり男性よりも女性のほうが圧倒的に積極性が見られる。私もさまざまな講座、教室の中でいろいろ拝見しますと、その中に男性がぽつんと入っている事業を見ますと大変寂しい思いもしています。","voiceIndex":41,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問・要望","question":"ぜひ、よろしくお願いいたします。次に、１２４ページの上から１１行目に、高齢者生きがい対策事業というものがあります。その高齢者クラブ連合会助成金と、その下にあります高齢者クラブ助成金。最初見たときに、何がどうかはちょっとわからなかったのですけれども、この違いを教えていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"ご説明をするに当たりまして、高齢者クラブのほうの会員クラブの助成金のほうからご説明させていただきたいと思います。現在、１１３クラブの会員約１万２,０００名ですけれども、それぞれの町会・自治会単位でもってこの高齢者クラブが結成されているところです。","voiceIndex":43,"id":"exchange-020"},{"speaker":"木村委員","kind":"意見","question":"先ほどお話がありましたが、約１万２,０００人弱ということですけれども、高齢者クラブ連合会というのは大変大きな団体になりますね。クラブ会員は会費を払って、体や脳の健康づくりは別にしても、ボランティア、社会奉仕まで行っているとは大変なことだと、頭の下がる思いでありますけれども、活動を通しての生きがいとは一体どのようなこととお考えになりますか。","respondent":"白鳥高齢者いきがい課長","answer":"独居高齢者の方々の見守りも一部のクラブでは行っているという、こういったところから、生きがいを見出しているのではないかと感じております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"区としても、高齢者の健康のためにも大変大事な事業だと思っています。本区は、各クラブの会員が精力的に活動できる環境づくりのような、こういう活動のためにも、助成の枠を広げるようなお考えがあるかどうか、お聞かせ願いたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"新たな会員を増やしていただくための強化月間となるものも、今年の１月から３月にかけて行ったところですけれども、そのような中で、それぞれが自助努力という形で、この組織の強化につながっているわけだと思うのですけれども。","voiceIndex":47,"id":"exchange-022"},{"speaker":"木村委員","kind":"質問・要望","question":"この高齢者クラブのボランティアの回数をいろいろとお聞きしましたところ、１００回未満、それから１,０００回を超えるようなクラブもあるということをお聞きしました。そして、１００回と１,０００回とでは大きな違いがありますけれども、この差というものはどういうところから出ているのか、お聞かせいただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"その差というご質問ですけれども、会員の規模が３０名から二百数十名にわたるものですので、その会員数によりまして、その活動、行動もごく限られてしまうという、ボランティアも同じことだと考えております。","voiceIndex":49,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、成果報告書の１３３ページの延長夜間保育について、それと１３２ページの家庭的保育事業（保育ママ）について、１３５ページの児童センター運営費について、それぞれお尋ねしたいと思います。この利用者数というのは多いと考えるべきなのでしょうか。それとも、それほど多くないと考えるべきなのでしょうか。区のご見解をお伺いしたいと思います。","respondent":"立川保育課長","answer":"第１点目のお尋ねですが、現在の延長保育の利用状況ですけれども、最近の傾向といたしましては、いわゆる７時半までの延長利用というのは増えている傾向にありますけれども、８時半ですとか１０時という長時間については減っているという現状があります。","voiceIndex":52,"id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今、課長のほうから、７時半過ぎに関しては減っているというご回答があったのですが、率直なところ、随分多いというのが私の感想です。このようないろいろご事情があって、非常に朝早くから夜遅くまで預けられているお子様に対して、保育園として、あるいは区として何か特別に配慮したり、それに寄り添う対応を特に考えたり、そのようなことはされているのでしょうか。","respondent":"立川保育課長","answer":"長時間お預かりしているお子様につきましては、やはり週末などには、ほかのお子様と比較しまして、疲れが出ているというようなことが子どもの様子でうかがえる場合がありますので、そうした場合には休む時間を多くしたり、そういった配慮をしていると聞いています。","voiceIndex":54,"id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１３２ページの家庭的保育事業（保育ママ）１億４１３万６,０７６円についてお伺いいたします。保育ママ制度は、待機児解消加速化プランでも、小規模な保育の一つとしまして、家庭的保育事業の普及促進がうたわれており、品川区でも当然今後増加していくものと思われますが、まず、保育ママ制度について、簡単にご説明をお願いいたします。","respondent":"今井制度改革・待機児童対策担当課長","answer":"家庭的保育事業の主な目的ですが、就労等で保育ができない保護者にかわって、保育資格および経験を有する保育ママが、ご自宅や借り上げしましたマンション等で保育を行うものです。","voiceIndex":56,"id":"exchange-026"},{"speaker":"鈴木（博）委員","kind":"質問","question":"家庭的保育において最も大きな問題は、保育される保育者の資質だと思いますが、保育ママを行う方というのは、どのような資格をお持ちの方がされるのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"資格ですが、保育士、教員、看護師、助産師または保健師のいずれかの資格を持つ方で、かつ所定の研修を終了された方を区のほうで認定いたしまして、保育ママとして保育に従事していただいております。","voiceIndex":58,"id":"exchange-027"},{"speaker":"鈴木（博）委員","kind":"質問","question":"保育士、看護師、それから保健師などの資格を持っている方が、保育ママで事業を展開したところ、あまりその資格者がいなかったので、現在は資格を持たない方でも、一定の研修をすれば保育ママ事業ができるということをちょっと調べたのですが、そうではないのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"家庭的保育事業は、国のほうで一定の基準を定めておりまして、国の基準ではそのような制度もありますが、品川区では平成２３年からの運用につきましては、今、申し上げました資格を持つ方という形でしています。","voiceIndex":60,"id":"exchange-028"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それで、品川区はまだ実際されている方が３名しかいないということだと思いますけれども、資格を持って家庭的保育、小規模保育を行うのは、事業所ではない場合は自分の自宅で行うということになると思うのですが、当然、後ろにつく支援保育所なんかの援助もあると思うのですが、やはり保育の質が非常に大切だと思いますが、特に保育ママの場合は。","respondent":"今井制度改革・待機児童対策担当課長","answer":"保育ママにつきましては、在宅型、そして事業所型とありますけれども、公立の保育園が連携保育所となりまして、保育内容、または保育だよりとか園だよりとかをお渡しするとともに、月に１回、園長経験者の指導員が巡回しておりまして、相談や指導に当たっております。","voiceIndex":62,"id":"exchange-029"},{"speaker":"鈴木（博）委員","kind":"質問","question":"国の施策もありまして、家庭的保育事業はこれからも拡大していくものと思われますが、やはりちょっと保育園に比べるとスモールサイズだということと、それから保育者の質の問題。最後に、成果報告書１３５ページの児童センター運営費１０億６,７５９万２,４６４円についてお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１２９ページの特別養護老人ホーム等整備費、１３３ページの保育園運営費にかかわって、特養ホームと認可保育園の整備計画を伺いたいと思います。特養ホームについてですけれども、今年３月の入所調整会議にかかった５８４人の中で、入所できた方は何人か伺います。そして、この５８４人の中で８７名は、要介護５ですが、この要介護５で入所できた方が何人か、伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、あと、４年後のところまでは計画がされておりますけれども、現在、国のほうの制度改正も検討されておりまして、第６期の事業計画に向けて、利用者のニーズも今後探っていきながら、また保険料への影響なども若干出てきますので、そういうところを総合した上で。","voiceIndex":66,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"５８４人中１３２人というご説明でしたけれども、恐らくこれは１年間だと思うのですね。そうではなくて、今年３月の入所調整会議にかかった５８４人のうち、この半年間で入所がかなったのは何人かということを改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、なぜ第２回の人数が多いかというところになるかと思いますけれども、かえで荘の大規模改修が終わりまして、そこで４０人増えておりますので、そこの部分と、あと退所者が結構多かったというところと、両方があります。","voiceIndex":68,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問","question":"いずれにしても、大体６００名ほどいつも申し込まれて、半年で入所できるのが大体６０人ほどという狭き門という状況が続いていると思います。そこで、旧みやこ荘跡地の次について、例えば品川区としては土地を購入して特養ホームをつくるという考えがあるのか、それともあわせてなのか、旧第一日野小学校、旧荏原第四中学校など、跡地に特養ホームをつくるという考えがあるのかを伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"高齢者の事業は特養ホームだけではないと思いますので、特養ホームのほかに、どういうセーフティネットの仕方があるかということも含めまして、これから考えていきたいと考えています。","voiceIndex":70,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問","question":"そこは違うのかどうか、改めて伺いたいと思います。旧みやこ荘跡についても需要の様子見と。これでは、今、入所を待っている方の状況を踏まえれば、一体どういうことなのだと私は思います。土地を購入して特養ホームをつくるという考えがあるのか、また、今、跡地となっている第一日野小学校や荏原第四中学校などに、老健施設や特養ホームをつくるという考えがあるのか、改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、入所をした上で、さらにどういうふうな利用の需要が出てくるかということの検討をしつつ、必要なものであれば、土地についても探していきたいと考えております。","voiceIndex":72,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"今後の高齢者人口を踏まえても、私はまだまだ足りないと思いますが、足りないという認識があるのかないのか、伺いたいと思います。続いて、保育園についても伺いたいのですけれども、今後の認可保育園の増設について、区立認可保育園を入れない理由について、区は将来的な財政負担という説明がありました。つまり、なぜ財政負担が区立認可保育園をつくらない理由なのか、ご説明いただきたいと思います。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長","answer":"特養ホームにつきましては、国のほうの制度改正も、今、検討されておりますので、そういうところも視野に入れながら、必要なものをつくっていきたいと考えております。区立保育園につきましては、今、一般財源化されていることもあり、また区民のいろいろなニーズに応えるためにも、区立だけではなく、私立のいろいろな力をお借りして運営していく必要があると考えております。","voiceIndex":74,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"特養ホームについては、今、待っている方々の家庭の厳しい状況をぜひよく見ていただいて、今から直ちに特養ホームの増設計画をつくることを強く求めておきたいと思います。認可保育園についてですけれども、よくわかりません。なぜ財政負担が区立認可保育園をつくらない理由なのかと伺いましたが、一般財源化されていることがなぜ理由になるのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"そういう中で、区も含めまして、今年度平成２５年度は区立もあけ、そして私立のほうも４園あけという形で、総合的に対策を進めております。以上の点から、区立、私立を問わず、認可保育園を中心とした対策を進めていくのは、考え方の基本です。","voiceIndex":77,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問・要望","question":"すみません。「ない」とは言っていないとの説明ですが、先日の部長の答弁は、区立の認可保育園の増設を長期基本計画の素案に記載する考えはございませんと述べているわけです。つまり、これから区立認可保育園の増設を素案に記載する考えがあるということなのか、ないということなのか。私はぜひ、待機児童解消のためにもつくっていただきたいと思いますが、ご説明いただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"先日もご答弁申し上げましたし、今、課長のほうからもるる申し上げたとおりでありますが、私どもとしましては、区立の幼保一体施設については建設を進めてまいりましたし、今後も認定こども園等は検討いたしますが。","voiceIndex":80,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"成果報告書の１２２ページふれあい作業所、１３３ページ一日保育士体験事業と延長夜間保育についてお伺いします。先ほど、延長夜間保育のことについては別の委員からも質問がありましたけれども、改めてここ数年、この何年間かで結構ですけれども、２時間以上の延長保育を開設していた園というのは大体何園ぐらい、つまり８時半以降の延長保育を開設した園というのは、大体何園ぐらいあったでしょうか。","respondent":"立川保育課長","answer":"ここ数年の開設ですが、私立につきましては、８時半ということで開設をしていただいております。公立につきましては、７時半までということで開設しております。","voiceIndex":83,"id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"１時間延長は増えておりますけれども、１時間延長は７時半までですので、そんなに遅い時間ではないですけれども、２時間や３時間という遅い時間帯の延長夜間保育の利用者は減っているという状況があるということでしたけれども、この変化について、区としてはどのように分析していらっしゃるでしょうか。","respondent":"立川保育課長","answer":"最近の傾向ですが、平成２３年の東日本大震災の影響により、その後、延長夜間保育の利用者というのが率にしてかなり減ったという時期がございました。そういった意味で、最近の減少傾向というのは、やはり働き方に関して保護者の方の意識が変わったと認識しております。","voiceIndex":87,"id":"exchange-039"},{"speaker":"沢田委員","kind":"質問","question":"そういった保護者の方の意識も変わってきた。企業側の理解も深まってきたのかと思いますけれども、景気がまだまだ大変よくない状況の中で、これから遅い時間帯の、特に９時以降といった時間の延長夜間保育について、区としてどのように今後は考えられているのか、教えてください。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"小学校に入学いたしますと、やはりそれほど長時間預ってくれるところというのは、現在、区としては実施していないということもあります。当初始めたときに、利用者お１人お１人に対して各園長が、要するにその必要性についてきちんと説明をして、要するにこういう範囲で利用すべきだということをお約束しながら使っていただいていたのですね。","voiceIndex":89,"id":"exchange-040"},{"speaker":"沢田委員","kind":"質問・要望","question":"あまり時間がないので、一日保育士体験事業のことでお伺いしますけれども、この事業もすごく大変評価が高くて、すばらしい事業だということで、最初、これはどこでもやっているのかと思ったら、品川区とか、ごく限られた自治体でしかこの事業が行われていないということですけれども、やはり保護者が保育を体験するということで、普段自分の子どもがどういう生活をしているのかとか、また保育士側にも。","respondent":"立川保育課長","answer":"この中身ですが、保育士体験をしていただくときに、保護者の方に一緒に給食を食べていただきます。その経費です。","voiceIndex":92,"id":"exchange-041"},{"speaker":"沢田委員","kind":"質問","question":"その給食ということで、この事業は、今、無料で行っていらっしゃるのかと思いますけれども、やはり年々増加している、また、お互いにとっていい事業ということで、今回１,０００人ぐらいということでしたけれども、せめて給食費ぐらいは、そうすると１人４００円ぐらいですけれども、保護者にとってもいい事業ですので、ぜひそういったことも今後考えられたらどうかと思いますけれども。","respondent":"立川保育課長","answer":"今後とも、給食費につきましては区のほうで負担していきたいと考えております。","voiceIndex":94,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"ちょっと時間がないので、もう一点目です。品川区でもいろいろな障害者就労支援ということでされておりますけれども、こういった野球ボールの再生とか、こういった新たな事業の取り組みについてはどうお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"障害者の方にとっての就労の場というのは、経済的な自立に向けた重要な施策だと考えています。なかなかいい中身というのが見つからないところですので、ご提案の件につきましては研究させていただければと考えています。","voiceIndex":96,"id":"exchange-043"},{"speaker":"塚本委員","kind":"質問","question":"この精神障害者地域生活支援センター、いわゆる通称「たいむ」という名前で、西五反田に事業所というか通所施設があるかと思いますけれども、事務事業概要を見ると、ここで相談員体制ということで、常勤で４名、非常勤が２名というようなことで記載されておりますが、実施されている事業は相談だけではないと思いますので、されている事業の内容とその利用状況。","respondent":"中山障害者福祉課長","answer":"平成２４年度の実績ですが、基本相談支援ということで４,４４０件ほどの相談を受けているところです。地域活動支援センター事業のほうでは、利用者が延べ人数ですけれども７,０４７名ということで、大変活用されているところです。","voiceIndex":99,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問","question":"今、大変に活発にというか、キャパシティ一杯一杯でご利用されているというお話を伺いしましたけれども、その精神障害をお持ちの方々からのお声では、やはりなかなか、このたいむ１カ所しか、今、品川区内にはこういった居場所というのですか、普通に日常生活するような場所としてはほかにないということで、場所的にも１カ所であるし、こういった形で非常に活動が盛んなので。","respondent":"中山障害者福祉課長","answer":"今、区内に３カ所、そういう形で居場所支援ということで行っておりますので、その利用の人数の推移を見ながら、今後考えていければと思っているところです。","voiceIndex":101,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問","question":"平成２４年度に児童センターのあり方の検討会という報告が文教委員会のほうにされていて、その中を少し読んでみますと、いわゆる最も中心的な事業でやられているものの中で、親子のひろばというのを各センターでやられているかと思いますが、これが利用に当たって、いわゆるつどい形式、別に定員とか定めないで誰でもいつでもいらっしゃいというつどい形式のものと。","respondent":"伊崎子育て支援課長","answer":"幼児クラブのお話ということでよろしいでしょうか。幼児クラブにつきましてはご登録をいただいて、ご利用いただいております。","voiceIndex":103,"id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"利用者ニーズの運営効率、子ども自身への影響など、これからの検討というようなことで書かれているのですけれども、これは自主グループだけではないのかと私は認識したのですが、それは、自主グループだけということでよろしいのでしょうか。","respondent":"伊崎子育て支援課長","answer":"失礼いたしました。親の子育て支援をする自主グループと、あとチャイルドステーションとしまして、ご登録をいただきご利用をいただくという仕組みもとってあります。","voiceIndex":105,"id":"exchange-047"},{"speaker":"塚本委員","kind":"質問","question":"それで、その狙いですね。登録制という形にした狙いというか背景というのをお伺いしたいと思います。","respondent":"伊崎子育て支援課長","answer":"チャイルドステーション事業ということでさまざまな講座をやるときには、登録者の方にご案内をしておりますし、ご相談をお受けするようにもしております。","voiceIndex":107,"id":"exchange-048"},{"speaker":"塚本委員","kind":"質問","question":"今、ご説明をいただいたのですけれども、いわゆるチャイルドステーションという事業で登録制ということになっているということなので、登録をしていない方は利用できないのかと理解をしてしまうのですけれども、この事業の内容から見て、やっているときに来た人は誰でも受け付けるというような性格に見えるのですけれども、その辺のそごというのか。","respondent":"伊崎子育て支援課長","answer":"ただ、チャイルドステーションにつきましては、チャイルドステーション事業講座という形でやっているものにつきましては、ご登録の方のみのご利用になります。","voiceIndex":109,"id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"ただ、近年このティーンズプラザの利用者が非常に減少しているということなので、そうすると、この１０代の方たちはどこに行ってしまったのだろうというのを一瞬思ったりもするのですけれども、今、この現状について、１０代の方のこのティーンズプラザの利用の状況について、また、１０代の方たちがどういうところで、今、生活をしているというか。","respondent":"伊崎子育て支援課長","answer":"ティーンズタイムの利用者につきましては、特に大きく減少しているという傾向は、平成２４年度につきましては見られないところではありますので、ご利用いただく中学・高校生はそれぞれ目的があって、例えばバンド活動をやりたいとか。","voiceIndex":111,"id":"exchange-050"},{"speaker":"塚本委員","kind":"提案","question":"そうすると、ここでは一つの提案として、ティーンズタイム、夜の時間帯に児童センターを開所するので人員がそちらにとられるということで、午前中の子育ての事業について人員が手薄になるということで、そちらのティーンズタイムのほうの人員が、午前中、昼間のほうに再配置みたいなことを検討してもいいのではないかということが書かれておりますけれども、これについては、そういう意味では、今。","respondent":"伊崎子育て支援課長","answer":"ティーンズプラザを実施している館につきましては、ほかの館よりも１人多く職員を配置しておりまして、シフトを組む形で、それぞれの時間の事業に対応しております。","voiceIndex":113,"id":"exchange-051"},{"speaker":"塚本委員","kind":"質問","question":"わかりました。了解いたしました。そういったことを未然に防ぐために、例えば１カ月、２カ月という形で死亡されたままになれば、銀行の生活保護の通帳に全くの預金の出金が起こらないはずなので、そういったものを見ることで、銀行側からの情報提供みたいなものをして、そういう見守りみたいなことが可能かどうかということを、最後にちょっとお伺いしたいと思います。","respondent":"竹田生活福祉課長","answer":"ご提案の銀行でのチェックということですが、今後研究してまいります。","voiceIndex":115,"id":"exchange-052"},{"speaker":"高橋委員","kind":"質問","question":"職員の給与が６１人で５億３,６３０万円で、この６１人以外の非常勤職員の方も含めた生活保護行政に携わっている職員の方々の、安全確保についてお伺いします。今年に宝塚市で、火炎瓶による火災が発生したと。品川児童相談所では、昨年、防犯カメラを設置していると伺っています。この検討結果について、どのようになされたのか、お伺いいたします。","respondent":"竹田生活福祉課長","answer":"防犯カメラについては、本年６月１日から相談室に設置しまして、問題なく順調に運用しています。警察に勤務経験のある方２名を、生活福祉支援員という名称の非常勤職員として採用しています。","voiceIndex":118,"id":"exchange-053"},{"speaker":"高橋委員","kind":"確認","question":"一番最前線で日々ご苦労されていると思いますが、報道によると、堺市では家庭訪問した女性の職員の方が、突然玄関の鍵をかけられて暴行をくらいそうになった、あるいは男性職員が別の受給者から刃物などで脅かされたり顔を殴られたということがあったため、緊急時に居場所確認ができるＧＰＳを備えた携帯電話を配備したということを伺っています。具体的にお願いいたします。","respondent":"竹田生活福祉課長","answer":"ケースワーカーの定数上の数ですが、４４人となっております。生活福祉支援員の主な業務ですが、ケースワーカーが家庭訪問する際の同行です。訪問時の役割としましては、ケースワーカーが適切な相談・助言・指導ができるための安全の確保です。","voiceIndex":120,"id":"exchange-054"},{"speaker":"高橋委員","kind":"意見","question":"家庭訪問時に同行する、職員の方の安全が確保されているということで、警察官ＯＢの方は大変なご苦労だと思いますが、未然の防止、引き続き配置をお願いいたします。配置していただいてから時間がたっているわけですが、配置後の実績、このようなことがあって、それが防げたというようなことがありましたら、最後にお尋ねします。","respondent":"竹田生活福祉課長","answer":"４月から９月までの訪問実績ですが、約３０件です。未然に防げたものということですが、薬の服用を忘れていた受給者がいまして、ケースワーカーを両手で突き飛ばすということが家庭訪問でありました。その際は生活福祉支援員が助けたという事例もあります。","voiceIndex":122,"id":"exchange-055"},{"speaker":"高橋委員","kind":"意見","question":"引き続き、よろしくお願いします。１２９ページの重症心身障害者通所施設の運営費です。区長もオープニングセレモニーで挨拶をされておりました。この負担軽減の支援ですが、大変意義のあるものなのですが、通所事業で延べ２０９人とありますが、利用されている方の実人数が何人いらっしゃるかということ、１日どれぐらいの方が利用されているかということをお尋ねいたします。","respondent":"中山障害者福祉課長","answer":"重症心身障害者通所事業所ピッコロについてのお尋ねです。こちら、１日の定員が５名ということになっております。現在ですけれども、６名の登録者の方がいらっしゃいまして、大体１日最大で３名ぐらいの方がお越しいただいていることになっております。","voiceIndex":124,"id":"exchange-056"},{"speaker":"高橋委員","kind":"質問","question":"５名のところ、１日３名の方がご利用になっているということです。もちろん、いろいろ法律上や人的な措置など、問題が出てくると思いますけれども、まだ都の補助事業ということもあると思うのですが、今、お話があったような空けておくということで、施設の有効利用も考え、そして就学前のお子さんと保護者のためのことも考えて、その可能性についてはいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"昨年度、開始に当たりましては未就学児の方を対象としていたのですけれども、今年の７月から要綱改正をいたしまして、夏休みに向けまして、学齢児の方も対象にしたところです。","voiceIndex":126,"id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"区長の方針の中で、最重点課題は防災ですけれども、そのほかの三つの柱として、緊急経済対策、そして総合的な待機児童対策、高齢期の住まいと安心対策という形で出ておりますが、各ページの質問をする前に、本日、二つのそういう意味の事業部の方が大半を占めておりますので、まず事業部として、区長のこういう思いに対しての決意を教えてください。","respondent":"今井制度改革・待機児童対策担当課長、永尾高齢者福祉課長","answer":"約２,５００人の拡大の中で、まだ待機児童の解消できない部分がありますので、保育需要の高どまりも踏まえて、今後とも積極的に総合的に対策を進めていく所存です。高齢者につきましても、高齢者人口が伸びておりまして、今年度は高齢化率が２０.６％になり、今後も団塊世代の方の高齢化が進むことから、どんどん増えてくると認識しております。","voiceIndex":135,"id":"exchange-058"},{"speaker":"藤原委員","kind":"質問","question":"この中で、合算すると１,８００万円になりますが、まず、なぜ分けているのか、それぞれの決算と中身とともに教えてください。それと、１３５ページ、すくすく赤ちゃん訪問事業ですが、保健センターで訪問できなかった分を対応すると思いますが、子育て支援課では、誰がという意味なのですけれども、どういうふうに訪問しているのか、教えてください。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長、伊崎子育て支援課長、立川保育課長","answer":"成年後見センターの件ですけれども、１２１ページの成年後見制度利用支援事業につきましては。事業所型につきましては、例えばＮＰＯ法人等が保育ママを複数雇用して実施する事業でございまして、こちらは今後。子育て支援課では、保健センターで新生児訪問として訪問ができなかったケースや、訪問してもいない場合のケースにつきまして。大規模改修の基準ですが、耐用年数というものを約５０年と設定いたしまして、現在では年２園から３園、計画的に実施しています。","voiceIndex":138,"id":"exchange-059"},{"speaker":"藤原委員","kind":"質問","question":"それと、これも改めてですが、建替えの件ですけれども、今後建替えの必要がある園も出てくると思いますが、区有施設の有効利用という観点からすると、単純に１園１園改築していくわけでもないと思いますけれども、一方で待機児童対策もしばらく続けていかないとならないではないですか。その実態をお伺いしたいのと、それと決算額を３０件で単純に割ると、１件当たり約１３万円強となりますよね。","respondent":"永尾高齢者福祉課長、今井制度改革・待機児童対策担当課長、立川保育課長、伊崎子育て支援課長","answer":"ちょっと説明が不十分で申しわけありませんでした。ですので、区のほうで条例を定めまして、基準等を定めまして、今後も展開をしていきたいと考えております。今後の改築計画というご質問ですが、こちらにつきましては、現在進めております待機児童対策と。","voiceIndex":143,"id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"すくすく赤ちゃん訪問事業ですけれども、まず、今の説明はわかったのですけれども、そういうことなので１３万円かかってもしようがありませんという形で、ちょっと金額にこだわってしまうのですけれども、もうちょっと明確な答弁をいただきたいのと、あと、保育園の改修という意味では、課長の答弁を伺っていても想像できないのです。","respondent":"伊崎子育て支援課長、立川保育課長","answer":"説明が不足していて申しわけございません。今後につきましては、現状待機児童対策のほうを中心にしておりますので、待機児童対策につきましては、今後１０年ぐらいは入所希望のお子様の高どまりが続いておりますので、そうした待機児童の状況を見まして。","voiceIndex":148,"id":"exchange-061"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長はめいっぱい答弁してくださっていると考えていますので、これで、わかりました。最後にここは明確な答弁をいただきたいのですけれども、児童相談所ですけれども、私、一般質問でさせていただきましたが、区長会は特別区への移管を積極的に進めているという答弁がありました。現在の状況と、移管に当たっての決意を改めてお伺いします。","respondent":"伊崎子育て支援課長","answer":"区といたしましては、所管課長会で、今、さまざま移管に向けてのロードマップ等の検討をしておりまして、そちらをあわせて、区としては積極的に移管を進めていきたいという意思があります。","voiceIndex":151,"id":"exchange-062"},{"speaker":"渡部委員","kind":"質問・要望","question":"一つ気になっていたのが、さまざまな形で高齢者クラブというところに助成して、地域の高齢者の方々が活動なさっている中で、果たして、品川区内の全町会が何らかの形で網羅されているのかというところが気になっていますので、この辺を教えていただきたいのと、あと、やはり高齢者クラブは任意団体ですし、その地域でグループが集まって、仲のいいグループですよ。","respondent":"白鳥高齢者いきがい課長","answer":"ただいま、高齢者クラブの町会とそれに伴うクラブ数の割合のご質問が１点、それから、未加入の単位クラブがあるかどうかという二つの質問をいただきました。","voiceIndex":154,"id":"exchange-063"},{"speaker":"渡部委員","kind":"質問・要望","question":"今の数字を伺っている限りですと、その町会の中で高齢者クラブをお持ちでない町会というのが多々あるとまず思ったのですが、今、いろいろさまざまな状況の中で打ち合わせ等をなさっているということですが、品川区内全域でこういうクラブ活動、品川区高齢者クラブ連合会の皆様方も頑張っていらっしゃって、さまざまな活動をされている。","respondent":"白鳥高齢者いきがい課長","answer":"そういった中で、いろいろとお隣の地域の方々には、こういったクラブを結成したらどうかというような働きかけも必要ではないかと考えています。そのための支援につきましては、区としてもさまざまな相談を行っていきたいと考えています。","voiceIndex":156,"id":"exchange-064"},{"speaker":"渡部委員","kind":"確認","question":"たしか初年度から３年間の１０万円が終わるときに、いろいろな町会から何とかしてくれと。ですので、本当にかかる経費等、その町会によって違うと思いますが、さまざまな観点で研究していただいて、何らかの形で町会がその事業を継続できるような仕組みづくりにお手伝いいただければと思いますので、それだけちょっと確認したかったので、よろしくお願いいたします。１カ所スタートを切りました。","respondent":"永尾高齢者福祉課長","answer":"先ほどの町会・自治会の見守りもそうですし、こういう民間の企業の見守りも同じになります。今後はこの民間企業、いろいろな企業があると思いますので、そことの協力を願いながら進めていきたいと考えています。","voiceIndex":160,"id":"exchange-065"},{"speaker":"渡部委員","kind":"質問・要望","question":"１３５ページ、児童センターのことを聞きます。児童センターのティーンズタイムの時間帯が変更になって、高校生から「７時に出されちゃうんだよね」なんていう話を、当然７時までになったから帰されてしまいますけれども、実際にどうでしょうか。８時が７時になった影響というのは、今の時点で何か入っているような話ですとか、もうそれに慣れているから大丈夫なのか、何か声があったら教えてください。","respondent":"伊崎子育て支援課長","answer":"ティーンズタイムの時間につきましては、今年の６月から変更しております。","voiceIndex":162,"id":"exchange-066"},{"speaker":"渡部委員","kind":"質問","question":"そうですか。難しいですね。僕は７時でいいと思っているのですけれども、そういう声もあるのかと思って聞いてたものですから、ちょっと質問させていただいたのですけれども。その児童センターです。","respondent":"伊崎子育て支援課長","answer":"全部で２５館あります。こちらの児童センターの将来的なあり方につきましては、昨年度いたしましたあり方検討会の中で、将来的な数について一部触れてはおりますけれども、ただ、今現在は特に数を統合させるとかいったところまでは考えてはおりません。","voiceIndex":164,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問・要望","question":"子どもたち、学校へ行きづらいといいましょうか、だけど児童センターには行ける、職員の方々とお話をして元気になってというような話も聞きますので、この体制のまま頑張って続けていただきたいのですが、あと、時間がなくなってしまったのですけれども、児童センターと、今回すまいるスクールの所管が変わって、さまざまな活動をしていくと思っていたのですけれども、いまだそれが全く見えてこない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":166,"id":"exchange-068"},{"speaker":"こんの委員","kind":"質問・要望","question":"私のほうからは、１３０ページの子育て支援事業の中の、子育て支援ネットワーク講習、そして時間があれば、１２７ページの杖の交付についてお伺いします。そこで、まずこの二つの事業の目的など事業の概要と、区民の方への広報の仕方をお知らせいただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"ネットワーク交流につきましては、特にお子さんの年齢は制限をしておりませんで、保護者の方、あるいは興味のある方につきましてご参加いただき、自主的に交流を持っていただくことで、地域として子育てを支えていく土台をつくっていきたいと考えて設定しております。","voiceIndex":168,"id":"exchange-069"},{"speaker":"こんの委員","kind":"質問","question":"そうすると、では、この事業の決算額からちょっと聞きたいと思いますけれども、当初予算でいきますと１１７万７,０００円という予算に対して、決算額は９０万７,５５２円という減額となっているわけですけれども、この差異についてお聞きしたいのと、ここ数年の参加者の傾向、またこの事業の評価をどうされて、どのように評価しているのか、お聞かせください。","respondent":"伊崎子育て支援課長","answer":"決算額ですが、こちらの経費につきましては、託児があった場合の保育ボランティアの経費を多くに取ってあります。ですので、お申し込みが見込みよりも少なかったということで減額となっております。","voiceIndex":170,"id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"差異はわかりました。そこで、そのお母さんたちも、この悩みについて学ぶ機会があれば学びたいという思いはありますということだったのですね。もっと広くお母さんたちに家庭へのメッセージ・支援として、もっと広いところで、今、定員が１カ所３０名から４０名と、年１回という講習もありますので、これをもっと展開していくべきではないかと考えておりますけれども、いかがでしょうか。","respondent":"伊崎子育て支援課長","answer":"現在のところは定員３０名程度でやっておりますので、これは事業の実施上の講師の都合とか、会場の都合等々ございまして、こういった形で実施しております。こちらが拡大できるかどうかについてはさまざまな課題がありますので、前向きに検討していきたいと考えております。","voiceIndex":174,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問","question":"今年度もすごくいい講座なのですよね。年に１回講演会を設けましょうというのがあるのですが、こういった中で、やはり講師派遣もなかなかお母さんたちも苦慮されているようですので、教育委員会と連携して行うとか、そういった方面を考えられるとか、家庭教育学級、お母さんたちがご自分たちでされようとするところへ働きかけるというのはいかがでしょうか。","respondent":"伊崎子育て支援課長","answer":"こちらのチラシのほうは、学校を通じてお配りしているということもございまして、保護者の方は当然ご存じのものです。ＰＴＡの活動につきましては、それぞれのＰＴＡの独自の考えがあると思いますので、必要であれば、こちらから講師のご紹介などはしていきたいと思います。","voiceIndex":176,"id":"exchange-072"},{"speaker":"こんの委員","kind":"質問・要望","question":"ですので、もう少しお母さんたちからというよりは、区として親育ち、親教育ということが大事だという施策もある中ですので、こういったことは一講習で、聞きたい方、関心のある方だけではなくて、もっと働きかけをする必要があるのではないかと考えていますので、先ほどご答弁いただきましたけれども、前向きな検討ということですので、今後、ぜひよろしくご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-073"},{"speaker":"向委員","kind":"質問","question":"そういった中から、この品川区としては、どういった形で対応されているのかというのをお伺いしたいのですけれども、まず、海外療養費の請求の仕組み、海外の病院にかかったときに、領収書とか診療内容の証明書などを何とかして持ってきていただいて、窓口でそれを精査していくということになると思いますけれども、このあたりで気をつけていることとか、そのあたり。","respondent":"間部国保医療年金課長","answer":"その申請日に当たりまして、確実に海外に行かれていたかどうか、このようなチェック。それと委員からもお話がありましたけれども、現地で発行された領収書やそれにかわるもの等のチェックをしています。","voiceIndex":180,"id":"exchange-074"},{"speaker":"向委員","kind":"質問","question":"これまでに発覚したそういった不正受給については、翻訳の人もすぐに大使館からきちんとそういった身元が証明された人でなければならないとか、そういうことではなかったかと私は記憶しているのですけれども、そういった大事な書類、現地から取り寄せなければいけない、現地で書いてもらわなければいけない、そういった領収書とかその他診療内容の翻訳というのは、今。","respondent":"間部国保医療年金課長","answer":"ですから、これは２３区一括して、東京都とか国保連に働きかけて、そういうような海外療養費の業務を委託できないかということも現在検討を進めているところです。","voiceIndex":182,"id":"exchange-075"},{"speaker":"向委員","kind":"質問","question":"件数としては、東京都内とかでもそんなに多くないかもしれないですが、実際、額としては、１回こういうことが起こるとかなりの額になります。しかも相手側の国も受け取ってくれないというのがよくありますけれども、こういった領収書のたぐいも大使館のお墨付きとか、そういうのは、今、されているのでしょうか。","respondent":"間部国保医療年金課長","answer":"ただいまのところ、お墨付きは必要はないということで、処理しています。","voiceIndex":184,"id":"exchange-076"},{"speaker":"向委員","kind":"意見","question":"わかりました。同じように療養給付等の中で適正化を図るということで、もう一つお尋ねしたいのが、第三者行為求償事務について、ページ数で言うと国保だと成果報告書の１８９ページ、後期高齢者医療でしたら２０４ページ、介護保険だと２１７ページにちょこちょこと各事務について金額も載っております。","respondent":"間部国保医療年金課長","answer":"ただ、これで一番多いのは交通事故ですが、今、委員もご指摘いただきましたけれども、ほとんどの方は保険に入られておりますので、保険会社と本人の過失割合に応じて、後ほど確定した後。","voiceIndex":186,"id":"exchange-077"},{"speaker":"向委員","kind":"質問","question":"わかりやすい説明、ありがとうあります。品川区でこういった広報の主な形態、どういうふうに呼びかけをして、早目の事務対応につなげているかを教えてください。","respondent":"間部国保医療年金課長","answer":"この事故が起きたときの対応ですが、まず、保険者である私どもに一報をいただければ、そのまま保険証を使っていただいて構いませんという形になってあります。そうすると、ご本人は窓口で３割負担で済みます。","voiceIndex":188,"id":"exchange-078"},{"speaker":"向委員","kind":"質問・要望","question":"それに加えて、こういった事務を担当されている方がいらっしゃると思います。国保に関して、介護保険、後期高齢者医療、いずれも担当されている職員の方は区独自の方なのか、それとも過去に損保会社とか法律的には何かしら資格を持っている方とか、そういった資質といいますか、どういった方が担当されているのか、教えてください。","respondent":"間部国保医療年金課長","answer":"ただ、この点の今後もスキルアップを図って職員でやっていくのがいいのか、費用がかかるわけですが委託がいいのか、そういう点は随時検討してまいりたいと思います。","voiceIndex":190,"id":"exchange-079"},{"speaker":"向委員","kind":"質問","question":"わかりました。そうですね。専門的な知識、交渉の技術も本当に必要で、１件１件対応するにも難儀なことは大変推測余りあるぐらいですが、そういった中で、普通に交通事故を起こしたときもそうですけれども、やはり保険会社の方は本当にプロですから、症状を早目に固定されてしまう、要はまだはっきりと後遺症がどれくらい出てくるか、まだ時間が経過しないとわからないことも交通事故は多いですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私は、成果報告書の１２５ページのひとり暮らし高齢者についてお聞きしたいと思いますけれども、この緊急通報システム、また自動消火装置、電磁調理器等の利用数というか設置数、緊急通報システムは、支え愛・ほっとステーション事業のほうのも合わせて、それぞれ一緒に教えていただきたいのと、あとひとり暮らし高齢者がどれだけ区内にいるのかという人数を教えてください。","respondent":"永尾高齢者福祉課長","answer":"それで、もう一つ調査をしておりまして、７０歳以上と６５歳以上の人だけで構成されている方、なおかつ周囲５００メートルに二親等以内の親族がいない世帯ということで、高齢者のみの世帯ということで、１万９７４人となっております。","voiceIndex":194,"id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問","question":"この自動消火装置と電磁調理器の設置件数がとても少ないと思うのです。この案内、こういうものですよというパンフレット的なものもいただいたのですけれども、ちょっと分かりづらいかとも思うのです。ＰＲというか周知というか、これだけまだ数が少ないというのは、区はどういうふうに考えているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"こちらの設置については、ケアマネジャーを通じてご相談に応じるという場合が非常に多くなっています。","voiceIndex":196,"id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それとあと、ケアマネジャーの方は、皆様こういうものがあるということはきちんと周知されて知っているのでしょうか。それで、区内の消防署の方からも、この自動消火装置は、こんなにいいものがあったのかと、これはどんどん普及させていくべきだというような声もいただいているのですね。ですので、どんどんＰＲの強化などを進めていっていただきたいと思いますが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、確かに件数的には非常に少ないという印象はありますので、これからこのパンフレット等については、また考えていきたいと思っています。","voiceIndex":198,"id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ、お願いします。それで、あと地域見守りネットワーク事業のところで、孤立死を未然に防ぐということで、近隣コミュニティの再生などを重視してということでつくられていますけれども、平成２４年度がこの助成団体が２８団体ということですけれども、これは町会・自治会を中心にということですけれども、内訳をちょっと教えてください。","respondent":"永尾高齢者福祉課長","answer":"町会と自治会のそれぞれの内訳というのは、今、すぐに数えられないのですけれども、もう少しお時間いただきたいと思います。","voiceIndex":200,"id":"exchange-084","title":"町会・自治会支援"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで孤立死を未然に防ぐということで、東京都監察医務院調べで、平成２４年度の孤立死亡数２９７人と出ていまして、７割が６０歳以上。孤立していく原因はさまざまありますけれども、そうやって地域で見守って助け合ってというのもあるのですけれども、区として孤立していく原因は主にどこにあるとお考えでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういう方に対しては、やはり本人の意向もありますけれども、民生委員や町会の方のご協力も得ながら、見守りの関係をつくっていきたいと考えているところです。","voiceIndex":202,"id":"exchange-085"},{"speaker":"石田（ち）委員","kind":"質問","question":"サービスにつながっていればとか、認定を受けていない、また事業に参加していない。何でそうなっているのかというところだと思うのですね。高齢者の社会的孤立が問題になって深刻になっていく中で、港区、江東区、新宿区などでは、実態調査の中から課題を出して対策を打つということを始めているのです。ですので、実態調査等々、行政が入っていくべきだと思いますけれども、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"そういうものも通しながら、孤立しがちな高齢者を確認して、対応していきたいと考えております。それと、先ほど地域見守りネットワークの自治会と地域見守りの件数の内訳ですけれども、自治会が１１団体で町会が１３団体となっております。","voiceIndex":204,"id":"exchange-086"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう時間がないですけれども、この緊急通報システム、こういったなかなか外に出られない方の命を守るというところには有効だと思いますので、ぜひ無料化を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"この事業、あらあらは把握できているのですが、改めて目的、内容、対象と、定員というのでしょうか、決算書では延べの人数と決算額が出ているのですが、延べではなくて定員があるのか、そして、このサービスを受けた方が何人なのか、そのあと回数がわかれば、１回当たりのもろもろ含めての経費的なものが１人当たり幾らなのかがわかれば教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"そのような中で、ひとり暮らしの方が中心ということになりますけれども、外出を習慣化することによりまして、そこに皆様で温かい食事を召し上がっていただく。そういう中で交流の輪も広げていきたいということで、実施をしているものです。","voiceIndex":208,"id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問","question":"それと教室終了後、教室終了後というのは、この事業自体は、僕はこれからも発展していってほしいという前提で伺います。そういう意味では、大もとの外出習慣がままならない方というのは、本来というか、理想とすべき対象者というのはどういう位置づけなのでしょうか。それで、現状でまず、段階的にこうしているというのがわかれば教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"対象の年齢ですけれども、おおむね６５歳以上の方で、この会場に自力でお越しいただける方。","voiceIndex":210,"id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問","question":"ありがとうございました。そうすると、恐らく民生委員との取っかかり、きっかけがある方が、まず、今は参加できている。今後を見据えたときに、定員、受け入れの問題もあります。ここから問うのは、これまでの検討だとか、今後こういうことを考えているみたいな場の提供という意味と、対象者、今後こう広げていきたいのだというような中長期を含めた目標を教えてください。","respondent":"白鳥高齢者いきがい課長","answer":"そういう中では、定員につきましては１５名から２０名程度が、１会場当たりの定員だと思っているところですが、今現在行っている南品川、東品川、それと大井林町の東大井ですので、各地区にバランスよく展開をしていけたら理想だと考えていますし。","voiceIndex":212,"id":"exchange-090"},{"speaker":"渡辺委員","kind":"質問","question":"ありがとうございました。今後拡大すべきというのは、ものすごく感じています。そうしたときに、混雑時のランチタイム、例えば１２時から１３時は避けていただいたとすれば、ゆったりとあるいは店主とお話ができる。あるいは、どうですか、また来てくださいとか、これこそまさに、政策的な理念に一致すると思いますので、商店街支援、地元の食事処、あるいは喫茶店等の活用というのはいかがでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"ただいま、委員からご指摘、ご提案をいただきました内容につきましては、まさに、この事業の目的でありますそのものだと私も認識していますので、今後、商店街連合会、あるいはさまざまな関係機関とのかかわりを、もう少し整理しながら、研究しながら。","voiceIndex":214,"id":"exchange-091"},{"speaker":"山元委員","kind":"質問・要望","question":"私からは１２６ページの自立支援サービスの中の同行援護、次に隣の１２７ページ、地域生活の支援の中の日常生活用具給付、時間があれば、次の１２８ページ、マッサージサービス経費についてお伺いしたいと思います。初めに、１２６ページの同行援護につきましてお伺いしたいと思います。大雑把でいいのですけれども、実際どのように施行されているのか、この辺を教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"同行援護についてのお尋ねですが、平成２３年度までは、隣のページの地域生活支援の移動支援で対応していたところです。法律が変わりまして、視覚障害をお持ちの方のいわゆるガイドヘルプにつきましては、同行援護という形で給付事業に移ったところです。","voiceIndex":217,"id":"exchange-092"},{"speaker":"山元委員","kind":"質問・要望","question":"こちらの同行援護は視覚障害者のみということであります。時間を見ると、１万６,４５３時間というすごい時間で、実際に視覚障害者の方が利用なさっているわけですけれども、区内にはどのくらいの視覚障害者の方がいらっしゃるのか。できれば、この中で年代別、大雑把でいいのですが何十代というか、使っている方たちの数がわかれば教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"年齢別の構成になりますけれども、まず、１０代が６名、２０代が１０名、３０代が３６名、４０代が４３名、５０代が５１名、６０代が合わせまして１１２名、７０歳以上の方が３１２名ということで、総合計５７０名になっております。","voiceIndex":219,"id":"exchange-093"},{"speaker":"山元委員","kind":"質問・要望","question":"やはりお年を召した方がかなり多いというのを感じますけれども、実際に、この同行援護というのは、具体的にどういうところにご一緒していただけるのでしょうか。多い順だけで結構です。教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"こちらは、社会参加の支援ということも兼ねていますので、中にはお医者さんのように決まった場所に行かれる方もいらっしゃるのですけれども、例えば、点字図書館に行きたいであるとか、お買い物に行きたいであるとか、そういったことでも使われているものです。","voiceIndex":221,"id":"exchange-094"},{"speaker":"山元委員","kind":"質問・要望","question":"どうもありがとうあります。いろいろ使っていらっしゃると思うのですけれども、実際、こういう方々が最大何時間くらい使えるのか教えていただきたいのと同時に、これは品川区だけのものなのか、または２３区共通の時間とかはあるのでしょうか。使える時間というのは。","respondent":"中山障害者福祉課長","answer":"２３区統一の時間数というのはないですけれども、おおむね区内の方は、月当たり五、六十時間使っていらっしゃるところです。","voiceIndex":223,"id":"exchange-095"},{"speaker":"山元委員","kind":"質問・要望","question":"後ほど、五、六十時間使っている方がどのくらいいらっしゃるのか教えていただきたいということと、また、同行援護は、目の不自由な方であれば、全員が使えるのでしょうか。","respondent":"中山障害者福祉課長","answer":"こちらのサービスを使われている方ですが、先ほど手帳をお持ちの方は５７０人だったのですけれども、実際に同行援護のサービスを使われている方は、登録人数としては、平成２４年度は６０人ということになってあります。","voiceIndex":225,"id":"exchange-096"},{"speaker":"山元委員","kind":"質問","question":"６０人の方が５０時間、６０時間使っていらっしゃるのかと想像するのですけれども、聞いたところによると、級があるかと思いますけれども、多少見える４級、５級というのでしょうか、そういう方たちは、同行援護は使えるのでしょうか。それとも使えないのでしょうか。","respondent":"中山障害者福祉課長","answer":"実際、若干見えるような方は、アセスメントをした結果では、多分該当から外れてしまうと考えています。","voiceIndex":227,"id":"exchange-097"},{"speaker":"山元委員","kind":"質問","question":"先ほど、課長から、お医者様とかは同行援護で使えるという話でありましたけれども、基本的に、仕事のためには同行援護というのは使えないと聞いていますが、それは事実なのでしょうか。","respondent":"中山障害者福祉課長","answer":"就労目的についての同行援護は使えないということになってあります。","voiceIndex":229,"id":"exchange-098"},{"speaker":"山元委員","kind":"質問","question":"実は、ある方が、仕事ではないのですが、会社でお仕事をしていらっしゃる方が、自分自身のスキルアップのために講習会とか、講演会とかに行きたいのだけれども、それは仕事の上だということで使えないと言われたという話を聞きました。実際、これはどうなのでしょう。自分自身のスキルアップのためというのは、仕事としてみなされてしまうのですか。","respondent":"中山障害者福祉課長","answer":"もしお悩みのケースとかがありますれば、具体的にこちらにご相談いただければと考えています。","voiceIndex":231,"id":"exchange-099"},{"speaker":"山元委員","kind":"質問・要望","question":"その都度ご相談をさせていただきたいと思います。次に、日常生活用具給付についてお伺いしたいと思います。実際、２,７６７件ということで、身体障害者の方とか、聴覚障害の方とか、さまざまいると思うのですが、特に視覚障害者の方たちは、この中でどのくらいの方が活用なさっているのか。その辺を教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"こちらは平成２４年度実績で合計１３件になります。活字文字読み上げ装置というのもの、視覚障害者向けの日常生活用具になります。こちらも１件ほど支給しています。","voiceIndex":233,"id":"exchange-100"},{"speaker":"山元委員","kind":"質問","question":"その中に、デイジー再生機というものもあると思いますけれども、これもやはり全員が給付されるわけではないと思いますが、その辺は、使えるにはどういう条件が必要でしょうか。","respondent":"中山障害者福祉課長","answer":"デイジーは読み上げ機能のものだと思います。ですので、日常生活用具のご相談をいただきながら、その方にとって、その日常生活用具が必要かどうか、そういった判断をこちらでさせていただいて、具体的に支給の対象となるかならないかという判断をさせていただいているところです。","voiceIndex":235,"id":"exchange-101","title":"町会・自治会支援"},{"speaker":"山元委員","kind":"質問・要望","question":"お年を召していると、ちょっと目が見えたとしても、夜見えなかったり、さまざま条件があると思いますので、ぜひともお話を聞いていただいて、枠にはめずに使えるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"親がしっかり見るというのが基本になっていると思いますので、そこを制度があるから使うということではなくて、なぜこれがあるのかということをしっかりと保護者の方に伝えて、利用を活用していただくというふうにすべきではなかろうか。それから、幼児の二人同乗用自転車のレンタルですが、この内容はどうなっているのでしょうか。児童センターのところでは、職員の採用はどのような状況でしょうか。","respondent":"立川保育課長、伊崎子育て支援課長、堀越人事課長","answer":"延長夜間保育の利用の仕方のことでのお尋ねですが、各公立保育園では、延長夜間保育をご利用になる保護者の方と園長が１対１で面接をいたしまして。幼児二人同乗用自転車レンタルです。こちらは、現在２２台貸し出しておりまして、まだ一定の需要があると考えています。採用についてですけれども、福祉系の職員ということで、複数の職場に配置できるという人材育成の方法で考えていきたいと思っておりまして。","voiceIndex":239,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"延長夜間保育については、しっかりと継続的に事情を聞きながら、子育てに何が必要なのか、どういう状況で延長夜間保育があるのかということについて、きちんとご説明をしていただくということを、これからも推進していただきたいと思います。これは非常に時間がかかります。その中では、こういう第三者評価をするための助成金というのは、非常に有効活用ができるのではないかと思いますが、いかがでしょうか。","respondent":"立川保育課長、伊崎子育て支援課長、堀越人事課長","answer":"新しい制度でも、保育内容の質、量的拡大、両方を目指していますので、今後とも各事業者には第三者評価制度を活用していただいて。レンタル自転車ですが、こちらはシルバー人材センターが行っている事業に対して区が補助をしているものでございまして、かなり普及をしてきたといえども。児童を相手にするという人材ということで、福祉的な観点で、そういう形で採用して育成、それから配置管理を行っているという考え方です。","voiceIndex":244,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問・要望","question":"自転車レンタルについては、まだ需要があるということですが、状況を見据えながら、見直しをするなり考えていただきたいと要望しておきたいと思います。そのために、どういうふうにこれらの助成金を使っていくのか。どういう動きをつくっていくのか。しっかり、児童センターは児童センターの職員として、ノウハウを構築していくという人材育成という形を考えられているのか、そこをお伺いします。","respondent":"今井制度改革・待機児童対策担当課長、堀越人事課長","answer":"子ども・子育て新制度の中におきましても、保育の質、そして設置基準につきましては、確認制度等で運営基準等を確認して、そして給付をするという大きな仕組みになってきてありますので、その中で保育の質。実際に異動して、一定の年数在籍して、児童センターの中核職員として育成していますので、そういう形で配置管理を行っていきたいと考えております。","voiceIndex":248,"id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問","question":"１２６ページの就労移行支援等、１２８ページの通所施設関係、そして１３３ページの延長夜間保育の３点お伺いします。就労支援センター「げんき品川」での取り組み強化がプレス発表に載りましたけれども、７,４４９万８,０００円予算化されていますが、この予算の使い方、そして障害者の就労支援の現状の評価と今後の課題についてお知らせください。","respondent":"中山障害者福祉課長","answer":"ある程度能力の高い方は、今は一般企業への就労ということが国でも制度化しておりますので、一定の雇用率を確保するために一般就労の場があること。それから、一般就労ができない方については福祉的就労の場ということで、就労継続支援Ａ型とＢ型がそれぞれあります。","voiceIndex":252,"id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"わかる範囲でいいのですけれども、人数をお伺いします。げんき品川とたいむ、それぞれの相談の人数、延べではなくて実人数はわかりますか。一般就労につながった方、福祉就労のところ、別々に仕事につながった人数も、できれば実人数で教えてください。","respondent":"中山障害者福祉課長","answer":"げんき品川の相談実数ですけれども、１,５９２人というのは延べ人数になります。登録者の数で行きますと、ちょっとすみません、数字を整理させていただければと思います。実際に平成２４年度、企業に就職した人数ということですが、こちらは２５人になっております。","voiceIndex":254,"id":"exchange-107"},{"speaker":"飯沼委員","kind":"提案","question":"わかった時点で教えてください。３点提案をしますので、お答えをいただきたいと思います。理解、啓発のための努力を求めます。これが１点目です。これが２点目です。そして３点目、専門職の配置をまずお伺いしたいのですが、げんき品川とたいむ、そして障害者福祉課に配属をされています専門職の人数を教えていただきたいのが、まず初めです。専門職の配置の充実を求めますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"げんき品川では、一般企業、障害者を受け入れた企業から、受け入れ前の支援、受け入れ後の支援ということで、長く継続して就職できていくようにという支援をしています。","voiceIndex":256,"id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご丁寧にありがとうあります。私はここを強く求めますが、これをもう１回お願いしたいのと、保護者の方々から、企業の中には虐待があり得るといった認識をぜひ持っていただいて、その上で相談に乗ってほしい。やはり現実に、いろいろご苦労されている部分があるのかと思います。ぜひぜひ品川区でも、げんき品川、たいむにおいても、専門職の充実をお願いしたいのですがいかがでしょうか。","respondent":"堀越人事課長","answer":"区としての、障害のある方の雇用に関してですが、自立それから社会参加等を進める上で、そういった障害のある方の雇用は大変重要な課題であるという部分では認識しております。","voiceIndex":258,"id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりこれは自治体が率先してやっていくべきものであると思うので、重ねてお願いしたいと思います。何とかこの苦しい状況を改善してほしいという声が届いています。通所施設の定員に対して利用状況を教えていただきたいのと、現状の認識と今後の対策もあわせてお伺いいたします。","respondent":"中山障害者福祉課長","answer":"その整備が終わりますと、平成２７年４月には５０人の就労継続Ｂ型ということで、ふれあい作業所が変わってまいります。そこでまた１０人の雇用の確保ということで、順次こうした形で現状の解決につながるような策を講じているところです。","voiceIndex":260,"id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状認識をある程度していただいて、改善の方向にあるということです。新しくできるということでもあるのですが、来年、再来年、特別支援学校の卒業生が増えていくというあたりの見込みをどう考えているのかということと、そういうことも含めて、保護者の方々からも、ぜひ通所施設を増やしていただきたいという声が出ていますので、ぜひ増設を求めたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"特別支援学校および城南特別支援学校の卒業の見込みということです。こちらは区でも数字として把握しています。この数字を見つつ、新たに卒業されて区内の就労の場にいらっしゃる方もいれば、あるいは今まで使っていたサービスをやめられる方もいらっしゃいます。","voiceIndex":262,"id":"exchange-111","title":"町会・自治会支援"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ考えていただきたいと思います。保育園のところなのですけれども、本日、何人かの方から延長夜間保育の質問がありました。夜間保育が必要なくなる社会が来ることを私も願っています。この点を、十分配慮していただきたいのと、子どもたちの夜の生活にマイナスの要素があるのならば、それを取り除く改善をぜひ行っていただきたいので、この点を答えてください。","respondent":"立川保育課長","answer":"保護者の方が実際に毎日夜間迎えに来たときに、お子さんが数少なく残っているような状態なのですけれども、保育者といたしましては、そうした状況におきましても常に最善の保育を実施しています。","voiceIndex":264,"id":"exchange-112"},{"speaker":"若林委員","kind":"質問・要望","question":"４点ありますが、最初に１点お聞きして、あとで３点伺いたいと思います。区立幼稚園でも徹底した取り組みが行われていると伺っています。今年の予算特別委員会で、私たちの会派から、私立幼稚園について理解を進めることの要望に対しての答弁がありまして、アレルギー対応は正しい知識が前提となると思うので、研修についてもお願いしていきたいというご答弁をいただきました。","respondent":"立川保育課長","answer":"幼稚園では、幼稚園協会が実施する研修会等がありますので、そういう機会に、区から補助しています研修費等から、アレルギー対応の研修についても開催してほしいということを要望しております。","voiceIndex":268,"id":"exchange-113"},{"speaker":"若林委員","kind":"質問・要望","question":"要望しておられるということですので、改めて確認、文科省のガイドラインに沿った、また区の要望もしている中で、しっかりと私立幼稚園の中で研修等を行っていますという、各職員がスキルを身につけて今努力をしていますという確認をぜひしていただきたいと思いますので、ご答弁をお願いしたいと思います。ここら辺の区の評価をお聞きしておきたいと思います。お聞きしておきます。","respondent":"立川保育課長、中山障害者福祉課長","answer":"ご指摘のありました私立幼稚園に対するアレルギー対応に関する研修につきましては、機会を捉えて要望していきたいと考えております。こちら、チラシを配布した数としては１,８００枚なのですけれども、ご家族でいらっしゃったり、お子さんなどはチラシを持たずにこちらの会場で楽しんでいただいたというところで。","voiceIndex":270,"id":"exchange-114"},{"speaker":"若林委員","kind":"提案","question":"ただ、まだ３カ月一括で、この前もあるお母様とお話しましたが、まだまだ単価は大きいですということで、どうしても認証保育所にお世話になる判断ができませんというようなことを聞きましたので、一つ最後の提案になるかと思いますけれども、今回４カ月が３カ月になりましたが、毎月がベスト、理想です。それから、障害者まつり、わかりました。一つご提案ですが、祭りと言えばおみこし。２点。","respondent":"立川保育課長、中山障害者福祉課長","answer":"事務改善をやったばかりなのですけれども、保護者の利便性ということを考えますと、今後とも改善に向けて研究していきたいと考えております。障害者の方が少しでも多くお祭りに参加して楽しんでいただけるよう、ご提案のことも含めて検討してまいりたいと思います。","voiceIndex":273,"id":"exchange-115"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、社会福祉費から１３４ページのぷりすくーる西五反田運営費、１３６ページの品川児童学園運営費、児童相談員経費、この辺で確認をさせていただきたいと思います。４月からはどうなるかわからない状況はありますけれども、指定管理者だったＮＰＯですと、年度が変わって平成２６年４月からは、ＮＰＯだと運営ができないという話も出ていたのですが、その辺を区に確認をさせてください。","respondent":"立川保育課長","answer":"現在のぷりすくーるですけれども、こちらは条例に従いまして、認可保育園の部分と幼児教育部門ということで運営していますが、新制度のいわゆる幼保連携型の認定こども園ということだと思いますが。","voiceIndex":277,"id":"exchange-116"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、ぷりすくーるが幼保連携型ということになってくると、継続して、さっき言ったようにどうなるかわからないですけれども、運営自体がいいということなのですか。それとも、今のＮＰＯ法人はだめという、その辺はどうなのでしょうか。","respondent":"立川保育課長","answer":"まだ、区といたしましては、区全体の施設につきまして認定こども園化する、しないということについては、まだ国のほうで、詳細について明らかになっていない現状ですが、仮に認定こども園化ということになりますと。","voiceIndex":279,"id":"exchange-117"},{"speaker":"鈴木（真）委員","kind":"確認","question":"ぷりすくーるが幼保連携型ととっていたのですけれども、区全体ではなくて、ぷりすくーるだけを考えたときに、あそこは社会福祉法人にならなくてはいけないのでしょうかという、学校法人なり。そこはちょっと確認させてください。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"ぷりすくーるにつきましては、公設民営で実施していますけれども、運営形態自体を認定こども園化するということになりますと、現状の法人の形態では運営できないです。私どもとしましては、こういった基準が、今明確ではないので判断を留保しているところでありますけれども、明確になった時点で。","voiceIndex":281,"id":"exchange-118"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ただ、一つ気になるのが、さっきの繰り返しになりますけれども、来年３月から、もしぷりすくーるが今のＮＰＯ法人子育てしながらがやっていったときに、ＮＰＯから変わらなければいけないといった場合は、指定管理の契約自体がどうなるのかとその辺の心配があります。そこら辺も早めに、先方また我々にも教えていただきたいと思いますけれども、その辺よろしくお願いします。","respondent":"立川保育課長","answer":"大型の遊具についてのご質問ですが、こちらにつきましては、年度ごとに計画的に取り替えの必要なものについては取り替えるということで対応を図っているところです。","voiceIndex":284,"id":"exchange-119"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"順次計画的というか、なるべく早く要望に応えていただけるように、その辺もご判断をよろしくお願いいたします。児童学園のほうに移ります。歳入の際にお聞きさせていただきました。児童学園改築ということで、いい答えが出てきたと、私ども自民党としても思っております。その辺はどのように考えたらいいのか、お答えください。","respondent":"中山障害者福祉課長","answer":"現在、そういう意味では相談につながるまでに３カ月お待ちただいているような状況があります。こちらとしましては、部屋の工夫も含めまして、できるだけ３カ月の相談を短くするような努力をするために、児童学園と打ち合わせをしています。","voiceIndex":286,"id":"exchange-120"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。ただ、他の自治体から品川に移られた方が万が一そういうときは、品川はそんなにおくれているのかというような、区に対して、不満を持たせないように、なるべくその辺もうまくつないでもらいたいと思います。それから、今度は改築のほうに移っていきますが、この間私も控え損なったのですけれども、改築はどのくらいの建物の方向性を考えているのか、この点についてお答えをいただきたいです。","respondent":"中山障害者福祉課長、柏原行財政改革担当課長","answer":"建替え後は、かなり広い面積がとれるものと考えられております。建物につきましては、今の面積に対しての建てられる建物は、かなり大きなものが建てられるという、建ぺい率等々はありますので、そういったところを踏まえながら、ボリュームはチェックしていきたいと思います。","voiceIndex":288,"id":"exchange-121"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"行革ではなく、担当の課長がどこまで答えられるかわからないですけれども、やはり、これが障害者施設だけで１本で決まったのかどうかも確認したかったところです。もちろん、障害者施設として利用していただきたいというのは、自分たちも十分あるのですけれども、その中でいろいろな要望事項もそれぞれのところから出ています。","respondent":"柏原行財政改革担当課長","answer":"先ほども申しましたように、かなりのボリュームの建物が考えられます。現行の児童学園の機能でありますとか、足りない部分でありますとか、当然ありますので、そういったものを確保した上で、どういったところで使えるか、総合的な判断も踏まえて考えていきたいと考えております。","voiceIndex":291,"id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。全体的な話なのですけれども、今のは子どもという形でしたけれども、障害者も高齢化してくるという中で、障害者の高齢化ということも踏まえた上で、今度は高齢者施策との兼ね合い。区として、どういうつながりを持って、連携をとっていらっしゃるのか、健康福祉事業部としての考え方をお答えいただきたいと思います。","respondent":"早津健康福祉事業部長","answer":"そうした中では、障害者も高齢期を迎えていくということになりますので、ますます障害者施策と高齢者施策の連携を深めて、長期的な物の見方を持ちながら、施策を展開していきたいと考えています。","voiceIndex":293,"id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それから最後になります。先ほど課長からご答弁いただきました。当然、区として、また担当課として、いろいろな立場で品川区の要望を訴えていると思うのですが、今、現実的に一番動いているのは、区長会での動きだと思っています。区長会の中で、いろいろそういう都に対する要望も出ていると思うのですが、現状的なものを確認させていただきたいと思うのですが、よろしくお願いします。","respondent":"濱野区長","answer":"児童相談所の問題であります。ご案内のように、あり方検討会がいったん閉じたような状態で、しかしそういう中でも、児童相談所だけはぜひ移管をということで運動を繰り広げてまいりました。しかし、東京都のほうは、いまだにだんまりの状態であります。","voiceIndex":295,"id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひ区長の力で、実現に向けて頑張っていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-125"},{"speaker":"原委員","kind":"質問・要望","question":"同じく、福祉の品川と言われるということに思いを込めまして、質問します。この２００万円を、具体的に中身を教えていただきたいということと、何で市民なのか、区民でもいいのかという、その辺はお話いただきたい。それから１２３ページ、その中で小規模多機能型居宅介護施設運営費助成、これは２カ所で８９６万円となっておりますけれども、これも具体的に教えていただければと思います。","respondent":"永尾高齢者福祉課長","answer":"社会福祉協議会の助成金の話になりますけれども、社会福祉協議会は、地域の身近な存在として、きめ細やかな、行政ではできないような細かい生活の中でのサービスをやっているところです。","voiceIndex":300,"id":"exchange-126"},{"speaker":"原委員","kind":"質問・要望","question":"ですから、そういう中において定着していくのか、またある程度の高齢者の保護とか、そういうもっと全体的な資産面も含めてなのですけれども、そういう面でのプラス面を、区の立場としてどういうふうに考えているのか、もう１回お答えいただきたいということと、それと、社会福祉法人についてですけれども、今もありましたように、これは昨日、一昨日の答弁の中ですけれども、違っているかあれなのですが。","respondent":"永尾高齢者福祉課長","answer":"法人に対する助成です。こちらにつきましては、社会福祉法人の部分については、バランスを持った資金のやりくりが法人の中で必要となっておりまして、当然、安定的で継続的な経営が求められています。","voiceIndex":302,"id":"exchange-127"},{"speaker":"原委員","kind":"質問・要望","question":"世間が何と言おうと大いに活用していただきたいと考えています。ただ、実際に世の中の形として、今、民間と同じような契約をされているということがありましたが、そうなのかという思いも私自体があるものですから、公正証書等も含めて、１点ご答弁で漏れたのが、定期的に見直し等をやっていらっしゃるかどうかという答弁がなかったので、その辺をもう一ついただければと思います。","respondent":"永尾高齢者福祉課長","answer":"品川区の５法人に対するやり方というのは、他区にはない独特のやり方をしていると思います。","voiceIndex":304,"id":"exchange-128"},{"speaker":"あべ委員","kind":"質問・要望","question":"これは１食１万２,０００円余の計算になってしまうのでけれども、このコストが妥当と思われているかどうか、お考えを伺いたいと思います。五反田シルバーセンターにもほかのシルバーセンターにあるような、座椅子というのですか、そういったものを導入していただきたいと思うのですが、いかがでしょうか。区として、何らかの形で支援をしていただきたいと思うのですが、お考えはいかがでしょうか。","respondent":"永尾高齢者福祉課長、立川保育課長、白鳥高齢者いきがい課長、伊崎子育て支援課長","answer":"一つの例ですけれども、一定の地域の中で認知症サポーター会議というのを開いておりまして、そこの地域の民生委員やご家族。現在のところ、経済的な支援については考えておりませんけれども、講習等に参加する機会については年次休暇等の取得については。こちらにつきましては、ほとんどが委託料ということで事業運営費が主なものですけれども、その中での人件費ということで。ご参加の方を見ますと、下の子がまだ小さい、就学前という方もいらっしゃいますので、実施の時期や運営方法につきましては。","voiceIndex":307,"id":"exchange-129"},{"speaker":"あべ委員","kind":"提案","question":"ぜひ、より多くの方に両方取っていただきたいと思います。先ほど、他の委員からもご提案がありました既存の飲食店を使ってというのも、私はすごくいい方法だと思います。その中に、栄養ですとか、体操を入れていくという考え方もあるかと思いますので、ぜひ多く広めるためにも、１回当たりのコストを下げていけば、同じ金額でより多くのサービスが提供できるわけですから、ご検討をいただければと思います。","respondent":"白鳥高齢者いきがい課長","answer":"そのために座ってしまうと。多くの方が利用できないというようなこともあるのですけれども、やはりパイプ椅子……。","voiceIndex":312,"id":"exchange-130"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。質問で、私が言い間違えたのですね。つまり、当初額に対して、とても少しだけ流用増をしていて、結局執行率は７０％台というかなり低い状態なのです。なので、どうしてこれだけ執行率が低いのかということと、それから執行率が低い事業で、どうして途中で８万円だけ足してあるのかというのがよくわからなかったので、その理由、この数字の意味を教えていただければと思います。","respondent":"永尾高齢者福祉課長","answer":"日常生活支援総合事業ですけれども、こちらは要支援の方を対象に、訪問介護員を派遣して、日常生活をみてあげるという、自立に向けてのケアをするという内容ですけれども、ちょっとこの流用の中身について、今すぐ答えが出ません。","voiceIndex":316,"id":"exchange-131"},{"speaker":"あべ委員","kind":"質問・要望","question":"ありがとうございました。では、この少額の流用については、また別の機会にでも伺うことにしたいと思いますが、全体に、介護保険の中の介護予防の事業、特に地域のところは、かなり執行率が低め、低めになっているように感じております。ですから、大変言い方は悪いですけれども、多目の予算を何とか使おうとしているかのような組み立てになっているように感じております。","respondent":"永尾高齢者福祉課長","answer":"なかなか外に出るのが難しい方がたくさんいらっしゃる中で、どうしても講座を設置すると、基本的な人件費がかかってきてしまうという難点があります。これからも、要介護にならないような施策のために工夫をしていきたいと考えております。","voiceIndex":318,"id":"exchange-132"},{"speaker":"浅野委員","kind":"質問","question":"成果報告書の１２７ページの福祉タクシー、自動車燃料費助成、それと１３３ページの児童福祉施設費、非構造部材耐震対策、保育園、ぷりすくーる西五反田、幼保一体施設、児童センター、家庭あんしんセンターなどありますけれども、これは高齢者施設、障害者施設なども含めてお伺いしたいと思います。","respondent":"立川保育課長","answer":"保育園、幼稚園関係ですけれども、公立の幼稚園、保育園、また幼保一体施設全ての園で、非構造部材耐震対策については実施いたしました。","voiceIndex":321,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問・要望","question":"保育園の特質というところで、棚とか時計などが多かったと伺っておりますけれども、一つ気になるのは、実際に今回こういう形で行いましたけれども、また時間がたつと忘れて、また新たな棚をつくったりとか、例えばそういう手を入れる危険性もありますので、継続して、保育園ですとか、そういう施設に関しましては、指導していっていただきたいと思うものであります。","respondent":"立川保育課長","answer":"私立保育園、認証保育所等につきましては、東京都で耐震対策についての事業を実施しておりますので、そちらの申し込みを、区で取りまとめたという状況です。","voiceIndex":325,"id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"都のほうでということですが、耐震対策は認識しておるのですけれども、同じく非構造部材についてもやられたのか、また私立の保育園も、そういう意味では全部、実際に行われたのか教えてください。","respondent":"立川保育課長","answer":"今、お話しましたのは非構造部材の耐震対策ということで、東京都のほうで事業化しています。","voiceIndex":327,"id":"exchange-135"},{"speaker":"浅野委員","kind":"質問","question":"そういう意味では、やられたというところですので、子どもの安全はある程度改善されたといいましょうか、整えているということで認識をしておきます。区の直営でありますとか、委託、指定管理とかさまざまありますけれども、それらについても、それぞれ教えてください。","respondent":"柏原行財政改革担当課長","answer":"そのほかもろもろの施設があります。それで、まず学校のほうを先にやりまして、それからお子さまのいるような施設ということで、あと二次避難所になるようなところであるとか、こういったところは順次進めていく予定です。","voiceIndex":329,"id":"exchange-136"},{"speaker":"浅野委員","kind":"質問","question":"区民が多く使われるということでありますので、このような施設関連につきましても順次やられるということですので、また決算が出てきたらお伺いしていきたいと思うわけであります。こちらのほうですけれども、交付した金額に対する利用比、タクシーのほうは私の計算によると約８割の計算で、燃料費の助成が９５％くらいだと思いますけれども、この数字で正しいのか教えてください。","respondent":"中山障害者福祉課長","answer":"委員お尋ねの福祉タクシーの利用率につきましては、交付枚数から利用枚数を勘案しますと、おおむね８割程度の利用率と考えていいかと考えています。","voiceIndex":331,"id":"exchange-137"},{"speaker":"浅野委員","kind":"質問","question":"おおむね８割ということで、使用期限等がありますので使われ方はさまざまだと思いますが、交付額につきましては、今までもなかなか上げていただけないというのはあると思いますけれども、全額利用されていない主な理由は、どういうところにあるのか教えてください。","respondent":"中山障害者福祉課長","answer":"そういった中で、ご利用される方の利用目的が、例えば通院ということになりますと、利用が集中することがあろうかと思います。そういった中で、交付はされたものの未執行のものが出てしまったということが、一つの原因として挙げられると思います。","voiceIndex":333,"id":"exchange-138"},{"speaker":"浅野委員","kind":"質問・要望","question":"さまざま個別の事情がありますので、ぜひとも全部使えるようにしてもらいたいと思いますが、最後になりますけれども、タクシーか、燃料費助成かどちらかということですけれども、共通に利用できないかという声も何件か届いておりまして、なかなか難しいとは思いますけれども、そういうところにも焦点を当てて、検討をしていただけないかという要望ですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"福祉タクシー券の交付、そして自動車燃料費助成というのは、少しでも外出支援の一部に役立てていただければということでやっております。今のところ、両方の支給は難しいと考えていますが、利用の実態等を見ていきたいと考えています。","voiceIndex":335,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"最後に今後の、今言ったように民間でもこういう形ができてきていますけれども、先ほどお聞きしたら、悪徳弁護士とかそういうのがあるけれども、品川区として二重、三重のチェックの仕組みがあるということで安心しているところなのですけれども、これから高齢者の数が増えてきて、どんどんと利用者が増えてくるのではないかと思うのですが、そのあたりの対応としてはいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それで、今後、高齢者が増えてきていますけれども、今のやり方で行くと、かなり職員の人数的にも厳しいところがありますので、今後、市民後見人の要請が充実されてくれば、そういうところにも任せたり、ただし悪用されないような方法を考えつつ。","voiceIndex":338,"id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"１２３ページの福祉人材確保・定着事業の４,３２３万円余。いろいろな事業をされているのですが、このことをやって、１年たってみて、福祉人材が確保されているのか、定着してきているのか。行政からこういう形でやったのか、事業者から声があったのでこういう事業をやってきたのか、その結果について教えてください。","respondent":"永尾高齢者福祉課長","answer":"介護者、家族への効果的な支援策検討事業ということで、介護者がいろいろな研修等、介護教室等の研修等に出やすくするための方策を検討したりとか、その中で、介護者が不在になる間に訪問介護員を派遣するモデル事業をやってみたりとか、福祉人材ネットワーク推進研修事業として。","voiceIndex":342,"id":"exchange-141"},{"speaker":"須藤委員","kind":"質問","question":"内容でなくて、法人から来たのか、行政がやったのか。結果はどうなっているのかということを教えてください。","respondent":"永尾高齢者福祉課長","answer":"そういう事業、そのほか人材確保の研修等をやっています。訪問介護２級取得受講費助成ということもやっておりますけれども、現場改革を大事にしているというところで、こういう事業を充実させておりますけれども、依然として人材不足というのは続いている状況かと考えています。","voiceIndex":344,"id":"exchange-142","title":"町会・自治会支援"},{"speaker":"須藤委員","kind":"質問・要望","question":"１２５ページ高齢福祉費全体で、高齢福祉というと、自分のことを自分で聞いているようで恥ずかしいのだけれども、振り込め詐欺というのは違うかもしれないけれども、高齢福祉全体で見ると、被害とか、いろいろな事業をやっている中で、そういうＰＲなんかはいろいろな場所でできると思うのですが、私自身もここ何回かそういうことがあって、「俺、俺」と息子を称するので、「おまえ。","respondent":"永尾高齢者福祉課長","answer":"ケアマネジャーと警察の連携もできております。警察のほうで、例えば高齢者クラブ等の会合には必ず説明をしたり、また民生委員協議会の地区の会合にも、警察の方が必ず１年に１回は来て説明をしております。","voiceIndex":346,"id":"exchange-143"},{"speaker":"須藤委員","kind":"質問・要望","question":"高齢者は、聞いて、こっちに行ってしまうので、なるべく丁寧にやっていかないと、つい引っかかってしまう。最後に、１２７ページ、高次脳機能障害者医療コーディネーター設置で、高次脳機能障害についてはいろいろと対応していただいてうれしく思いますけれども、今後の考え方、いろいろと高次脳の方々からご要望があるのですが、今後の対応というのは、一つはいわゆるケアをして、その後、就活、リハビリ。","respondent":"中山障害者福祉課長","answer":"区としても、これからも高次脳機能障害の方の居場所づくり、そして社会生活の支援というところで対応していきたいと考えております。","voiceIndex":348,"id":"exchange-144"},{"speaker":"須藤委員","kind":"質問・要望","question":"ありがとうございました。いろいろなご努力をしていただいているのはわかっているので、感謝申し上げます。ただ、高次脳機能障害というのは１０人いれば１０人、症状も違うし、その対応も異なってくるので、患者、あるいは親御さん、家族の方からのいろいろなご要望はいろいろな形で出てこようかと思うので、またいろいろな声を聞いて、ぜひ対応もろもろよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"介護保険と国保、後期高齢者について、お伺いしたいと思います。介護保険なのですが、決算書２５４ページの介護給付費等準備基金運用状況報告書で、平成２３年度の基金の残高が２３億１,０００万円余で、２億６,０００千万円余を取り崩して、平成２４年度末では２０億４,９００万円余という基金残高になるということで確認させていただいてよろしいでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今、委員ご指摘のとおりで正しいということです。","voiceIndex":352,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第５期が平成２４年度から始まったのですけれども、この基金の問題での委員会ですとか、決算および予算特別委員会のやりとりの中で、第５期に入る前の基金の金額が１８億８,０００千万円で、第５期で１０億円余を取り崩して、残８億円余になるという説明だったのですけれども、そうすると平成２３年度末の２３億１,０００万円余とは４億円余の差があるのですけれども、これがなぜなのかということと。","respondent":"永尾高齢者福祉課長","answer":"実績で見てみますと、実際の保険料収入の中で給付費が賄われているということで、結果的に最初の予定よりも支出のほうが少なくなっているという状態になっています。","voiceIndex":354,"id":"exchange-147"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この基金の問題は、介護保険の保険料を決めるたびごとに、ずっとやってきている問題なのですが、品川区の基金はたくさんため込まれているという状況なので、この基金というのは６５歳以上の方の保険料そのものですから、私はやはり必要なサービスが使えるようにするということと、それから余った保険料については、基金に積み増していくのではなくて。","respondent":"永尾高齢者福祉課長","answer":"品川区の介護認定の方法ですけれども、認定調査がほかの自治体に比べると、かなりきめ細かくやっておりまして、医師の診断書だけの書類上の認定だけではなくて、実際の調査をしたりという内容になっているところから、実態に合わせてやっているという結果になっているところです。","voiceIndex":356,"id":"exchange-148"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、要支援の方が、今度は介護保険のサービスから外していくという検討がされていますけれども、私は、本当に具体的にヘルパーですとか、在宅介護支援センターですとか、いろいろお話を伺う中で、要支援の方もサービスを使わなければ生活が成り立たないし、生きていけないという実態を改めて伺ってきたのですけれども、要支援の方のサービスの必要性の認識についても改めて伺いたいと思います。","respondent":"永尾高齢者福祉課長","answer":"要支援をサービスから外すというお話ですけれども、それについては、今、国の会議で検討されている内容でありまして、まだ決定している内容ではありません。","voiceIndex":358,"id":"exchange-149"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、平成２４年度の運営状況の中で、特定施設と特別養護老人ホームの介護給付費がほとんど同じという状況になっているのです。有料老人ホームは要支援の方でも入れる。特養ホームは、今度は３以上ということで検討されているわけですけれども、私は、これは介護保険のあり方として不公平だと思いますし、問題なのではないかと思いますけれども、その点はいかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"今、国で検討されている部分、特養についての検討をされている状態ですけれども、特定施設について、どういう検討になるかというのはこれからになるかと思いますので、一概に今の段階で、どちらが不公平ということは言えないと考えています。","voiceIndex":360,"id":"exchange-150"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特養ホームは、お金がある人でもない人でも入れるわけですから、私は特養ホームこそつくっていくという姿勢に、ぜひとも区としては立っていただきたいと強く要望して、国保のほうに移りたいと思います。国保では、やはりいつも高過ぎる保険料が問題ですけれども、改めて滞納者、短期証、資格証、差押え件数と金額、収納率の件数と金額について、お聞かせください。","respondent":"間部国保医療年金課長","answer":"滞納繰越分については５％ほどアップしているということで、委員ご指摘があるかもしれないですが、最近、やや景気が持ち直している部分と、保険料算定を旧ただし書きに変更しまして、幅広い層に保険料を公平に負担していただいたことがきっかけで。","voiceIndex":362,"id":"exchange-151"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。短期証と資格証が半減、資格証も前に比べたら少なくなっているということは本当によかったと思っています。それともう一つ、今後２０１５年に向けて広域化が進められようとしていますけれども、このことでどう変わるのかということについてもお聞かせください。","respondent":"間部国保医療年金課長","answer":"広域化につきましては、制度改革国民会議のほうで、国保につきましては平成２６年から平成２９年の間に都道府県単位化で進めるという報道があります。しかし、分権的な広域化ということで、保険料の賦課・徴収等健診を含めた保健事業については、そのまま国保に残るです。","voiceIndex":364,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"ということは、それを窓口にしている所管の高齢者福祉課、障害者福祉課、国保医療年金課、生活福祉課、保育課、子育て支援課、それぞれの課において、それぞれのサービス、手続を受けられる区民に対して、日ごろ直接、電話や窓口で対応されていると思いますが、職員の方にも相当のストレスがあるのではないか、受けているのではないかと思うのですが。","respondent":"竹田生活福祉課長","answer":"今般の基準改定は、社会保障審議会の生活保護基準部会における検証結果や、平成２０年度以降の物価の動向を勘案するという合理的な考え方に基づき適正化が図られたものです。","voiceIndex":367,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"でも、一般の人から見て絶対におかしいですよね。生活費、生活必需品、生きていくためのお金が、実際に生活して生きていくための費用、物価が上がっているのです。前はデフレだから、下がっているから、その分は合わせようということで下げたのです。国のやり方はおかしいではないですか。それは筋が通らないと思うのですが、もう一度、区として、何もしないのかご見解をお聞かせください。","respondent":"竹田生活福祉課長","answer":"今回の調査結果は、全国の消費実態調査に基づいて検証された結果です。検証するには所要の時間がかかりますので、経済状況がその間に若干変わるということはやむを得ないことだと思います。ただ、一般財源で補填するつもりはございません。","voiceIndex":369,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"実際、我々はこう生きていて、低所得者もたくさんいます。誰が考えたってわかりますよね。次に、先ほどの職員の勤務実態についてお聞きするということで、質問は聞いているのかな、各所管で、窓口で直接いろいろな区民の方と接しています。苦情等さまざまあると思うのですが、何人くらい休職しているのか、またこれの原因によって、何人くらいお辞めになっている方がいるのか、お聞かせください。","respondent":"堀越人事課長","answer":"このようなメンタルの病気に関しましては、原因につきましてはそれぞれ個人の性質的なものですとか、プライベートなもので、さまざまありますので、特に原因を特定できるとは考えておりませんけれども、窓口でのクレーム対応の研修ですとか、メンタルヘルスの研修ですとか。","voiceIndex":371,"id":"exchange-155"},{"speaker":"須貝委員","kind":"質問・要望","question":"でも、今、資料がないということなので、それはよくわかりました。それで、職員の方、私は相当ストレスがあると思いますので、その辺はしっかり、メンタル等配慮してやっていただきたいと思います。そして、ここ３年くらいで結構ですが、介護保険、予算は毎年幾らくらい増えているのでしょうか。そして、介護認定者数も、ここ３年くらいでいいのですが、何人くらい増えているのか、お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"申しわけありませんでした。介護認定の認定率と数になりますけれども、６５歳の方の介護認定は平成２３年３月現在ですと１万９５６件、平成２４年３月ですと１万１,５６７件ということで、それぞれ認定率でいくと１５.４％と１５.９％となっております。","voiceIndex":374,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"予算もどれくらい増えているのかというのもお聞きしたかったのですが、品川区でさまざまな介護予防対策を実施しているわけです。単純に、なぜこういうふうに増え続けてしまうのか。高齢者が増えているからという単純な理由もあるかと思いますが、私は、品川区でさまざまな施策をやって、何とか介護予防しよう、とめようとして努力をしているわけですが、なぜ増え続けてしまうのですか。お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"区でも、それに対応するためにいろいろな保健事業だとか、生きがいづくりの事業等を行っているところですけれども、やはり各自が健康に対して気をつけるというようなものも必要だと思っていますので、そういうところの啓発も含めてやっていきたいと思っています。","voiceIndex":376,"id":"exchange-157"},{"speaker":"須貝委員","kind":"質問・要望","question":"確かに最初は生きがいなのかもしれないですけれども、やはり生活して、結婚しようかと思ったら年収はどうなの、３００万円満たないのです。２００万円です。でも、そういうときに、いい人は３年勤めた。介護に関して、これからどんどん増えるわけですが、認知症の方も含めて、健康診断のような仕組みはあるのでしょうか。ただ、そのまま、認知症になりました、介護を受けられましたということなのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"こちらは要介護状態になることを予防して、自立した生活を営むようにということで、そういう状態になる恐れの高い方を二次予防事業者といたしまして、その調査を行って、結果をスクリーニングしていくようなことを始めているところです。","voiceIndex":378,"id":"exchange-158"},{"speaker":"須貝委員","kind":"意見","question":"先ほど、高齢者いきがい課のほうでさまざまな事業に取り組んでいらっしゃって、さまざまな高齢者の方が楽しみ、大勢の方と触れ合っていらっしゃる。これと同じようにデイサービスセンターでは、介護予防というよりは機能改善ということとか、朝お迎えに行って、お昼に食事をして、おやつが３時ごろ出て、また送り届ける。私はやるべきだと思うのですが、その辺についてご見解をお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"特に男性の場合は、引きこもってしまう方が多いので、例えば女性の方、近所の方が、講座に参加をするときに声かけするとか、そういう仕組みを考えていったらいいかと思います。いろいろなアイデアを出しながら、検討してまいります。","voiceIndex":380,"id":"exchange-159"},{"speaker":"須貝委員","kind":"意見","question":"私、受け身もいいのですが、やはり積極的に、もっと区役所が出ていくべきだと思いますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":382,"id":"exchange-160"},{"speaker":"井上委員","kind":"質問","question":"歳入のところでもお伺いをしましたので、その続きになるのですけれども、低所得者等対策事業と被保護者自立促進事業で、高校入学の方と中退の方の数を伺いまして、生保のほうではお伺いをしたのですけれども、受験生チャレンジ支援貸付を活用したお子さんたち、平成２４年でいうと２８人が利用しているのですが、その中で平成２０年から始まった事業で。","respondent":"竹田生活福祉課長","answer":"こちらの受験生チャレンジ支援貸付事業は、生活保護受給者ではなく低所得者を対象にした事業ですので、貸付終了後、中退したかどうかということは把握しておりません。","voiceIndex":384,"id":"exchange-161"},{"speaker":"井上委員","kind":"質問","question":"これは生保ではないかもしれないのですけれども、どこかでこういった子どもたちが、入学して、免除でそのままほっとかれるのではなくて、フォロー体制が必要かと思うのですが、特に生保のほうは、こういう形で見られるということで、中退者の方がいて、どのようなフォロー体制をとっていただいているのか教えてください。","respondent":"竹田生活福祉課長","answer":"生活保護受給者世帯に育つ高校生の中退の問題ですが、子どもの健全育成支援の観点から、生活保護世帯への養育相談や学習支援などに取り組んでおります。","voiceIndex":386,"id":"exchange-162"},{"speaker":"井上委員","kind":"質問・要望","question":"これは要望です。次に、福祉団体についてお伺いしますけれども、障害者の総数と障害者団体と言われる７団体の会員数の総数は、何人ということで把握されているでしょうか。","respondent":"中山障害者福祉課長","answer":"障害者の人数といたしましては、おおむね身体障害者が８,０００人程度、知的障害者が３,５００人程度だったと思います。それに対しまして、障害者７団体の構成人数ですが、こちらはおおむね７００人程度ということになってあります。","voiceIndex":388,"id":"exchange-163"},{"speaker":"井上委員","kind":"質問","question":"障害者の意見聴取や周知に、よく区からは障害者７団体という答弁が出てくると思うのですけれども、実際に今お伺いをしたところによれば、７団体の会員の方たちというのは、手帳をお持ちになられている方たちの１割にも満たない状況ということなので、ほかにも積極的な情報提供をしていかなければいけないのではないかというふうに思いますけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"今回ヘルプカードの作成を課で進めておりますが、こういった中でも７団体だけではなく、オープンに意見を伺う場ということで、広報等を通じて呼びかけているところです。","voiceIndex":390,"id":"exchange-164"},{"speaker":"井上委員","kind":"質問・要望","question":"私も、団体の方たちが、それぞれ施策の取り組みだとか、周知のことを積極的にしていただいているので、決して団体を否定しているわけではありませんけれども、７団体以外に多くの障害者のグループの方たちがいらっしゃいますから、ぜひコーディネーター役を務めて、意見交換、情報交換をする場を設置していただきたいと思いますが、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"個々のご意見を伺うことはできるのですけれども、なかなか団体ではない方、まとまった場での意見ということでは難しいのかとは考えているところです。ただ、今回、障害者の方を対象とした調査を行っております。","voiceIndex":392,"id":"exchange-165"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ広く、いろいろな方たちとのコミュニケーションがとれる工夫をしていただきたいと思います。続きまして、日中一時支援事業についてお伺いしたいと思います。その上で質問をしていきたいと考えています。そこでお伺いしたいのは、タイムケア事業当時の実績と２０１２年度の実績の比較で、利用人数、利用者負担、事業者への人件費相当の補助費の変化を教えてください。","respondent":"中山障害者福祉課長","answer":"今回、にじのひろばにつきましては、最大で８時間以内であれば２,０００円、８時間から１１時間まででも３,０００円ということで、かなり安くなっていると考えているところです。","voiceIndex":394,"id":"exchange-166"},{"speaker":"井上委員","kind":"質問","question":"決算書で、利用者が今お答えいただいた人数で、結果的に２０１２年度は１.６倍の利用者になっているのですけれども、この事業の指導員の配置基準の考え方は、区はどのようにお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"職員の配置人数ですが、こちらはどちらも８人から９人の指導員を配置しています。ほかの、例えば通常の法内サービスと比較しても、十分な職員配置がされていると考えているところです。","voiceIndex":396,"id":"exchange-167"},{"speaker":"井上委員","kind":"質問","question":"事業費で、大きな支出というのは人件費になるかと思うのですけれども、今回２０１１年度と２０１２年度、２,０００人、１.６倍になったときに、品川区の人件費の補助が８９０万円で同じになっているのですけれども、時給換算８５０円くらいということで、課長の答弁が議事録に残っていましたけれども、この中で、利用者が４時間１,０００円で、人件費が４時間で１人３,４００円と計算すると。","respondent":"中山障害者福祉課長","answer":"そういった中では、まだ法人で対応できるのかと考えているところです。","voiceIndex":398,"id":"exchange-168"},{"speaker":"井上委員","kind":"質問","question":"先ほど人件費だけでお話をしたときに、３人のお子さんを１人で見てできるという金額の中で、単純に言って、相当難しいのではないかと思うのですけれども、そのようには、私の試算というか、計算が間違っているのか、その辺の認識はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"おっしゃるとおり、人件費としては８９７万６,０００円を想定しておりますが、全体の運営費補助というところでは１,７００万円を超える額を補助しております。そういった全体の枠の中で、ＮＰＯ法人で対応していただいているところだと、私は思っているところです。","voiceIndex":400,"id":"exchange-169"},{"speaker":"井上委員","kind":"意見","question":"本当にこれがなくなってしまうと、困ってしまうお子さんたちがたくさんいらっしゃるので、その辺はお願いしたいと思います。ちょっと時間がありますので、地域配食サービスが、大分利用が下がっていると思いますが、そこのところについて、今後見直しをされるのか、どのようにお考えなのか、残っている時間でお願いします。","respondent":"永尾高齢者福祉課長","answer":"区の分析としては、民間のお弁当屋や食事を配送するような業者がいろいろできておりまして、そういうメニューを見ますと、かなりきめ細かくできるようになってきています。糖尿病対応だとか、刻みとか。そういうところから見直しをしたいと考えています。","voiceIndex":402,"id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は成果報告書から３点伺います。それから、今後の展開についても、あわせて教えてください。それから、ページが戻りますが、１２３ページの特別養護老人ホーム建設費助成につきまして、９月１５日くらいの新聞に出ておりましたけれども、厚労省で、東京都について規制緩和を、そういう動きがあるというふうに伺っていますが、それについての内容と、区の考え方を教えてください。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"もう一つの、特別養護老人ホームのプレスのお話ですけれども、東京都の場合、地価が高くて土地の確保が非常に難しいということで。就労指導する年齢についてのご質問ですが、国の通知によりますと、１５歳から６５歳となっております。ただ、高校に進学された方は高校卒業後ということになると思います。","voiceIndex":405,"id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問","question":"そうすると、これは財源的なものとか、費用の部分での課題というよりは、どちらかというと各地域でどう進めていくかということのほうが、今、課題になっているということで思っておけばいいでしょうか。それから、特養については、今おっしゃっていただいた内容だと思うのですけれども、それについての区の考え方というか、これからどう考えていくかというのが、もしありましたら教えてください。","respondent":"永尾高齢者福祉課長、竹田生活福祉課長","answer":"支え愛・ほっとステーション事業ですけれども、財源は東京都のシルバー交番設置事業補助金を使っておりまして、現在２分の１の補助をいただいていますけれども、今後どうなるかというところは不透明なところもありますので。シルバーセンター等でご紹介を得て働いている方も大勢いらっしゃいます。就労支援の原則はあくまでも６５歳未満ですが、ご本人の希望に基づいて就労を妨げるものではございません。","voiceIndex":408,"id":"exchange-172"},{"speaker":"たけうち委員","kind":"質問・要望","question":"支援・ほっとステーション事業については、どうしてもやっている地域とやっていない地域で、正直サービスの格差が出てしまうのではないかという部分があるので、できれば全区展開をしてもらいたいと思いますので要望します。今のスタッフのマンパワーでは厳しいと思うのですけれども、考え方としてどうかと。そこだけ、最後にお答えいただきたいと思います。","respondent":"竹田生活福祉課長","answer":"生活保護受給者の方も、６５歳以上になっても社会参加に非常に生きがいを感じている方もいらっしゃいます。ぜひ、委員ご指摘のとおり、能力を最大限発揮していただいて、実りある人生にしていただきたいと考えております。","voiceIndex":411,"id":"exchange-173"},{"speaker":"本多委員","kind":"確認","question":"１２５ページの障害者福祉費について質問しますが、その前に１点だけ確認させてください。その辺の確認だけさせてください。","respondent":"立川保育課長、今井制度改革・待機児童対策担当課長","answer":"幼保一体施設、ぷりすくーる、また保育園、幼稚園におきましても、既存の施設につきましては、そのまま新しい制度に乗るということはできるです。ぷりすくーるにつきましては、認可を受けた保育所と、そして幼児教育施設ですので、そのままの形で幼保連携認定こども園になるのには、一定の課題があると認識しております。","voiceIndex":414,"id":"exchange-174"},{"speaker":"本多委員","kind":"質問","question":"わかりました。ありがとうございました。障害者福祉費について伺いますが、先日の国民体育大会の開会式で、障害者スポーツ大会の開会式は来週行われますけれども、先日の開会式で、障害のある方もない方も心ひとつにということで、障害のある方もない方もというフレーズが何回も何十回も出たのです。","respondent":"中山障害者福祉課長","answer":"委員ご指摘の健常者、障害者という言い方ではなく、障害のある人もない人もというところは、やはり障害者基本法の基本理念にのっとった、そういうところから来ている表現でないかと思います。","voiceIndex":417,"id":"exchange-175"},{"speaker":"本多委員","kind":"質問","question":"区として、今後どうかというのを聞きたかったのですが、後で教えてください。それと、障害者福祉の幾つか例を取り上げますけれども、聴覚障害者からこの間報告を受けまして、他人とトラブルになってしまって、聴覚障害がゆえにさらにそのトラブルが大きくなってしまったという報告を受けました。さらに、まだまだ障害のある方に対する理解というのを深めてほしいという意見をいただいたのです。","respondent":"中山障害者福祉課長","answer":"ノーマライゼーションの考え方にのっとりまして、品川区といたしましては、人権尊重都市品川宣言もありますし、障害のある方もない方もともに住みやすいまちづくりというのを築いていきたいということで、積極的にやってまいりたいと思います。","voiceIndex":419,"id":"exchange-176"},{"speaker":"本多委員","kind":"質問・要望","question":"よろしくお願いします。次に行きます。福祉施設や障害者支援施設の充実というのは求めていきますけれども、あれもこれもというふうになってはいけないと思うのです。","respondent":"中山障害者福祉課長","answer":"身体障害の方の通所施設であれば、そういった入浴の対応もできるところです。入浴ということだけに焦点を当てますと、施設に通っての入浴だけではなくて、訪問入浴ですとか、ヘルパーを介しての入浴といった手段もあります。","voiceIndex":421,"id":"exchange-177"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に、高齢者クラブのことを１点確認だけさせてください。高齢者クラブ１１３クラブへ助成が出ているということで、先ほども渡部委員から結成強化を求める声があったり、または、高齢者に対する食を通してきずなを深めるという渡辺委員からのお話もありました。前、活動の人のカウントによって算定されていたのが、公平性が課題だというのがあったので、公平性が保たれているかという確認だけお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"委員ご指摘の高齢者クラブの助成金の算定基礎ですけれども、やはり会員の人数、それから活動状況によりまして算定するということは、これまでどおりです。公平性を保った、そういう支援ということで行っているところです。","voiceIndex":423,"id":"exchange-178"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":110954,"voices":425}},{"id":"h25-20131007-4","meetingId":"h25-c-settlement","date":"2013年10月7日","dateIso":"2013-10-07","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 おはようございます。 ただいまより決算特別委員会を開きます。 それでは、平成２４年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"成果報告書１３８ページの予防接種費、１４３ページの不妊治療助成事業、１４６ページの資源持ち去り防止対策費、時間があったら１５０ページの中小企業ＩＴ化推進事業についてお伺いしたいと思います。１３８ページの予防接種費についてですけれども、主に子宮頸がんワクチンのことで何点かお伺いさせていただきたいと思います。","respondent":"伊津野保健予防課長","answer":"これが普通の任意接種の場合の救済制度であります。ただ、定期接種と比べまして、おおむね半額程度なので、品川区では自治体総合賠償責任保険に特約をつけまして、定期接種と同等程度の補償になるようにしております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"任意予防接種の健康被害ということで、きちんと区のほうでも制度を整備されているということですけれども、今回の子宮頸がんワクチンにおける副反応のケースというのは、いまだに原因がはっきりしないという点で、医師が診断書を書けないという部分もあったりして、大変問題になっています。この事態が発覚したのが５月か６月ごろだったかと思いますが、それから４カ月たった現在の状況についてお伺いします。","respondent":"伊津野保健予防課長","answer":"国のほうでもこの問題を大きく考えまして、現在では１１の大学病院で痛みについての専門外来というのを設置しまして、そこでの受診を勧めまして、原因を究明するような形になっております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"現在のような状況の場合、例えばもし本区で、仮定の話になってしまいますけれども、起きた場合というのは、もうわかってから４カ月たって、そうやって専門のところで見られているということですけれども、こういった場合の治療費というのは先ほどの補償制度の中から、定期予防接種と同様に出るということでよろしいのでしょうか。","respondent":"伊津野保健予防課長","answer":"残念ながら現在のところまだ因果関係がはっきりしていませんので、対象になっていないと聞いていますが、今後こういう１１カ所での診断とか原因究明が進んでいけば、補償の対象になる可能性はあると思います。","voiceIndex":8,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"実際、品川区では起きていないですけれども、こういった緊急でそれなりの医療費もかかるし、かなり病院を回られたり、患者さんは大変な思いをされているというとき、改めてこの補償制度というものが、適用されないから出ないというのではなくて、区としても緊急な場合の一時的な補償というのを考えられないかと思いますけれども、そのあたりのお考えはどうでしょうか。","respondent":"伊津野保健予防課長","answer":"杉並区のほうでも審査会を開いておりますが、なかなかすぐには結論が出ないという、難しい問題だと考えています。区では幸いなことにこういう事例はありませんが、もしあった場合はそういう対応も考えていきたいと考えています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問","question":"ぜひともそういった課題に対する万全の対応をお願いしたいと思います。次に、不妊治療助成事業についてお伺いします。区のほうの、今後の一般不妊治療に対する対応の考え方をお聞かせください。","respondent":"江部健康課長","answer":"国・都で実施しております特定不妊治療費の助成というものですが、考え方といたしますと、一般不妊治療につきましても妊娠しにくくなるということにつきましては同じかと思います。","voiceIndex":12,"id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"今、品川区では４９件の方が４３歳以上で受けられているということでしたけれども、この中で成功した方というのは大体何組いらしたのでしょうか。以前もお伺いしましたけれども、特定不妊治療にかかるお金に対して、区として、改めて年齢制限を設けての助成ということは考えられないのか、お聞かせください。","respondent":"江部健康課長","answer":"特定不妊治療のニーズがあることは存じ上げておりますが、一般不妊治療を受けられる方の数が、やはり特定不妊治療よりも多いということがあります。特定不妊治療については東京都の制度があるということから、今のところはそれぞれの役割分担があるという認識をしております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"沢田委員","kind":"質問・要望","question":"資源持ち去り防止対策費についてお伺いします。１,１１７万円余ですけれども、この決算の金額を改めて確認ということで、使われ方を確認させていただきたいと思います。それから、そういった資源持ち去り防止に対して効果が出ているかどうかということをお聞かせください。","respondent":"小林品川区清掃事務所長","answer":"その効果ですけれども、具体的に早朝、主に区民の方から情報をいただいている重点地区についてパトロールしている等によりまして、直近で申しますと持ち去りを含む指導を大体月当たり１００件程度行っておりまして、それに伴って抑止効果があるものと考えております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"沢田委員","kind":"意見","question":"平成２４年度決算のリサイクル資源売払収入というのが、平成２３年度から見て約２,０００万円、そして平成２５年度の予算では約７,０００万円減ってきておりますけれども、この資源売払収入が減少している原因と、これが例えば資源持ち去りによっての減少なのか、大体その資源持ち去りによってどれだけの損害が出ていると予想されておりますか。お聞かせください。","respondent":"小林品川区清掃事務所長","answer":"持ち去りの影響ということですが、大変申しわけないのですけれど、正確にそのうちどの程度が持ち去られているかということは把握できておりません。多くはパトロールの中で原状回復をしておりますが、若干一部がそのまま持ち去られているところは否めない、あるという現状です。","voiceIndex":20,"id":"exchange-008"},{"speaker":"沢田委員","kind":"意見","question":"ほかの自治体でも大変この持ち去りに苦慮されていまして、ＧＰＳを設置するというところもあったかと思いますけれども、それなりの効果が出て問屋をつかまえたり、持ち去りがそれで減ったという効果が出ていると聞いています。品川区でもこういったＧＰＳ発信機を取りつけて、取り締まりをさらに強化していくということも考えられるかと思いますけれども、そういったところのお考えをお聞かせください。","respondent":"小林品川区清掃事務所長","answer":"都下の市ではやっておりますし、区も数区で検討していると言われております。その実効性等、視認した後、どう対応していくかも含めて、今後研究してまいりたいと思います。","voiceIndex":22,"id":"exchange-009"},{"speaker":"つる委員","kind":"提案","question":"私からは、１４０ページ健康診査費、１４２ページ区民健康づくりプラン品川推進事業費についてお尋ねします。健康事業の延伸についてという角度でちょっとお尋ねしたいのですが、提案なのですけれど健康マイレージ事業、これを提案しようと本日準備をしていたのですが、聞いたところによりますと厚生委員会のほうで北九州市のほうに、健康マイレージ事業も含めて視察に行かれるということで伺っております。","respondent":"江部健康課長","answer":"委員ご提案のマイレージという、要は受けたらポイントになるというものが、地方を中心に今広がっているというお話ですが、実際品川区としてこれについてと言われましても、現段階では意見は今のところ持っておりません。申しわけございません。","voiceIndex":25,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"さきの８月２１日に政府の閣議決定された中の、社会保障制度改革推進法第４条の規定に基づく「法政上の措置」の骨子について、こういった閣議決定された中に、その中の医療制度のところで、健康管理や疾病予防など、自助努力を行うインセンティブを持てる仕組みの検討など、個人の主体的な健康の維持、増進への取り組みを奨励する、こういう記載がありますので。","respondent":"亀井品川保健センター所長、伊崎子育て支援課長","answer":"これは品川保健センターで年間２０回、荏原保健センターで年間２０回、大井保健センターで年間５回、ご夫婦で参加していただいて、沐浴実習、赤ちゃんをお風呂に入れるという実習をやったり。イクメンという名前はついていないですけれども、父親の子育て参加促進講座といたしまして、児童センターのほうでも行っております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"児童センター等では、今ご答弁があった中であるかもしれませんが、そうした部分で例えば子どもの健診、１歳６カ月とか３歳児健診があると思うのですが、こういう機会を通じて、いわゆるイクメン交流会、こうしたものも検討してみてはと思いますけれども、いかがでしょうか。","respondent":"亀井品川保健センター所長","answer":"確かにおもしろいというか、いい提案であるかと思いますが、例えば乳児健診でも１組、２組、ご両親でいらっしゃる方とかいらっしゃいますけれども、なかなか交流会というか、そこまでまだ健診に参加していただいたり、育児学級などでもまれに。","voiceIndex":30,"id":"exchange-012"},{"speaker":"つる委員","kind":"提案","question":"ぜひ、いろいろな知恵を絞っていただいて、工夫していただきたいと思います。次に産後ケアセンター、これについては公明党の会派からも提案しています。一般社団法人ドゥーラ協会というところで、産後の家庭への紹介やドゥーラの養成をしているということなのですが、品川ではこのドゥーラについてのご認識はいかがでしょうか。","respondent":"亀井品川保健センター所長","answer":"ただ、品川区の産前産後のケアについての実情をお話しさせていただければ、妊娠中から地区担当の保健師が訪問をしたり、産後もすくすく赤ちゃん訪問であるとか、そういうことでいわゆる施設型のサービスではありませんけれども訪問したり。","voiceIndex":32,"id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"初めての提案なので、またいろいろと調査、研究していただきたいと思います。次に、ことし妊娠中の夫婦が参加する育児教室などで活用してもらおうという趣旨で、厚生労働省から配布されている、乳幼児揺さぶられ症候群予防啓発ＤＶＤ、「赤ちゃんが泣きやまない～泣きへの理解と対処のために～」があると思いますが、この活用状況を教えてください。","respondent":"亀井品川保健センター所長","answer":"赤ちゃんが泣くのが一番大変なのは一、二カ月ぐらいのときなので、そのころにどういう形でこのメッセージを伝えるかということなのですけれども、これを監修された先生の、これの非常にコンパクトなパンフレットがあるのですけれども、そういうものを活用して。","voiceIndex":34,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"時間がありますので、１４９ページ、観光アクションプラン推進事業に行きたいと思います。聞くところによりますと職員の方も何名か、この天王洲で見られたというふうにも伺っております。非核平和都市品川宣言をしている品川区として、世界から悲惨な核をなくすこのシンボル的取り組みとして、この花火大会をぜひ検討していただきたいと思いますが、このあたりいかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういう中で昨日も非常に観光協会を初め、あちらの場所で打ち上げるに当たっては、いろいろな調整、苦労をしてあそこまでに至ったものです。今年の経験をまた来年に結びつけていこうということで、観光協会とも連携しながら今後のあり方を探ってまいりたいと思います。","voiceIndex":36,"id":"exchange-015"},{"speaker":"木村委員","kind":"質問・要望","question":"１４４ページの環境対策費からの質問をいたします。下から２行目、太陽光発電システム等設置助成、２,９１３万円余ですが、この事業、以前は都市計画課のほうで行っていた事業と聞きました。平成２３年度から環境課になったとのことですが、この事業、ＣＯ２削減が目的の一つだと思いますけれども、一応この事業の趣旨を、３・１１の大震災との関係もございましたらお聞かせいただきたいと思います。","respondent":"野呂瀬環境課長","answer":"３・１１以降、省エネに取り組んでおりますけれども、発電する、いわゆる自然エネルギーが脚光を非常に強く浴びてまいりまして、ますます私どもとしても取り組んでいきたいと思っているところです。","voiceIndex":40,"id":"exchange-016"},{"speaker":"木村委員","kind":"意見","question":"３・１１以降、節電とかそういうことでいろいろ、省エネ、省エネという形で動いておりますけれども、この事業の終点、終点という言葉も変ですけれども、どこに設定している事業なのか、そして太陽光発電システム等のこの「等」というのは、ほかにどういうものがあるのか、これもご説明ください。","respondent":"野呂瀬環境課長","answer":"あくまでも低炭素社会の実現のために、その普及啓発事業の一環として取り組んでおりまして、社会変化等の状況を見極めながら進めていく、このように考えているところです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"木村委員","kind":"意見","question":"今年の９月に、スポーツの祭典である２０２０年、２度目となる東京オリンピックの開催が決定されました。この品川区も同じでありますけれども、スポーツを通じて世界と手をつなぐには、環境整備は大変意義のある事業だと思いますけれども、まずはここ品川から、大きく変動させるべきと考えますけれども、行政としてのお考えをもう一度お聞かせください。","respondent":"野呂瀬環境課長","answer":"３・１１の事故でなかなかその目標がままならないところはありますけれども、オリンピックに向かって日本という国が、また東京が、スポーツの祭典もそうですけれども、環境都市として、いわゆる環境にやさしい都市だということを全世界にアピールできる。","voiceIndex":44,"id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"３キロワット仕様で大体１５０万円程度するということをお聞きしましたけれども、９万円の助成で残りが１４０万円近くですけれども、太陽が出ている時間帯に発電するわけですけれども、日中家族全員が外出している間は、冷蔵庫等で使っている電力以外は電気を貯めておくことができるようになっているのかどうか、そしてできないのであれば、日中の発電というものは大変無駄になると思いますけれども。","respondent":"野呂瀬環境課長","answer":"助成金額ですけれども、平成２４年度は平成２３年度と一緒です。平成２５年度、本年度から、委員がおっしゃったとおりキロワット当たり１０万円が３万円と。これにつきましては当然製造コストが下がったとか、パネルが軽量化して設置工事代金等も以前に比べて安くなったです。","voiceIndex":46,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"売電するということでありました。３・１１以降、昨年そして今年の夏も猛暑となりましたし、区民の皆様も相変わらず、特に高齢者の方々、節電に協力していただいていると思います。３・１１以降、本区役所も節電していると思いますけれども、まずはやはり模範となるべき行政が先頭になって、できる限り節電をするべきと思いますけれども、行政としてのお考えをもう一度お聞かせください。","respondent":"野呂瀬環境課長","answer":"品川区の中では、他の自治体と違ってメガソーラー、大規模な発電システムについてはなかなか難しいということで、お答えさせていただいたと思います。","voiceIndex":48,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問・要望","question":"そういうふうに前向きな姿勢でどんどんとやっていただきたいと思います。これから東京オリンピックに向けて、いろいろな事業が始まると思います。いろいろな事業があると思いますけれども、それも一つとしてお願いしたいと思います。","respondent":"野呂瀬環境課長","answer":"すみません、節電につきましても同じように取り組んでまいります。","voiceIndex":50,"id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"１４０ページの犬の登録・予防注射、１４７ページの雨水利用タンク設置助成事業、同じく１４７ページ、その下の区有施設等雨水利用タンク整備事業についてお伺いいたします。ここで質問です。区のこのマイクロチップに関しての見解と、その装着状態をご存じでしたら教えていただきたいのと、マイクロチップの読み取り体制の整備状態も教えてください。お願いします。","respondent":"高山生活衛生課長","answer":"今年度、かつて獣医師会に入られていた動物病院の方から、マイクロチップの読み取り機についてご寄附をいただきまして、区としましてはそういったもので読み取りができるような形で、体制をとっているところです。","voiceIndex":53,"id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"東日本大震災では多くのペットたちも被災しまして、現在でも原発被害により設置された警戒区域内では、取り残されたペットたちの保護活動が続いております。では、先ほど答弁いただきました、ご寄附いただいた個体識別の読み取り機ですが、具体的に保健所のほうですとかに置いていただいて、これから始めていくのでしょうか。その辺のこれから将来に対しての取り組みなどをお願いいたします。","respondent":"高山生活衛生課長","answer":"は区に１台ご寄附いただきましたので、有効に活用するということが一つと、各動物病院におかれましても、通常そういった読み取り装置を備えていただいているというふうに伺っておりますので、災害時も含めて、平時とあわせて活用されるものと考えております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"先ほども申しましたけれど、２７件、１８件と、効果がどのぐらいあるのか、つけた方への聞き取り、またアンケートなどございましたらお聞きしたいのですけれど、お願いします。","respondent":"奥田河川下水道課長","answer":"例えば１件つけていただいた方が、別のところに２件つけたいという方もたびたびありますので、非常に有効的に活用されているのではないかと考えています。","voiceIndex":59,"id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"この間の台風のようなとき、想定外の雨量とかに対して、浸水被害の軽減とかの効果があるのかお伺いしたいのと、これで一番気になるのはボウフラ対策などもあるのかと思いました。その辺をお願いいたします。","respondent":"奥田河川下水道課長","answer":"個人の方がつけていただくだけでなくて、区のほうでも実は個人の方の設置促進のために中学校ですとか小学校に、こちらはもっと規模が大きい１,０００リットルとか５００リットルみたいな形でつけてあります。","voiceIndex":61,"id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"やはり件数だけを見てしまうと、魅力がないのかとちょっと考えてしまう部分もあるのですね。これはＰＲ不足ではないかと思ってしまうのですが、やはりいいことであればぜひ皆様にもお使いいただいて、たくさん設置していただければ、水のリサイクルもあり、また災害にもということでしたら、ＰＲに関しての努力などお聞きしたいのですが、お願いします。","respondent":"奥田河川下水道課長","answer":"これまでＰＲといたしましては、委員からご指摘ございましたように広報しながわにも当然載せてありますし、区のホームページですとか、東京都と連携いたしまして毎年雨期前の６月の浸水対策強化月間、あと庁舎の相談窓口にはチラシなどでもＰＲしてきてあります。","voiceIndex":63,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"たくさんＰＲしていただいているみたいですけれど、なかなか区の方がこういうのがあるといっても、これを伺ったきっかけは「広報に載っていたので、どんなの」と聞いてくださったものですから取り上げさせていただきましたけれど、さまざまな場所で周知して、増やしていっていただきたいと思います。","respondent":"奥田河川下水道課長","answer":"効果につきましては、おおむね５００リットルとか１,０００リットルという形でつけておりますので、幼稚園とか保育園では教育の目的にもなりますし、雨水の利用と浸水被害の軽減に大きな効果を発揮するものと考えています。","voiceIndex":65,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"私からは、成果報告書１５１ページの商店街活性化推進事業にかかわって、商店街の活性化と商店街装飾灯について伺いたいと思います。伺いたいのは、その指標として、商店街の中で生鮮三品が一つもない、またはほとんどない、そういった商店街は幾つあるのか、品川区にある商店街の総数、そしてその中で生鮮三品が一つもない、ほとんどない商店街数を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"商店街の数ですが、現在１０８商店街ということでありますけれども、こちらの中でいわゆる生鮮三品がないということで明確に数字があるわけではございませんが、この間生鮮三品店支援事業を行っている中で、区商連のほうとも全体的に、いわゆる八百屋、果物屋、肉屋。","voiceIndex":69,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"とりわけひとり暮らしのお年寄りから、そういうお話もよく伺います。生鮮三品がなくなっている、あるいはぎりぎりの状態であると。この生鮮三品だけでなく、よく自分のまちにあったらいいなと、消費者として、住民としてあったらいいなとお年寄りからも子育て世代からもよく伺うのが、お総菜屋、パン屋、豆腐屋、ケーキ屋など加工するお店というのでしょうか、これはよく伺います。","respondent":"米田商業・観光課長","answer":"ご指摘のありました、今後生鮮三品店以外にどういう形態での支援ができるかということは検討しますが、今既にマイスター店支援事業の中で、過去においてパン屋やお菓子屋にスポットを当てたお店の紹介ですとか、夜。","voiceIndex":71,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひそこをつなげる仕組みを考えていただきたいと思いますので、改めて伺いたいと思います。私はこの事故の負担を商店街に負担させるのはとんでもない話だと思いますけれども、この電気料金値上げ分について、商店街の負担とならないよう助成額を引き上げていくべきだと思いますけれども、あわせて伺いたいと思います。","respondent":"米田商業・観光課長","answer":"商店街連合会とも十分連携をとりまして、地域に出店をしたいという方がいらっしゃった場合には、こちらの部局ともども、親身になってご相談をさせていただいて、商店街に連続性を持たせてにぎわいが創出できるようにということについては。","voiceIndex":73,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、今頑張っているお店、これから新規にオープンするお店、その個店への支援を進めていただきたいと思うのと、原発事故に伴う電力料金の値上げ分を商店街が負担することのないよう、区の助成額を引き上げていただきますよう強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"１４０ページ、女性の健康診査のことについてお伺いしたいと思います。事務事業概要のほうを見ますと、１６歳以上、平成２４年ですから４０歳未満の女性の区民の方で、括弧書きで勤務先等で受診機会のない方が対象者になっています。それでどのぐらいの受診者数かというのが３年間分出ていて、このページにも２,２４０人というのが出ています。","respondent":"江部健康課長","answer":"もうどんどん、どんどん女性の社会進出がされますと、企業での労働安全衛生法での健診を受ける方が、数字的にちょっとつかんでおりませんが相当数いるだろうと思います。ということで、現実的には受診率はかなり低い、このような数字になっているものと思われます。","voiceIndex":77,"id":"exchange-032"},{"speaker":"渡部委員","kind":"質問・要望","question":"そうですよね。結局この受診者数というのは多いか少ないかという、評価のしようがないのかと思ったのが一つ。ということは、次にお伺いしたかったのが、この健康診査についてどういう周知をされていますか。そういう女性の方々に対してどういうふうに、こういう仕組みがありますよというのをお伝えになっているか、教えてください。","respondent":"江部健康課長","answer":"各診療所、２００数カ所ありますけれども、そこで周知するということの意味は、ご本人は行かなくてもご家族だったり、知人が行くであろうということで、まずやっているのが一つです。","voiceIndex":79,"id":"exchange-033"},{"speaker":"渡部委員","kind":"質問","question":"子宮頸がんの検診でしょうか、２０歳以上の女性の方には通知が行きますよね、そのときにでも一緒に、女性の方の健康診査はこういうものがありますよと、例えば三十何歳の乳がん検診が始まるときに、こういう診査がありますよと。これは毎年受けられるわけですから。もし入っていれば、それで周知としてはその世帯には行くのだろうけれど、入っていなければ、入れたらいかがですかということですが。","respondent":"江部健康課長","answer":"それも一つかと思います。委員ご指摘の件は検討します。","voiceIndex":81,"id":"exchange-034"},{"speaker":"渡部委員","kind":"質問","question":"その半面、例えば診療所に行きました、保険証を持って普通の病気か何かでかかっているときに目にした、それで１６歳から、今は３４歳まで受けられると、勤務先等で受診機会がない者と書いてあるけれども、私、２３歳だから、ちょっとこの健診をお願いしますといったとき、医療機関のほうで、この人は働いているか、保険証の種類によってはわかりますけれど、わからないケースというのはあるのではないですか。","respondent":"江部健康課長","answer":"確かに勤めているけれども、会社でやる機会がないという方がいらっしゃれば、受けていただくように医師会のほうにお願いしており、各医療機関でそのような対応、実際に診察するときに、健診を受けたいということであれば、では健診しましょうということで。","voiceIndex":83,"id":"exchange-035"},{"speaker":"渡部委員","kind":"意見","question":"すみません、意地悪な聞き方を一つしますけれど、そうしたら会社で受けていてもこの健診は、要するにその人のモラルですけれど、受けさせてくださいと言ったら受けられてしまう仕組みということですね。","respondent":"江部健康課長","answer":"検査項目はかなり限定的でございまして、女性の健康診断は、血液検査と問診等に限ります。我々が職場でやりますと、身長、体重、目とかさまざまありますが、かなり限定的なので、そういうこととは差別化されているというふうに認識しております。","voiceIndex":85,"id":"exchange-036"},{"speaker":"渡部委員","kind":"質問","question":"もともと今回は、本質的な受診率というのがどの程度とれるかわからないと思っての質問でしたので、なるべく広報等で広くお知らせいただければと思います。これはページ数といいますか、商業・観光の全般のことでお伺いしたいと思います。競馬場といわゆる品川区の関係、商業・観光の面でのことでお伺いしたいと思います。８月にオクトーバーフェストをやっていました。お願いします。","respondent":"米田商業・観光課長","answer":"現在行っている取り組みといたしましては、外国人向けの観光情報冊子に競馬場のご紹介をさせていただいたり、あるいは商店街との連携も含めまして、地元の商店街がそちらの会場に行きまして、飲食店を中心に出店していただいて、あるいはお帰りのときは出店していない。","voiceIndex":87,"id":"exchange-037"},{"speaker":"渡部委員","kind":"質問・要望","question":"今年になって初めてそういう交流が始まったのか、それで１１月に区長賞があるわけで、さまざまな交流が始まったというイメージがある中で、プロパティサービスとお話をさせていただいて、飲食店の方ともお話したのですけれど、立会川の商店街の単発的な小規模商店街支援、それも８月にというのもお伺いしたんですけれど、例えばそういうところは、プロパティサービスも当然民間ですから、区商連。","respondent":"米田商業・観光課長","answer":"今ご提案の趣旨は十分検討いたしますが、ある程度財政的な負担が出てくるような形が何となくいたしますので、その辺も含めましていろいろ検討してまいりたいと。","voiceIndex":89,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問・要望","question":"まさにおっしゃるとおりだと思います。しかしながら、例えば区商連の方々と、プロパティサービスの中の飲食店の方々との協力体制とかができれば、費用負担が少ない中で、仕入れルートの確保だけですよ、あとはそこでご商売、商品を売っていただけるかどうか。この間行ったときは、残念ながら３千何百人の来場者だと言っていました。もう一言よろしくお願いいたします。","respondent":"米田商業・観光課長","answer":"そういったいろいろな積み重ねがどうしても大事となってくるかと思いますが、委員ご提案の趣旨も今後検討の材料に含めさせていただきながら、区商連とも相談いたしまして、区内の産業の発展に寄与するものであれば、取り入れてまいりたいと考えているところです。","voiceIndex":91,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問","question":"私からは、１４０ページの犬の登録・予防注射、これは犬のふん害についてお伺いしたいと思います。そこで品川区として今、犬の登録・予防注射ということで年１回予防注射のために、飼い主との接触というか接点がありますけれども、この犬のふんの対応について、どのような対策等、現状なされているものがあるのかお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"こういったことの対策としましては、もちろんまずは飼い主における適正な飼育ということが最重要となってまいりますが、区といたしましてはまず現地に看板類の設置、そういった困り事を保健所として、飼い主に対する適正な飼育の文面の紹介でありますとか。","voiceIndex":95,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"なぜかというと、どうせ回収してくれるんだから放置しておいてもいいんだということで、かえってこういうことになったということで、非常に難しいと頭を悩ませていたそうです。この泉佐野市は兵庫県高砂市の取り組みを参考にいたしました。こういった取り組みは、非常に参考になるし、有効なのではないかと私も認識を改めたところなんですけれども、区としてどのようにお考えなのかお伺いしたいと思います。","respondent":"高山生活衛生課長","answer":"そういったことは犬の飼い方、しつけ方の教室などを通じまして、これまでも普及を図っているところですので、そういった飼い主に対します犬の生理、習性を踏まえた飼い方、散歩の仕方なども今後普及してまいりたいと考えております。","voiceIndex":97,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"このレインボーブリッジの外側ということになりますと、かなり品川区とは密接に、というかほとんどもう品川区につくるのではないかという思いもありますが、この東京港クルーズ客船誘致促進ビジョンにつきまして、区として具体的な、どこにできるのかとか、工事がいつごろから始まって、いつごろできるのかとか、こういった情報はどの程度つかんでいらっしゃるか、わかる範囲で教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"今後、その新たな船着き場については、やはり晴海に近いところで設置するということを打ち出しているということで、聞いているところです。","voiceIndex":99,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"わかりました。こういった観光客がたくさん外国からやってくるということについては、今後その観光客をしっかり品川区内に誘致していく、誘導していく取り組みが必要かと思いますので、今後ともその取り組みについてはぜひ検討していただきたいと思います。そういった品川区の将来にぜひ花を添えるという意味で、花火大会の開催というのを私からもぜひ要望したいと考えています。","respondent":"米田商業・観光課長","answer":"今現在ああいう形でやっていて、それがもしかしたら見る方には物足りないかもしれませんが、観光協会ともこれをまた積み上げていこうということで、昨日も会話をして別れておりますので、今後もそのような形で十分検討してまいりたいと思ってあります。","voiceIndex":101,"id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"それに対しまして、区としての対応をどう考えられているかということもお聞きします。次に商店街活性化事業です。それから武蔵小山創業支援センター、女性起業家支援は今どうなっていますかということ、それからウーマンズビジネスグランプリの３回目を来年するということになっていますが、これらの過去２回において成果があったのか、ないのかについて、まずお聞きいたします。","respondent":"伊津野保健予防課長、米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"子宮頸がんワクチンの対象者ですが、平成２４年度はまず新規としましては中学校１年生の１,０９１名、２０歳としましては１,２２１名を対象としました。商店街の支援の基本的な考え方ですけれども、商店街はやはり先ほども申し上げましたが、近隣でお買い物をされる方の。起業家の支援につきましては、大体３カ月の工程で土曜、日曜を毎週使っておりまして、延べ１４回で、起業に関しての基本的なことから。","voiceIndex":104,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"子宮頸がんワクチンは、失神ですか、副反応はどこまで把握されているんですか。だけど商店街としたときに、どう評価するんですかということなんですね。それに対して、品川区は商店街をどう捉えていくんですかということが一つ。ですからその評価についても、しっかりと提示していくべき時期に来ているのではないか。それから、女性起業家、これは実際に商売が成り立っているところはあるんでしょうか。","respondent":"伊津野保健予防課長、米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"もし発生していれば、先ほど答弁しましたように、審査会を開くなどの対応をしていきたいと考えております。いわゆる新たな支援ということにつきましては、いろいろ商店街連合会等も含めて商店街支援のために有効な施策があるかということは。それからウーマンズビジネスグランプリでは、昨年ファイナルに出まして、これは歯科医の方ですけれども先月。","voiceIndex":108,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"品川にぜひ店舗を出していただけるようにお願いしたいということと、それから子宮頸がんワクチンはきちっと対応できるようにしていただきたいと思います。商店街については、いろいろな助成金のやり方をやはり再考していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"意見","question":"本日は成果報告書の１３９ページの定期予防接種、同じく任意予防接種、同じく感染症予防費のうちで感染症対策費、１４０ページの肝炎ウイルス検診に関連してお尋ねします。任意予防接種と健康診査の肝炎ウイルス検診から、Ｂ型肝炎についてお尋ねいたします。Ｂ型肝炎について、簡単にご説明をお願いいたします。","respondent":"伊津野保健予防課長","answer":"Ｂ型肝炎は、患者の血液や体液によりましてＢ型肝炎ウイルスを感染しまして、症状としましては倦怠感、黄疸、腹痛などの症状を起こします肝臓の病気であります。","voiceIndex":114,"id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"意見","question":"感染すると急性肝炎になり、劇症型ではそのまま死亡しますが、山を越えれば１カ月ほどで回復します。現在世界中で２０億人の感染者がおり、大体世界中で３.５人に１人はＢ型肝炎ウイルスに感染したことがあると言われております。品川区の肝炎ウイルス検診の受診者数、およびその中でＢ型肝炎ウイルスの陽性者数と、陽性率についてお尋ねします。","respondent":"江部健康課長","answer":"肝炎ウイルス検診実績は４,１７２件でございまして、陽性者は１６人、０.４％です。","voiceIndex":116,"id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問","question":"肝炎ウイルス検診は、Ｂ型とＣ型と行っておりまして、今、健康課長からのお返事があったのは、お聞きしたＢ型肝炎ウイルスのことだと思います。肝炎ウイルス検診受診者の中で、Ｂ型肝炎には大体０.４％が陽性になっております。Ｂ型肝炎ワクチンは現在任意接種に位置づけられておりますが、我が国では現在どのような方が、Ｂ型肝炎ワクチンを主に接種しているのか質問します。","respondent":"伊津野保健予防課長","answer":"我が国におきましては、妊娠中にＢ型肝炎ウイルスの抗体をはかりまして、感染しているかどうかを検査します。妊婦が感染していた場合、生まれてくる赤ちゃんに対してリスクが大きいということでワクチンを、健康保険の適用で接種しております。","voiceIndex":118,"id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問","question":"母親からの感染例は、抗体の注射がうまくいかなかったことと、ワクチンが何らかの理由で効果を上げられなかったということですが、３分の１はこのような事業である母親への措置と無関係に、Ｂ型肝炎に感染しております。世界保健機関、ＷＨＯはＢ型肝炎ワクチンについて、今どのような方針を推奨しているのでしょうか。我が国で現在、Ｂ型肝炎の患者は、どのような年齢層に多く見られるのでしょうか。","respondent":"伊津野保健予防課長","answer":"ＷＨＯでは、先ほど申しましたようなリスクの高い赤ちゃんのみならず、そういうことに限定することなく、全ての赤ちゃんにＢ型肝炎ワクチンの接種を勧奨しております。Ｂ型肝炎ですが、我が国でも２０代から３０代の男女ともに、その年代に多い感染を示しております。","voiceIndex":120,"id":"exchange-050"},{"speaker":"鈴木（博）委員","kind":"質問","question":"東京２３区内でも本年４月１日から、渋谷区が１回５,０００円の一部助成を始めました。ぜひ品川区でもＢ型肝炎ワクチンの大切さを理解して、品川の子どもたちがＢ型肝炎ウイルスに感染し、持続感染を起こし、一生苦しむことがないように、定期接種化されるより以前に接種費用の助成を始めてほしいと考えております。区のご見解はいかがでしょうか。","respondent":"伊津野保健予防課長","answer":"この４月から、そのうちの３つのワクチンでありますＨｉｂワクチン、小児用肺炎球菌ワクチン、子宮頸がんワクチンについて定期化されたところであります。残りの４つのワクチンにつきましても、国の動向を見据えながら検討していきたいと考えております。","voiceIndex":122,"id":"exchange-051"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"わかりました。ぜひ積極的にご検討をお願いしたいと思います。それと、先ほど保健予防課長のご答弁にありましたように、Ｂ型肝炎は２０代、３０代に現在発病のピークがあります。エイズ予防啓発事業の中で、ぜひＢ型肝炎の正しい理解と、Ｂ型肝炎あるいは肝炎の検査の勧め、それと任意接種でありますがワクチンの積極的な接種の勧奨を行っていただきたいと考えますが、区のご見解はいかがでしょうか。","respondent":"伊津野保健予防課長","answer":"Ｂ型肝炎は、先ほど申しましたように２０代、３０代に感染のピークがありますし、多くは性交渉によって感染するということですので、エイズ予防啓発の中で、予防あるいはワクチンの接種を考えていきたいと考えております。","voiceIndex":124,"id":"exchange-052"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ぜひＢ型肝炎に対する理解と積極的な取り組みを区に強く要望いたしまして、次の質問に移りたいと思います。次に、成果報告書１３９ページの定期予防接種、同じく１３９ページ感染症対策費に関連して、風疹対策について質問いたします。さしも猛威を振るった風疹の大流行も、９月に入り下火になってきたようです。日本全国、東京都、品川区のこの夏以降の風疹の流行状況は、現在いかがでしょうか。","respondent":"伊津野保健予防課長","answer":"風疹の流行状況でありますが、全国、東京都とも７月までは高い発生数が見られましたが、８月になってやや減少傾向にありました。最新のデータでは全国で２８名、東京都で８名の発生が見られております。","voiceIndex":126,"id":"exchange-053"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ようやく患者数が減少し、ゼロ名になったようですが、これは風疹の流行がおおむね終息したと考えてもよろしいのでしょうか。それともまだまだ十分な警戒が必要と考えるべきなのでしょうか。ご見解を伺います。","respondent":"伊津野保健予防課長","answer":"今回の風疹の流行によりまして、風疹の抗体を持っていない方が全て抗体を持ったかというと、そこまでは言えないと思いますので、まだまだ今後の流行には注意を払う必要があると考えております。","voiceIndex":128,"id":"exchange-054"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そもそも風疹とはどういう病気なのか、あわせて今回の流行も終息に向かっておりますので、今回の風疹の流行について簡単なまとめをお願いします。","respondent":"伊津野保健予防課長","answer":"特に妊娠初期に感染しますと、胎児に大きな重い障害を起こす可能性が高い病気であります。今回の流行の特徴でありますが、制度的に風疹ワクチンを接種する機会がなかった、あるいはあっても接種率が低かった２０代から４０代の男性を中心とした流行でありました。","voiceIndex":130,"id":"exchange-055"},{"speaker":"鈴木（博）委員","kind":"質問","question":"風疹感染の最大の問題は、先天性風疹症候群の赤ちゃんの誕生です。２０１３年１０月現在、今回の流行で何名の先天性風疹症候群の赤ちゃんが生まれているのでしょうか。この先天性風疹症候群のお子様は、今後どのように生きていかれることになるのでしょうか。この先天性風疹症候群のお子様は、これからも続々と生まれる可能性、危険があるのでしょうか。あわせてお尋ねします。","respondent":"伊津野保健予防課長","answer":"この赤ちゃんにつきましては、今後重い障害を持って生活されることを余儀なくされるものと考えております。流行は、一旦おさまったというふうに考えられますが、妊娠中の障害ですので、これからこのような先天性風疹症候群の患者さんが増えることは予想されます。","voiceIndex":132,"id":"exchange-056"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今回の風疹流行の総括は、２０代から４０代の風疹の抗体を持たない青年男子が流行の中心になったことであります。この層は２００７年の麻疹大流行の際も流行の中心となり、多数の麻疹患者が出たことは記憶に新しいところです。昨年の２０１２年の風疹の流行の際も、７月をピークにしまして患者数は一旦減少しました。品川区の現在の風疹流行対策をお尋ねします。","respondent":"伊津野保健予防課長","answer":"東京都の流行は全体としては落ち着いたものの、品川区の流行につきましてはまだ続いておりましたので、妊婦の夫につきましても急遽女性と同じく、来年３月末まで助成を延長するように決定いたしたところであります。","voiceIndex":134,"id":"exchange-057"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"妊婦の夫に対する風疹ワクチンの全額補助を継続する対策は、その意味で非常に評価される施策だと思います。お母さんのお腹の中の赤ちゃんが、風疹に感染する機会を少しでも減らせるように、最も感染源となっている、風疹抗体をあまり持っていない２０代から４０代の成年男子に対する対策の強化を強く要望しまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-058"},{"speaker":"向委員","kind":"質問","question":"私からは、成果報告書の１３８から１３９ページ、予防接種費、感染症予防費、感染症対策費に関して、それから１４１ページ母子健康診査費、妊婦健康診査に関連して、それから１４２ページの健やか親子学習、マタニティクラスなどに関してまずお伺いします。風疹について主にまずお尋ねしたいんですが、先ほど別の委員からも詳しく質疑がありました。このあたり曜日に違いがある理由を教えてください。","respondent":"伊津野保健予防課長、江部健康課長、亀井品川保健センター所長","answer":"ですから、妊娠中の母親にはワクチンを接種することができないので、仕方なく妊娠されている夫にワクチンを接種するということです。それから出生届につきましては、我々としては４カ月健診の数字で押さえてありますが、対象者は３,３４６名です。私からは健やか親子学習のマタニティクラス、母親学級と二人で子育てについてご説明申し上げます。","voiceIndex":139,"id":"exchange-059"},{"speaker":"向委員","kind":"質問・要望","question":"風疹の助成はあくまで緊急対策ということはわかりました。風疹の流行が春から夏にかけてだったので、そこでかかってしまった赤ちゃんが生まれるとすれば、今ごろの時期から冬にかけてということで、２３区内でも４カ月健診ですか、早期発見を進めるために対策に乗り出している区も、墨田区とかあるみたいですけれども、品川区ではどういう対策を、もしされているものがあれば教えてください。","respondent":"伊津野保健予防課長、江部健康課長、亀井品川保健センター所長","answer":"症状が重い方は出生直後すぐわかると思いますが、軽い難聴とかは、保健センターで行います４カ月健診とかそのあたりで。国のほうの統計でいいますと、十五、六％が流産という数字が出ておりますので、残りの部分は多分、転出ですとかの理由なども考えられると思います。ただ、もう一つの見方として、ワークライフバランスというところから考えていくと、ウイークデーに仕事をして。","voiceIndex":143,"id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"先に母親学級の件ですが、理想というか希望はあります。そういったお母さんたちは、次の妊娠に向けて準備を進めます。でもそういうお母さんたちやご家庭、夫である配偶者については、予防接種は何も対策がとられないということにもなりますので、改めて質問しますが、そのあたりのあいているところなどもフォローできるようなことを、検討していただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-061"},{"speaker":"こんの委員","kind":"質問","question":"私からは、１３８ページの予防接種費、そして時間があれば１４６ページのみどりの保全事業をお聞きしたいと思います。そこでこの接種をするに当たっての予診票なんですけれども、例えば品川区民が他の自治体の医療機関で、他の自治体の予診票を使用して接種した場合、費用はどうなるのか、あるいはその予診票の扱い方はどうなっているのか教えてください。","respondent":"伊津野保健予防課長","answer":"特別区、２３区の中では相互乗り入れという形で行っておりますので、そのまま費用負担なしで受けることが可能であります。それ以外の自治体におきましては、一度お金を払っていただきまして、償還払いという形で行っております。","voiceIndex":149,"id":"exchange-062"},{"speaker":"こんの委員","kind":"質問","question":"２３区ではそうだということですが、他の自治体でもしあった場合は、後でお返しするという形をとっていると。でも今お聞きするところでは、２３区はそうではないということなんですが、いわゆる予診票ですね、この自己負担なく、定期接種ですからだれでも公平に受けられる体制というのが必要だろうと思うんです。それをお聞きしたいと思います。","respondent":"伊津野保健予防課長","answer":"今までは６種類か７種類だったんですが、先ほどおっしゃいました３ワクチンが増えましたのでかなり混乱して、各区の独自の予診票ですので、かなり混乱して事務作業に支障が起きるということで、とりあえず２３区の中で何とか統一できないかという形の検討は始まっております。","voiceIndex":151,"id":"exchange-063"},{"speaker":"こんの委員","kind":"質問・要望","question":"次に参ります。みどりの保全事業をお聞きしたいと思います。高齢者の方は掃くのに大変、あるいは枝打ちを自分でできないということもあって、保存樹の所有者の方は管理がなかなか難しいという、特に高齢者の方が所有していらっしゃる保存樹はなかなか難しいという現状がありますが、区はどのようにこの保存樹の管理を捉えていらっしゃいますでしょうか。","respondent":"多並公園課長","answer":"樹木の管理につきましては、大きく２つ分かれておりまして、１つが今の委員のお話のとおり、基本剪定と申しまして、一般的には３年から５年おきに、費用面または技術面で所有者の方にご負担がかかるものに対して区が直接行うことで。","voiceIndex":155,"id":"exchange-064"},{"speaker":"こんの委員","kind":"質問","question":"事業の内容はそうなんですが、いわゆる管理する所有者の方、ご高齢の方がお持ちの木の管理は、３年に一度の中で、ご自分で１年目、２年目をするのが大変厳しくなっている状況もあるということは、どのように捉えていらっしゃいますでしょうか。","respondent":"多並公園課長","answer":"維持管理する場合にも、所有者の方とお話をしながら、どのような形で管理していくかというのもアドバイスしながら進めているものです。","voiceIndex":157,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"１４１ページの公衆便所費、１４３ページの帰宅困難者用物資備蓄倉庫設置工事の件についてお伺いをいたします。どのように分かれているのか、そこの中身を教えてください。","respondent":"多並公園課長","answer":"公衆便所の件です。平成２４年度の決算の中で、公衆便所維持管理の一番大きなウエートを占めますのが、清掃委託が一番大きなところです。次いで大きいのが小破修繕でありまして、壊れた箇所を直す工事を行うものです。","voiceIndex":161,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だからその境が何なのかと思うのが、ちょっと疑問が残っています。この公衆便所の中で誰でもトイレの設置、洋式トイレの設置状況、私は改善を進めてほしいという立場での質問なんですが、設置状況と今後についての考えをお聞かせいただきたいのが一点です。これはどのようなトイレなのか、非常時というのがどういう状況なのか教えてください。","respondent":"多並公園課長","answer":"もう一つの非常時対応型のものですが、これはトイレの下に、ピットと申しまして大きな便槽があります。非常時にはその中に汚物をため込んで使えるというものが、非常時対応型のトイレです。","voiceIndex":163,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"公衆便所も、公園の便所も、ぜひ上下水道の改修を進めて、災害時に使えるようにしていただきたい、災害時の大きな備えになると思うので、その点いかがでしょうか。","respondent":"多並公園課長","answer":"文庫の森でもそのような形で整備させていただき、防災上の重要な公園を整備する際には、このような形も今後進めていきたいと考えています。もう一つ、洋式トイレの考え方ですが、確かにいろいろなご意見があります。","voiceIndex":165,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"和式トイレだと、足腰が悪くて使えない人がいるということをまず考えていただきたくて、第一には誰でもトイレを多く設置していただきたいことをお願いいたします。備蓄倉庫のことですけれども、健康センターにこの倉庫を備えるということがどういうことになるのか、一時滞在所にしていくというのか、物資の提供をするのか、荷物を預けるだけなのか、そこの位置づけと、備蓄内容を教えてください。","respondent":"亀井品川保健センター所長","answer":"実際に３・１１のときも、あそこは場所的に第一京浜と山手通りの交差点のところで、かなりの方があそこで滞留されましたので、そういう方々に提供できるものをそこで用意しようという形で準備したものです。","voiceIndex":167,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"備蓄の中身もそうなんですが、水とかトイレとか毛布とかいろいろ必要なんですが、私はぜひ休憩ができる場にしていただきたいと思うことと、あと先ほどもトイレに触れたんですけれども、健康センターは本当に幹線道路沿いにあるので、トイレの利用がすごく多いというか必要になると思うので、ぜひ災害対応用のトイレにしていただきたいのと、もう一点。","respondent":"鈴木防災課長","answer":"最初に、防災のほうに一番関係があります災害時の連絡体制のための通信機器ですが、通常のデジタル移動通信ですね、無線機を配備して、緊急時の対応ができるように準備をしています。","voiceIndex":169,"id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"エコカー関係です。これは平成１５年から、都の環境条例ですとか国のＮＯｘ・ＰＭ法の強化によって、車両の環境対策で多く取り上げられました。そこら辺で、区として今後のお考えを教えていただきたいのが一点です。それから一般廃棄物処理業許可事務です。これは決算書上で立入調査件数が３２件と出ているんですが、これはそういう調査のとき、品川区が今まで立ち入りをしてやっていたということでしょうか。","respondent":"野呂瀬環境課長、小林品川区清掃事務所長、江部健康課長","answer":"今後も、エコカー助成については一定の見直しということになりましたけれども、今申し上げたとおり、まだ規制基準を達成している状況ではありませんので。今後におきましても平成２４年１２月７日の品川区議会の附帯決議の趣旨に基づきまして、各区直接処理することが本来あるべき姿であることも踏まえ。件数が増えているという話は、今、実際に受けておりますけれども、今のところは今の助成の中でやっていただきたいというふうに考えております。","voiceIndex":172,"id":"exchange-071"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"エコカーにつきましては、まだまだ意識を持っていただく中で、いいほうに検討していっていただきたいということで、それは要望します。ですから、清掃の移管をしたときの意識が、我々議会の中も薄くなってきている。もう一回ちょっとその辺のご答弁をいただきたいと思います。それから薬剤師会の関係です。９０万円というお話も聞いております。","respondent":"野呂瀬環境課長、小林品川区清掃事務所長、江部健康課長","answer":"今回特にディーゼル車につきましては、運輸部門におけるＣＯ２の削減効果もあるということですので。したがいまして効率的な点はとりつつも、各区共同でそれを全て任せるというのではなくて、必要に応じて分担しながら、共同で立ち入りをすると。注射針回収につきましては、両薬剤師会のほうから実際にかかっている経費についてお示しいただいておりますので。","voiceIndex":176,"id":"exchange-072"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それと当時に品川でスタートした中で、２年とか１年の契約ですから、相当の入れ替えもあったと思うんです。その方々というのは、品川の中でそのまま継続してやっていただいているのかどうか、その点を教えてください。あそこに前、燃料のスタンドがあって、今もあるんでしょうけれど、そこが使われていないという話を伺っているんですが、現在の状況を教えてください。","respondent":"山崎ものづくり・経営支援課長、小林品川区清掃事務所長","answer":"転出された企業が３４企業ございまして、現在も事業を継続されている企業については２０社です。それから区内その他ですけれども、８割方が区内で創業しているものです。環境性能としてはディーゼル車のほうがむしろすぐれているのではないか、またコスト的にもＣＮＧより安くなっているという状況も踏まえて、今後その位置づけを検討してまいりたいと考えています。","voiceIndex":180,"id":"exchange-073"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"創業支援センターのほうはぜひ、うまくいっている中で今後も各事業所との関連、そして品川の中にうまく生かしていただきたいということをお願いします。それから清掃の、例えば発災で品川にトラックが来てもらったとき、荷物を運んでもらったときの帰りの車の燃料を維持できないかという話もあったんですけれど、ちょっと大きさを聞いて、今後の検討をまた、いろいろ全体で考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-074"},{"speaker":"高橋委員","kind":"質問","question":"衛生費１４３ページ、保健所等管理運営費、産業経済費のほうで１５０ページ中小企業事業資金融資あっせんについて、幾つかお尋ねします。合計しますと１,５３６件、１２７億円余の融資が実行されています。この融資に関しては、リーマン・ショック後からの推移、前年度との比較という観点で、どのような成果があり、どのような評価をされているのでしょうか。基本的なことなのですがお伺いいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"ただ区としましては、中小企業の資金ニーズに応えるためにいろいろ資金の工夫をしておりまして、増の３０億円というのは２３区の中で断トツ１位ということで、ニーズに応えてきたものというふうに評価しているものです。","voiceIndex":185,"id":"exchange-075"},{"speaker":"高橋委員","kind":"質問","question":"ニーズに応えた結果、２３区で３０億円増というのは断トツだというお話があったんですが、その突出した実績ですけれども、他の区に比べて非常に多かった要因というのはどのようなところにあるんでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"こちらは平成２４年度の段階で新設したものでございまして、ここの融資の表を見ていただきますと、融資内訳で４００件余、６２億円ということで、昨年の１２７億円の約半分をこの新設した融資が持っているということで、先ほどニーズを捉えたというのは。","voiceIndex":187,"id":"exchange-076"},{"speaker":"高橋委員","kind":"質問","question":"その１３ページの経営安定化資金のおかげで、これを利用された方、活用された方がたくさんいらっしゃったということですが、とはいっても制度の中身でどれぐらいの助成金額かというところがわからないんですが。６２億円のうち、４００件ぐらいですから１件当たり１,５００万円、そうするとこの１,５００万円の中で、区の助成の部分というのはどれぐらいになるのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"経営安定化資金につきましては平均１,５００万円の融資です。モデルケースで少しわかりやすくご説明しますと、この経営安定化資金につきましては、限度額を３,０００万円にしたことと、返済期間を１０年という長期にしました。運営系で１０年とったのは初めてです。","voiceIndex":189,"id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"衛生費のほうですけれども、１４３ページの保健所等管理運営費ですが、職員給与費１２３人という人数なんですが、こちらは総合庁舎の中の生活衛生課、保健予防課の職員の方が含まれているのでしょうか。そうすると１３８ページのほうの職員給与費１９人という保健衛生総務費のほうは、どちらの職員のことになるんでしょうか。","respondent":"高山生活衛生課長","answer":"一方で１３８ページの１９名につきましては、健康課の職員の給与費を計上しているものです。","voiceIndex":191,"id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"職員の構成についてお話しいただいたんですが、ちょっと保健所のことで。ところがお仕事の関係で、５時半ちょっと前ぐらいになってしまったと。そして税金のこともちょっとお尋ねしたかったので、税務課のほうに回していただいた。庁内では保健所のみ、このアンサーフォンになっているのではないかと思うんですが、それについての合理的といいますか、その理由はどのようなことになっているんでしょうか。","respondent":"高山生活衛生課長","answer":"その効果としましては、時間外においても食中毒の発生などの際には即時に対応させていただいているところです。","voiceIndex":193,"id":"exchange-079"},{"speaker":"高橋委員","kind":"質問・要望","question":"食中毒でなくて、飲食店の方がお尋ねしたときにつながらないということですので、機械的に変わってしまうことと、区長も品川区役所のイメージアップをとにかく広げていこうというお話もされていました。ぜひ今の点を検討し、改善していっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-080"},{"speaker":"山元委員","kind":"質問・要望","question":"厚生労働省は来年度から対象年齢を絞り込んだ事業に縮小すると聞いておりますけれども、その対象が子宮頸がんに関しては２０歳、乳がんは４０歳のみ限定と伺いましたけれども、品川区はこれを受けてどのように把握していらっしゃるのか、その状況を教えていただきたいと思います。","respondent":"江部健康課長","answer":"これについては２３区保健衛生課長会でもちょっと議論になっております。現在のところはまだ未確定ですので、予算要求上は前年並みにしているところでございまして、今後の検討にさせていただきたいと思います。","voiceIndex":197,"id":"exchange-081"},{"speaker":"山元委員","kind":"質問・要望","question":"先ほど聞くのを忘れてしまったんですけれども、２００９年前といいますか、この無料クーポン券がスタートする前と、昨年度でもいいんですけれども受診率といいますか、使用前、使用後ではないんですけれども、その率がわかれば教えていただきたいと思いますが、いかがですか。","respondent":"江部健康課長","answer":"２年に１回の個別通知と、５年に１回のクーポンということで、ちょっとふくそうする関係がありますので、正確な数字は把握しておりませんが、健康課のほうで試算しますと、クーポンをお送りすると、ほかの方よりも１６％ぐらい高くなるという試算はしておりますので。","voiceIndex":199,"id":"exchange-082"},{"speaker":"山元委員","kind":"意見","question":"厚生労働省の人口動態調査によりますと、乳がんで亡くなる日本の女性の割合が、平成１２年に初めて減少したと。４５歳から４９歳までに至っては、５割近くまで上昇したと聞いています。受診率の向上や早期発見につながったかなと思いますけれども、５０％を目指して品川区もいろいろと努力していらっしゃると思いますが、これを受けて品川区としてはどのような感想をお持ちでいらっしゃいますか。","respondent":"江部健康課長","answer":"それで冷静に考えてみて、今の段階だとどういう影響が出るのか、どのぐらいの人に影響が出るのかという分析を、今しているところでございまして、即答はできませんけれども何らかの対応を、国が縮小するといいましても、品川区としてはそのとおりいくかどうかについては。","voiceIndex":201,"id":"exchange-083"},{"speaker":"山元委員","kind":"質問・要望","question":"健康課長の一言、一言がとても希望に満ちて聞こえているんですけれども、子宮頸がんの対象は２０歳、乳がんは４０歳と限定しているわけですけれども、今までの２０歳から４０歳という長いスパンが、今度は２０歳だけ、４０歳だけとなると、やはり受診率が低下するのではないかと心配しているんですけれども、この事業に対して品川区はどのように感じていらっしゃるのか。","respondent":"江部健康課長","answer":"その成果で受診率の向上、がん発見者数の増加、死亡率が下がりつつあるという中にいるという認識をしておりますので、今回の国の判断については慎重に対応していきたいと考えています。","voiceIndex":203,"id":"exchange-084"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても健康課長の一言、一言の中には、品川区独自でも継続していこうと思っていらっしゃるように受け取りました。ぜひ継続を考えていただきたいと思いますが、その辺はいかがでしょうか。","respondent":"江部健康課長","answer":"これから予算の編成ということですので、財源を確保できたらという条件でもって、考えします。","voiceIndex":205,"id":"exchange-085"},{"speaker":"山元委員","kind":"質問・要望","question":"受診率アップにつながることについて、もう一つ確認させていただきたいと思います。４定のとき、私は受診率アップのために個別に電話連絡等したらいかがですかというお話をさせていただきましたが、それ以後、区としてはそのような、受診していない方に対して電話等々していらっしゃるのかどうか、その辺確認をさせていただきたいと思います。","respondent":"江部健康課長","answer":"ただ国保の基本健診のほうは、区が保険者という立場で被保険者に対応するという立場ですが、私ども健康課が行いますがん検診につきましては、年齢対象の方、区民全てです。","voiceIndex":207,"id":"exchange-086"},{"speaker":"山元委員","kind":"質問・要望","question":"どうかよろしくお願いいたします。次に、ちょっと時間がありますので１３８ページの公衆浴場についてお伺いしたいと思います。一番聞きたいことは、予算が３,１００万円のところを決算では１,８００万円ということなんですが、この差がどういうことだったのか、その辺をちょっと教えていただきたいと思います。","respondent":"江部健康課長","answer":"この中で一番大きいのは、建替工事をした場合の１,０００万円という補助金がありますが、これはいつも予算計上をしているものですが、ここ１０年建替えをされる浴場がないため残るものであり、執行しておりますのは風呂釜を替えるですとか。","voiceIndex":209,"id":"exchange-087"},{"speaker":"山元委員","kind":"質問・要望","question":"一言だけ。南品川、東品川地域では１軒も銭湯がないということで、それに対して区としてどんな対応を考えていらっしゃるのか、一言教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-088"},{"speaker":"藤原委員","kind":"質問","question":"これは歳入のほうが見当たらなかったんですが、調査はどこが主体でやっているのか、どういう目的か、そして調査結果を品川区がどう生かしていくのか教えてください。それと１５１ページの武蔵小山創業支援センターのところで、武蔵小山のウーマンズビジネスグランプリなんですけれども、受賞者の皆さんは区内で創業を、改めて聞きますが、しているんでしょうか。教えてください。","respondent":"高山生活衛生課長、亀井品川保健センター所長、山崎ものづくり・経営支援課長","answer":"調査開始年度であります平成１４年度に、２０歳から３４歳だった男女を対象としまして、結婚、出産および就業等の状況について。１歳６カ月児の健康診査は直営でやっておりますが平成２４年度で９３.８％、その次の３歳児健康診査も直営でやっておりますが、９２.０％の受診率です。区内では、エイジレス世代のファッションビジネスということでビジネスモデルをつくられて、品川のまちなか起業ステーションということで。","voiceIndex":213,"id":"exchange-089"},{"speaker":"藤原委員","kind":"質問","question":"２１世紀成年者縦断調査ですけれども、さっきの質問でその調査結果を品川区でどう生かしていくんですかと伺っているんですが、その答弁がなかったのでお願いします。乳児健診ですけれども、もちろん１００％に近いほうがいいんですけれども、この受診をしなかった人のフォローはどういうふうにするんでしょうか。子育て支援とかも含めて、その辺のことも教えてください。","respondent":"高山生活衛生課長、亀井品川保健センター所長、伊崎子育て支援課長、山崎ものづくり・経営支援課長","answer":"最終的にはこういった集めましたデータを厚生労働行政施策の企画立案、実施等のために役立てるための基礎資料として活用されるものですので。やはり今後、要支援家庭としてさらにフォローアップが必要な場合には。健診未受診者につきましても、今、品川保健センター所長から答弁がありましたように要支援家庭につきましては。そうした意味では１つの起業支援がひいては地域の活性化につながっていくような、こういった大切な観点をきっちり、基本ですので持ち合わせまして。","voiceIndex":217,"id":"exchange-090"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に１点だけ。１５２ページのプレミアム付商品券なんですけれども、これはやはり、商業・観光課長の答弁は大体わかっているんですけれど、どうしても伺いたいのであれします。毎回３億円。そうでなくて、やはりこれだけ区民の方が喜び、商店街が喜んでいる施策、私は毎回言っているんですけれども、この金額を上げていただきたいという要望で、改めて質問しますが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"金額につきましても、これは当初から２回継続して組んだり、あるいは補正で追加計上したりというようなことは経済状況を勘案しながら決めているものです。来年の４月には大きな商業環境の変化もありますので、こうした部分も含めてまた検討してまいりたいと考えています。","voiceIndex":222,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"それからＡＥＤですけれども、まずこの管理費の中身を伺いたいと思います。例えば４０歳過ぎてから一般治療から入るということは、かえって時間の無駄になるのかなという気もしないではない、そういったところで、ある程度はカウンセリングなどがあるのかどうか、それとも請求に応じてお金を出すだけなのかということをお伺いしたいと考えています。","respondent":"江部健康課長、柏原行財政改革担当課長","answer":"確かに季節によって増えることはありますが、ベースとしてはそれほどのことは認識しておりませんので、現在の委託料の中で行いつつ部分的に、先ほど申しました２月とかの繁忙期に、個別のプラス何日という形での対応を今。私も直接交渉したこともありますけれども、なかなか東京都が、このことに関しましては趣旨を曲げないといいますか、一つの答えしか返ってこないということで、そうはいいながらも区にある貴重な土地ですので。","voiceIndex":225,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"機械は機械で、共用型であれば機械の普及をしていただいても構わないんですけれども、むしろ子どもたちの命を救うには、ＡＥＤとあわせてというより、それ以上の熱意を持って心肺蘇生術の普及ということをぜひ関係のところから始めていただいて、広く区民に広めていただきたいと思いますが、区の見解をお伺いしたいと思います。それから不妊治療について。それぞれいかがでしょうか。","respondent":"江部健康課長、米田商業・観光課長、柏原行財政改革担当課長","answer":"ＡＥＤ絡みで子どもの心肺蘇生の件と、不妊治療をされている方への対応という２点についてお答えいたします。お話のありました天王洲の活性化というような全体的なことにつきまして、あるいはまた清掃の用地につきましても、関係部署と連携をとりながら。天王洲のまちづくりといったところも含めて、今、商業・観光課長からの答弁もございましたけれども。","voiceIndex":228,"id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"ただ、クリニックに行くだけでもそれは非常に緊張した、特殊な時間なんですね。そうではなくてもう少し一般論として、どういう心持ちを持っていけばいいのか、どういう体づくりをしていけばいいのかというような、そういったことを一般的な講座あるいは啓発のような形でやっていくというのも、一つのやり方ではないかと思いますので、今後考えていただければと思います。","respondent":"江部健康課長","answer":"研究します。","voiceIndex":232,"id":"exchange-094"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は成果報告書の１４０ページ、成人歯科健診について伺いたいと思います。今回この成果報告書では、２,５２０人ということでしたけれども、この対象人数と受診率、この受診率の達成目標というんでしょうか、それがあれば。","respondent":"江部健康課長","answer":"一方、７０代半ばぐらいから上の方については歯磨き習慣がなかったということがやはり、歯科医師会の先生方とか研究の中でも言われておりまして、その年代については歯周ポケットを持つ方の数が増えているということは、認識しております。","voiceIndex":235,"id":"exchange-095"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この受診率に目標があればということを伺ったんですが、あればお答えいただきたいのと、あと６.９９％、徐々に上がっていると言っていますけれども、少ないなと本当に感じるんですが、そこへの課題があれば教えてください。","respondent":"江部健康課長","answer":"我々は特に、２０％とか３０％を目標にしておりませんで、前年の実績を踏まえてプラスに、少し加算するというような形で毎年予算要求をしてきているところです。","voiceIndex":237,"id":"exchange-096"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では特に課題と感じていることがあれば、教えていただきたいです。それで、この間、私は歯の健康は全身の健康に大きく影響するということや、介護予防にもつながるということをお伝えしてきたんですけれども、区も、歯の健康は全身の健康に大事だという認識はお持ちなんでしょうか。","respondent":"江部健康課長","answer":"もちろん歯で食べて、人間は生きるものですので、歯周疾患から糖尿病につながるとか、そういう報告もなされておりますので、そこは認識しております。それから健診を受けられる方と、受けられない方というのは、やはり意識の問題が大きいと思います。","voiceIndex":239,"id":"exchange-097"},{"speaker":"石田（ち）委員","kind":"質問","question":"虫歯と違ってもとに修復できないというのが歯周病です。ですので他区の状況を見ましても、４０歳からの健診は品川区を含めて９区だけです。そのほかの１４区が２０代、３０代から始めていまして、毎年実施しているところが５区あります。ですので、４０歳からでは遅いとずっと言ってきているんですけれども、この予防という観点からの年齢拡大の考えはあるでしょうか。","respondent":"江部健康課長","answer":"予防の考え方は、あくまでも３０代、４０代の方、ですから基本的にはその方各自が、自分の体ですから自分でやるというのを基本にやっていただきたいと思います。","voiceIndex":241,"id":"exchange-098"},{"speaker":"石田（ち）委員","kind":"質問","question":"歯科口腔保健の推進に関する法律が、２０１１年からつくられていまして２年たっているわけですけれども、これがどういう目的でつくられて、内容はどういうものなのか、教えてください。","respondent":"江部健康課長","answer":"歯科口腔保健の推進に関する法律につきましては、平成２３年８月１０日施行されたということでございまして、地方公共団体は地域の状況に応じた施策を策定し、充実を図る責任があるということで、規定されております。それにのっとりまして私どもは事業を展開しております。","voiceIndex":243,"id":"exchange-099"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、認識が低いとか、自分の体だから自分で守れとか、そういうことを言われなくても守っているので、それをさらに、知らない人にどう伝えていくのか、知らなければできないので、先ほど健康課長もおっしゃっていましたけれど、それをやはり広げていくためにも、自治体が啓発の事業とか、そしてまた１５歳から健診を広げていこうという、通知が来たことで。","respondent":"江部健康課長","answer":"ただ、生活習慣が乱れて、口の中とか自分の健康を守れないという方もいるはずですので、その方については啓発事業の中で意識づけを図る方策を検討していくべきではないかと考えております。","voiceIndex":245,"id":"exchange-100"},{"speaker":"石田（ち）委員","kind":"質問","question":"この厚生労働省の歯科口腔保健の推進に関する法律の基本方針にも、第一に健康格差が掲げられているんですね。これを縮小していこうというのを掲げているんです。口腔崩壊している実態も、この間の一般質問で出しましたけれども、こういった口腔の健康格差を、区はどうお考えでしょうか。","respondent":"江部健康課長","answer":"先ほどの繰り返しになりますけれども、各種統計調査から健康格差が明らかであるということは、報告されておりません。","voiceIndex":247,"id":"exchange-101"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"厚生労働省からこういった特別区の各衛生主管部、部局長宛てに歯科口腔保健のさらなる推進を図るため、本資料もご活用いただきたいというふうに来ていると思うんですが、この検討はしっかり区としてやられているんでしょうか。","respondent":"江部健康課長","answer":"それにつきましては、検討した上、歯科医師会とも相談しながらやっております。","voiceIndex":249,"id":"exchange-102"},{"speaker":"石田（ち）委員","kind":"質問","question":"この厚生労働省の法律には、方針をつくり、計画を立て、啓発をしていくということがうたわれているんですけれども、それが検討されているということでいいんでしょうか。","respondent":"江部健康課長","answer":"歯の健康に関することにつきましては、現行の長期基本計画、総合実施計画の中でもうたわれ、健康づくりプランの中でも事業として展開しています。そこのところは、今回のその法律の趣旨を踏まえて、今後事業を充実させるという意味での検討はしていきたいと思います。","voiceIndex":251,"id":"exchange-103"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"健康格差は確実に起きているんですよね。私も先ほども言いましたけれども、多くの若者たちが歯の健康を守らない、時間もなくてお金もないという状況があるものですので、３５歳からの健康診断も、医療に受診できる機会を失った若者への対策として、今回平成２５年に実施されていると思うんです。それと同じことだと思うんですね。いかがでしょうか。","respondent":"江部健康課長","answer":"委員のおっしゃる健康格差という点、若者が極端に歯の健康状態がよくないということにつきましては、繰り返しになりますけれども統計として上がっておりませんので、我々としては今拡大を考えるという動きではありません。","voiceIndex":253,"id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"２つ目に、１４６ページの拠点回収について伺いたいと思います。融資を受けられなかった企業のフォローというんですか、その後というところの取り組みがあればお聞かせいただきたいのと、融資を受けた企業の状況について、金融機関、専門家とのその後の経営改善等、連携はどのようにされているのか、支援の継続につながっているのか、ここらへんのご様子をお聞きしておきたいと思います。","respondent":"江部健康課長、小林品川区清掃事務所長、山崎ものづくり・経営支援課長","answer":"区といたしましては、こういう事業形態を今のところ継続する考えです。その所要の経費ですが、キロ当たり５５円ですので、総トータルで１１０万円ほどかかっております。一番多く対応していますのが、創業系の融資ということで、起業して間もない部分について。そのご案内の仕方はもう少し適切に、表現等工夫してまいりたいと思います。","voiceIndex":256,"id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"１６２万円がずっと継続して助成されている、一方では、園数が多くなって、やったりやらなかったりの園が出てきているという実態がございまして、いわゆる適正な、また安定した事業となるような委託金、助成金のあり方、これはしっかりと来年度に向けて検討していただきたいと。これは要望します。それだけ確認させてください。濡れた土は重いので、ぜひ各拠点で徹底のほど、よろしくお願いします。","respondent":"江部健康課長","answer":"増えたり減ったり、施設数は増えておりますが、歯科医師会のほうで行っていただいている件数は７０だったり、６０だったり、平成２４年度は下がっておりますので、一概に多くなっているという認識は持っておりませんので、今後、会との話し合いはしていきます。","voiceIndex":261,"id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"区の事業の目的は、全ての私立、公立の保育園、幼稚園の皆さんに適切な指導を受けさせたいという委託事業ですので、それに沿った適正な委託金をという要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-107"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きしたいと思います。１点目が４款衛生費、３項清掃費、１目清掃総務費、成果報告書の１４８ページの船舶中継所跡維持管理費です。〔「知らなかったの」と呼ぶ者あり〕知らなかったですね。そして何か品川区が深く関与しているような気がしたんですけれども、実際にこの花火は港区で打ち上げられたようですけれども、品川区はどんなかかわり方をしていたかについてお伺いしたいと思います。","respondent":"小林品川区清掃事務所長、米田商業・観光課長","answer":"その後平成２１年４月から、粗大ごみの積み替え作業所として使用を開始しておりまして、現在もその機能を継承しております。この１０月からは小型家電の回収、分類作業所としても活用しています。具体的に区がどれぐらいかというお尋ねですけれども、今回、ご指摘ありましたように港区のところから上げるのが、花火が一番、保安区域とかも含めて上げやすいのではないかというようなこともありました関係で。","voiceIndex":265,"id":"exchange-108"},{"speaker":"松澤委員","kind":"質問・要望","question":"船舶中継所跡地ですけれども、平成１２年ですから平成３２年まで、あと７年は清掃事業だけということですよね。７年後は何があると思いますか。オリンピックなんですよ。何とかこれをオリンピックのときに、品川区であれだけの広さのものを活用したいと思ったとき、１年でも２年でも前倒しで品川区にいただけないか。その件について、しっかりと答弁をいただきたいと思います。","respondent":"柏原行財政改革担当課長","answer":"そういった中で、使用の用途の指定ということで、２０年間は清掃業務という強い縛りがございまして、やりとりをする中では、清掃業務以外では買い取りをしてほしいであるとか、いろいろな話が出てあります。","voiceIndex":268,"id":"exchange-109"},{"speaker":"松澤委員","kind":"質問","question":"まさにオリンピックがその年に開かれるわけですから、そこを有効活用したいと思ったら、やはり１年でも２年でも前倒しということが必要だと思いますので、さらに努力をお願いします。花火の件については、いろいろ課題もありますよということで、これだけはお伝えしておきたいと思います。次に行きます。当然、産業振興のことに使うんだろうと思いますけれども、ちょっとご意見を伺いたいと思います。","respondent":"米田商業・観光課長","answer":"中小企業センターの４階ですけれども、いわゆる産業関連団体ということで東京商工会議所品川支部ですとか、商店街連合会、各工場協会連合会ということでご入居いただいてあります。","voiceIndex":270,"id":"exchange-110"},{"speaker":"松澤委員","kind":"質問","question":"４階に観光協会がありましたよね、あれがあきました。その後が産業振興、そういうものに使われているかというと、商業・観光課で使っているように聞いているんですが、ちょっとその辺をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"４階の観光協会のあいたところは、就業支援センターの方の一部詰め所であったり、あるいは中小企業との経営相談の中では、一部部屋が手狭だということもありまして、そういった相談業務に転用しているものです。","voiceIndex":272,"id":"exchange-111"},{"speaker":"松澤委員","kind":"質問・要望","question":"基本的な考え方としては、手狭になったから、あいたから広げるという考え方は、私はいけないと思っているんですね。もともと中小企業センターですから、産業振興に役立つものを入れる努力、あいているから使ったんだと言うかもしれませんけれど、その辺、今度ももしあくとしたらしっかりと後を考えていただきたいと、注文しておきたいと思います。改めてその考えを聞きたいと思います。","respondent":"米田商業・観光課長","answer":"中小企業センターのある種業務量が増えているということでは、それなりに部屋のほうの確保も必要にはなってありますが、委員ご指摘の趣旨も踏まえまして、工場協会のほうから特に何もお申し出いただいていませんが、その折にはまた考えてまいりたいと考えています。","voiceIndex":274,"id":"exchange-112"},{"speaker":"松澤委員","kind":"質問","question":"了解しました。同じく成果報告書の１５０ページ、被災地観光促進経費は、平成２３年度から始まった事業で３,０６５件だったのが、平成２４年度は５,４３２件と大きくふくれ上がりました。今年度予算も大きく伸びているんですけれども、この内訳ですね、関東地方、東北地方、それぞれ指定されていたと思うんですが、この関東と東北の内訳をお聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"次いで多うございましたのが栃木県で９８３名、次いで多かったのが茨城県で７８０名です。平成２５年度からは、対象地域を東北地方に限定した実施を行っているものです。","voiceIndex":276,"id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"この被災地観光促進、平成２５年度は東北だけに絞ったということですけれど、これをいつまで続けていくのか、いいことですから続けようという思いはあると思うんですけれど、やはり事業ですからどこかで仕切り直しというんですか、ほかの方向を考えるとかいうことも考えられると思うんですが、この事業はどういうような形で進めていくのかについて、お聞きしたいと思います。","respondent":"米田商業・観光課長","answer":"この辺につきましては、こちらの支援策が有効に働きますよう、また来年度に向けては検討を進めてまいりたいと考えています。","voiceIndex":278,"id":"exchange-114"},{"speaker":"原委員","kind":"質問","question":"実は私ごとなんですけれども、昔、筑波大学とか早稲田の関連の附属機関でカウンセリングの資格を取らせていただいて、一時期そういった関係のところのお手伝いをさせていただいたことがあるものですから、訓練的な内容をより、学会でいってしまうとカウンセラー協会とか、日本自律訓練学会ですね、その辺のところで、具体的なものがあればもう少しお話を頂戴したかったと。","respondent":"大石荏原保健センター所長、山崎ものづくり・経営支援課長","answer":"平成２３年には健康大学で立正大学の先生をお呼びして、心の健康の話をしていただいたという実績もあります。いろいろなお悩みを抱えていらっしゃる経営者に資するために、相談も充実させるとともに、現在区のほうでは融資の実施件数が延べ９,０００件あります。","voiceIndex":285,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問","question":"私からは、１４７ページの清掃費全般からお伺いしたいと思います。ふれあい清掃事業についてなんですけれども、２００９年から始まっていますけれども登録人数の推移と、実際に異変に気づかれたケースなどあったら、その推移を教えてください。","respondent":"小林品川区清掃事務所長","answer":"ふれあい清掃事業は、日常ごみ出しができない高齢者等を対象に実施しております。","voiceIndex":289,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"このふれあい清掃事業で、以前に高齢者のひとり暮らしの見守りとか、そういったところの連携でということで、２００９年には何らかのそういったものがあった場合には、携帯電話で直接連絡がとれるようにということで、補正予算でもそういった対応がされているので、そのことについて何か、見守りで異変をキャッチしたケースがありますかということで、今、質問させていただいたんですが。","respondent":"小林品川区清掃事務所長","answer":"ごみが所定の場所に出ていないとき等は声がけをして、それで安否確認も含めて行っております。今、手元の平成２４年度、平成２５年度の数字では、お声がけをした件数はありますけれど、あらかじめお申し出いただいた連絡先に通報したという実績はございません。","voiceIndex":291,"id":"exchange-117"},{"speaker":"井上委員","kind":"質問","question":"そういったケースがなかったことは、とてもよかったことだと思うんですけれども、その中で高齢者の見守りとか、今、営業の方にお願いするという企業との連携とか、いろいろなところでそういうふうな連携をとっている中で、ぜひこの部分についても心配されている方たちがそういう登録制度というものにつながればいいなと思っているんですが、そういったことで高齢者福祉課のひとり暮らし担当とか。","respondent":"小林品川区清掃事務所長","answer":"この事業がより身近なものとしてその効果が図れますように、今、お寄せいただきましたご意見も含めて、高齢者福祉課あるいは障害者福祉課といった関係各課と連携を深めて、ＰＲに努め、対応してまいりたいと思います。","voiceIndex":293,"id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"東京二十三区清掃一部事務組合の分担金についてなんですけれども、サーマルリサイクルの分別が２００８年から始まりまして、血圧計や体温計などの水銀由来の事故が起きて、清掃工場がストップするということが何件かありましたけれども、今まで、過去トータルで何件、清掃工場がストップした事故があったのか、そしてその影響でいろいろな補修で何億円単位という経費がかかっているかと思いますけれども。","respondent":"小林品川区清掃事務所長","answer":"その結果、分担金への影響はというご質問ですけれども、基本的に清掃関係施設、２１施設を含めて一体的に清掃一部事務組合は対応しておりますが、各２３区はその所要経費を分担金で負担しておりますので、その施設の修繕対応の費用は、分担金のほかは。","voiceIndex":295,"id":"exchange-119"},{"speaker":"井上委員","kind":"質問","question":"本当に二十三区清掃一部事務組合が２４区目の地方自治体みたいな感じになって、そういうサーマルリサイクルへの影響が大きくあるということを考えると何らかの形で、分担金で把握していないということではなく、区としてどういうふうに影響があるのかということは、２３区全体で経費を示すとか、ここの部分では自治体という位置づけになっていますけれども、そこを区としても把握して。","respondent":"小林品川区清掃事務所長","answer":"したがいまして日常の契約、費用負担の詳細まで全て報告させて周知するということは、技術的に困難な点が多かろうと思っています。","voiceIndex":297,"id":"exchange-120"},{"speaker":"井上委員","kind":"意見","question":"議長会等での報告の中で、清掃工場が水銀由来でストップしたときに、どれだけの改修費がかかるかというとき、幾らぐらいかかりますよという大体の目安が報告されているという状況で、全体でどのぐらい増えているかを区民が知らないというのはやはり間違いだと思いますので、その仕組みをつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":299,"id":"exchange-121"},{"speaker":"浅野委員","kind":"質問","question":"１４４ページの環境対策費から、温暖化対策事業に関連して質問します。こちらの経過は東京都のほうからデータが出てくるというふうに私も認識しておりまして、ことしの春ぐらいにやっと２０１０年度の結果が公表されているわけですけれども、品川区のこの２０１０年度の二酸化炭素の排出量の目標と、実際にこれに向けて実施をした施策、そして結果について、こちらの数値を教えていただければと思います。","respondent":"野呂瀬環境課長","answer":"でも３・１１がありまして、その後いろいろ状況が変わってまいりまして、最終的に結果ですけれども、委員ご指摘のとおり、２０１０年の第１回目の数字が出たところです。","voiceIndex":301,"id":"exchange-122"},{"speaker":"浅野委員","kind":"質問","question":"この地域推進計画の上位概念、これは第２次環境計画の中間の５年後に見直しをするということも聞いておりますが、こちらの推進計画も１１年間の計画という、この計画についてもやはり中間で見直しをしていかなければならなくなるのではないか、それが今後出てくる国の数値とか、地球全体の数値などを考えながらやらなければならないと思いますけれども、この件についてはどう考えていますでしょうか。","respondent":"野呂瀬環境課長","answer":"この中間見直しが５年後ですので２０１７年に予定しております。これにあわせて、先ほど申しました地域推進計画、いわゆる品川区全体の温室効果ガスの削減計画ですけれども、これについては見直しを図っていきたいと、このように考えているところです。","voiceIndex":303,"id":"exchange-123"},{"speaker":"浅野委員","kind":"質問","question":"次に観光アクションプラン推進事業ですけれども、しながわ観光フォトコンテストを実施して、多分これは間違いなく品川のよさを発掘していこうという取り組みだと思うわけですけれども、区民の皆さんに区内の観光スポットをピックアップしてもらうということで、これは本当にいい機会になるのかなと思いますが、この効果というものをどのように考えておられるのか教えてください。","respondent":"米田商業・観光課長","answer":"こうしたことによって、いわゆる区内の名所、自分の近くに眠っているこんなものがあるよというようなことを発信することによって、それを区民の方のみならず、区外からいらっしゃる方もホームページをごらんになることによって、広く区への誘導に。","voiceIndex":305,"id":"exchange-124"},{"speaker":"浅野委員","kind":"提案","question":"至るところでこちらについてはさまざまな提案をしていますけれども、以前、福岡市のシティＷｉ－Ｆｉの視察をしてきたという話もしたかと思いますが、こういうような取り組みというのは間違いなく必要になってくると思います。そしてそれを一つのパイロット的な取り組みとして、いいところ、悪いところも含めて検討して、さらに発展をさせていくという考え方もあるかと思いますが、いかがでしょうか。","respondent":"米田商業・観光課長","answer":"それから戸越銀座に関しては、今年度ある程度街路灯の設置工事がほとんど終わりますので、今年度そういった利活用について、鋭意検討を進めているというふうに伺ってあります。","voiceIndex":307,"id":"exchange-125"},{"speaker":"須藤委員","kind":"質問","question":"１４５ページの土壌汚染相談について、１,３４５件という数字がありますけれども、簡単にどんな相談があるのか教えてください。","respondent":"野呂瀬環境課長","answer":"いわゆるディベロッパーとか不動産関係の方が窓口に来て、過去にそういう土壌汚染があったかどうかというのをお尋ねになる、この相談です。","voiceIndex":310,"id":"exchange-126"},{"speaker":"須藤委員","kind":"質問","question":"土壌汚染、私もあまり身近に感じていなかったので、今まで学校をつくるときに鉛とか云々ということで話を聞いていたんですが。そうすると音もその改良の時に出てくるだろうとか、いろいろな問題があると思うんですけれど、そういう点について、土壌汚染処理については、何か条例的に、近隣に周知するとか、説明するとかという形をつくったらどうかと思うんですが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"その土壌汚染を改良するときには、ちゃんと間違いなくきれいにするという土壌汚染改良報告書とか、そういう手続関係は全部条例に載っているところなんですけれども、今現在、それ以外のことで近隣に説明しなければならないとか。","voiceIndex":312,"id":"exchange-127"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから前向きに、解体するとかというのは条例があって、近隣の皆さんに周知するというから、承知しますよ。土壌に対しても。ですからそういったことをきちんと、皆さん方に周知させる、現状ではこういう土壌汚染でどの程度深くまで、何が入っているとかということは必要ないかもしれない。そろそろそういうことを、やはり研究していただきたいと思うんですか、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"区としましては住民のいわゆる福祉向上、これが第一の目標ですので、委員のご意見を踏まえた上で、今後検討してまいりたいと考えています。","voiceIndex":314,"id":"exchange-128"},{"speaker":"須藤委員","kind":"質問・要望","question":"今お話がありました、昭和に建てたものが建替えの時期に来ていると。そのことについては解体するのは別に、あるいは汚染どうのというのは何もないんですけれど、これも国のほう、あるいは東京都のほうでもまだ何も規制をしていません。これも既につくっている区もあるわけですけれども、そのあたりも研究してみていただきたいと思うんですが、いかがでしょうか。","respondent":"野呂瀬環境課長","answer":"ただ、委員がおっしゃった成形板、次の段階になるかと思うんですけれど、これも含めて、今後区民の健康とか、いつ災害が起こるかわからないということもありますので、いろいろ対策が難しくて、具体的な対策というのが非常に困難なところもあるやに聞いておりますけれども。","voiceIndex":316,"id":"exchange-129"},{"speaker":"須藤委員","kind":"質問・要望","question":"１５２ページの品川技術ブランドＰＲ事業、メードイン品川ＰＲ事業、これは区長が先頭になってＰＲしますというような話が当初あったと思うんですけれども、どんな品物ができていて、どんな成果が上がってきたのか、短い時間で申しわけないですが、お聞かせください。","respondent":"山崎ものづくり・経営支援課長","answer":"昨年度から開始しまして、昨年度につきましては、４つの製品について指定をさせていただいています。同様にことしも、製品の選定を終えておりまして、昨年３月のクラスターフェアで、区長にトップのプレゼンをやっていただきました。ことしもそうしたことを計画しております。","voiceIndex":318,"id":"exchange-130"},{"speaker":"南委員","kind":"質問・要望","question":"そこで、ことしの１１月にはポーランドでＣＯＰ１９がひらかれる予定で、２０２０年以降の新たな枠組みが議論されるわけですけれども、日本はロシアとかニュージーランドとともに２０１３年からの削減計画を持たないというふうにしていますので、私はこの会議に向けて、地域の隅々から２０２０年の目標を２５％に戻すよう国に求めていく。","respondent":"野呂瀬環境課長","answer":"ですからそういう条件の中で、今まで可能な限り太陽光の発電設備はやってきました。ですから今後もその考えは継続して、できるだけ可能な限り、設置できるところを見つけて、太陽光発電システムは設置していくという考えです。","voiceIndex":321,"id":"exchange-131"},{"speaker":"南委員","kind":"質問・要望","question":"今の質問の答弁は後ほどお願いします。次の質問はＰＭ２.５に関することです。品川区内でも４カ所ですか、自排局、一般測定局がある中でＰＭ２.５の測定がされているわけですけれども、東京都の平均値から見て、品川区のこの４カ所の状況はどうかということをまず教えていただきたいと思います。今週１週間の数値を見ただけでも。そういう点で、この問題についての質問をしたいと思います。","respondent":"野呂瀬環境課長","answer":"それと区は一事業所としてＣＯ２削減の実行計画というものを持ってありますので、それに基づいてしっかりと守っていくように取り組んでいきたいと考えています。","voiceIndex":323,"id":"exchange-132"},{"speaker":"南委員","kind":"質問・要望","question":"東京都の平均値を上回っているかどうかについてご答弁がなかったので、そこは大事な部分なのでお願いしたいと思います。それから放射能の関係なんですけれども、せんだって私も八潮団地の中で放射能の測定をしたんですね。したがって品川区は早急にまた、大気中の汚染状況がどうなっているかの調査を開始するべきだと思っていますので、その点についての見解を伺います。","respondent":"野呂瀬環境課長","answer":"しかしそのために、ほかの区内全部の砂場をはかるとか、そういうことになってくると、ちょっとこれは意味合いが違ってまいりまして、今までどおりこの姿勢のまま継続して、行ってまいりたいと考えているところです。","voiceIndex":325,"id":"exchange-133"},{"speaker":"南委員","kind":"質問・要望","question":"私が測定のことを伺ったのは、東京都の大気汚染のＰＭ２.５です。東京都の平均値との関係でどうかというふうに聞いたんです。基準値で下回っているから、そんなことは聞くはずがないですよ。正確に答弁をしていただきたいと思います。都の平均は１５.７に対して、品川区の豊町の測定局では１６.３、こういう数字です。上回っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":327,"id":"exchange-134"},{"speaker":"須貝委員","kind":"質問","question":"私は１４９ページ、産業経済費の全般についてお聞きしたいと思います。区内経済の状況は、かなり格差が出ていると同時に、一般的に大半の区内産業は、そんな中で中小企業は、今日大変厳しい経営状況にあると思います。まちを歩いていると感じるんですが、商業・観光課とものづくり・経営支援課、それぞれ支援するんですが、区内産業の経営状況の実態をどのように捉えていますか。お聞かせください。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"ただ今後オリンピックに向けた景気の浮揚の期待感とか、そういったものもまたお声を吸い上げながら、区内の商業の状況について把握してまいりたい、このように考えてあります。そうしたことで、いろいろな理由がありますので、そうした特性も踏まえて、適正に事務を執行してまいりたいと考えております。","voiceIndex":329,"id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"でも、実際どうですか。これはもともと一般会計予算の１.８％で、２６億円ということですが、決算で２０億円しか使っていない。そして不用額が６億５,０００万円となっています。そんな中で区の予算額は低い上に、区内経済が落ち込んでいるのをわかっているのに、実際に予算の７５％しか執行できていないということは、私は問題があると思うんですが、その辺についてどのようにお考えでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"区のほうでは、平成２１年度以来リーマン・ショックに対応して、いち早く経済対策を実施してまいりました。","voiceIndex":332,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"は知りません。そうではないでしょう。その辺はやはり真剣に私は考えてほしいと。その中でちょっとお聞きしたいんですが、日銀などは「生活意識に関するアンケート調査」の９月ですね、それから全国企業短期経済観測調査。こういうのはきちんと把握しているんですか。先ほど経済がよくなっているという話も、景気がよくなっている話も今、出ましたけれど、その辺はどうなんですか。教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"こういった対応をさせていただいています。","voiceIndex":334,"id":"exchange-137"},{"speaker":"須貝委員","kind":"意見","question":"そういうご答弁だったんですが、やはりまちを歩けばわかりますよね。店に入って、ものづくりなら製造業の各企業に入って、そういう資料をきちんとそろえて、やはりその実態を見て政策というのは考えるべきではないかというふうに申し上げておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":336,"id":"exchange-138"},{"speaker":"いながわ委員","kind":"質問","question":"１３８ページの公衆浴場に対する助成について、品川区の浴場組合のホームページで数を勘定しますと３２軒になっているんですが、今、区内の公衆浴場の軒数、もしわかれば、荏原、大井、大崎、品川の分布といいますか、軒数がわかれば地域別に教えてください。わからなかったら総軒数で構いません。お願いします。","respondent":"江部健康課長","answer":"全体で３１浴場です。地域別というのは数えないとちょっと。","voiceIndex":338,"id":"exchange-139"},{"speaker":"いながわ委員","kind":"質問・要望","question":"おそらく全盛期より相当軒数が減って、浴場組合の地図で検索というのをちらっと見ると、３１軒以上まだドットが落とされているという現状もあるので、なかなか本当の数というのは、申請件数になると思うんですが。それは、ありがとうございました。品川区がこの設備に助成する意義を改めてお聞かせいただきたいということと、今後の公衆浴場について、健康課長はどうお考えか、教えてください。","respondent":"江部健康課長","answer":"健康課が公衆浴場組合に助成している意義につきましては、第一義的には入浴という行為が自宅でできない方の衛生面の確保、それからもう一方では浴場組合の経営の部分的な支援という２面があると思います。","voiceIndex":340,"id":"exchange-140"},{"speaker":"いながわ委員","kind":"質問","question":"ここでグッとかじを切って、観光の視点で今度公衆浴場を考えたとき、それについてちょっとお伺いしていきたいんですが。羽田空港の国際化、２０２０年の東京オリンピック・パラリンピック開催がもう決定しております。テレビなど見ても、この外国人が日本の銭湯というんですか、公衆浴場に行くというのが、非常に今ブームだということも、報道されております。短めで構いませんので。","respondent":"米田商業・観光課長","answer":"あわせまして観光の側面からいいますと、銭湯スタンプラリーというような事業も平成２３年度には実施しておりますし、いわゆる公衆浴場商業協同組合との話し合い等にもよりますが、あちらのほうでぜひとも観光振興に銭湯を使ってまいりたいというような合意がとれれば。","voiceIndex":342,"id":"exchange-141"},{"speaker":"いながわ委員","kind":"質問・要望","question":"まさに、部署が分かれておりますけれど、そこはしっかり連携をして、最大限品川区として公衆浴場をバックアップしていただきたいと考えていますので、よろしくお願いいたします。それでこれは終わります。１４６ページの資源持ち去り防止対策費について、端的にお伺いしますが、今回予算ベースにおいては１件５万円の過料が予算の中に入っていました。それをまずお聞かせください。","respondent":"小林品川区清掃事務所長","answer":"ご指摘の過料を科した実績は、平成２４年度はございません。過料を科すに当たっては、規則に基づいて原状回復命令を行い、それに従わない者に対してあらかじめ弁明書をもって告知した後に、最終的に科していくという手続行為があります。","voiceIndex":344,"id":"exchange-142"},{"speaker":"いながわ委員","kind":"質問","question":"先ほども沢田委員から質問がありまして、１００件指導したという中で、本当にその１００件の人たちが素直に戻していただいたということで理解はしますが、１００件つかまえると、指導すれば１件ぐらいあるのではないかと思って、質問させていただきました。資源がキロ６円、町会に入るんですが。","respondent":"小林品川区清掃事務所長","answer":"指導を行う中で、たびたび指導して、やむを得ない場合にそれをその場で引き取って、車に積むということがありますが、これを行っておりますのは集団回収のものではありませんで、通常の資源回収、区の定めた資源ステーションに置いたものを持ち去ろうとしたものに対して。","voiceIndex":346,"id":"exchange-143"},{"speaker":"いながわ委員","kind":"質問・要望","question":"次に１４９ページです、観光全般でお伺いします。私が見たところは運河、東品川一丁目というんですか、ボードウォークのあたり、もう目の前から見て、非常に限られた空間の中で、あのビルの間に大輪が咲くというのは非常に大迫力で、感動いたしました。このご意志は、まさに品川区で花火大会をやる第一歩だと私は思っておりますので、ぜひ理想をいえばちゃんと期日を切って、調査研究をしていただきたいと。","respondent":"米田商業・観光課長","answer":"いろいろな状況を勘案しながら、進めるところは進め、立ちどまって検証しなければならないところは検証し、というような姿勢で、観光協会とは連携しつつ、十分その辺は調整の上、歩を進めてまいりたいと考えています。","voiceIndex":348,"id":"exchange-144"},{"speaker":"いながわ委員","kind":"質問・要望","question":"検証して立ちどまったとき、ぜひまた前へ一歩を踏み出していただくように、お願いをしたいところであります。２０２０年には青海の客船ターミナルを整備すると東京都も発表しておりますが、７年間は暫定入港といいますか、水産物埠頭に来るのではないかと思いますが、それに対して品川区として７年間の限定された期間でありますが、どういったお考えで外国人をこの品川区に呼び寄せるか、お聞かせください。","respondent":"米田商業・観光課長","answer":"現状、大田区のところで休日というようなことで、それから通関手続もそこで行って、そのままバスに乗ってというような流れで、なかなかその場でお降りになってというようなことは、交通の便からも難しいということは思っております。","voiceIndex":350,"id":"exchange-145"},{"speaker":"いながわ委員","kind":"提案","question":"ぜひ前向きにしっかりとやっていただいて、あと一点提案なんですが、青海埠頭に接岸されてしまいます。ここにまた暫定入港したときに、品川区のエリアから、ウエルカム花火ではないですけれど、そういうのを打ち上げるのも一つの手かもしれませんが、いかがでしょう。おもてなしの観点で。","respondent":"米田商業・観光課長","answer":"いろいろ勉強させていただければと思います。","voiceIndex":352,"id":"exchange-146"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は成果報告書の１４０ページの環境衛生費の中の、狂犬病予防および動物の愛護について伺いたいと思います。それから毎年９月２０日から２６日が動物愛護週間というふうになっておりますが、区として何か事業を、また実施したことがあるかどうか教えてください。","respondent":"高山生活衛生課長","answer":"改正動物愛護管理法に関するお尋ねです。こちらは平成１７年に動物愛護管理法が一部改正されまして、その後５年を経たことから、さまざまな法施行上の状況等を踏まえて改正されたものです。","voiceIndex":355,"id":"exchange-147"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この辺については予算をしっかりつけていただいて、やっていただきたいと思います。こうしたことについて、この殺処分をゼロにしていこうという改正動物愛護管理法、これについてしっかり周知、また今後の動物愛護について予算をしっかり取って、周知、啓発していっていただきたいと思うんですけれど、考え方を教えてください。","respondent":"高山生活衛生課長","answer":"動物愛護と申しますと、普及啓発がやはり中心ということになろうかと思います。飼い主の責任を徹底させつつ、区としましてもさまざまな啓発の機会を設けまして、そういった飼い主の方々に対する適正飼育に関する普及啓発、愛護思想の普及にかかわってまいりたいと考えております。","voiceIndex":357,"id":"exchange-148"},{"speaker":"たけうち委員","kind":"質問・要望","question":"この９月から、先ほど言ったとおり法が改正されて、そういう趣旨が明確に打ち出されてやっていく中で、品川区のホームページを見すると、この東京都のホームページにリンクされるようになっていまして、東京都のホームページを見るとしっかり伝わるんですけれど、品川区としてこれをどう啓発していくかということを、しっかりやっていただきたいと思うんですけれど。","respondent":"高山生活衛生課長","answer":"こういった法改正に伴いまして、さまざまなご意見が伴ってこの改正がなされたというふうに捉えまして、区といたしましてもホームページでの発信も含めまして、一層の啓発、充実に努めてまいりたいと考えております。","voiceIndex":359,"id":"exchange-149"},{"speaker":"本多委員","kind":"質問","question":"１４９ページの伝統的産業の振興、これについて質問いたします。「伝統の技と味しながわ展」開催等経費、４７３万５,７９６円、また新製品開発助成、１５０万円ということで、平成２年から「伝統の技と味しながわ展」など、今では中小企業センターでの実演ですとか、ふれあい講座等でもう２０年以上も定着されてきておりますけれども、やり方はこのままでいいのでしょうかという点。","respondent":"米田商業・観光課長","answer":"今、課題といたしましては新製品開発助成等で、高いもの、それはそれでちゃんと目が利いて、それでもお金を払うというよう方はそれを購入されるわけですけれども、それとはまた違った形で、いわゆる伝統の技というものをもっと安い形で、手に取ることができないかということでは。","voiceIndex":362,"id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"それで新商品のかき入れ時というんでしょうか、そういったものを聞きたいなと思いました。これは伝統産業のほうなんですけれども、あとものづくりの新商品開発、これは款が変わってしまうんですけれども、そういった新商品開発に対する助成の仕方と、この伝統的産業に対する新商品開発への助成と、何か両方頑張っていただきたいと思うんですけれど、その辺いかがでしょうか。","respondent":"米田商業・観光課長、山崎ものづくり・経営支援課長","answer":"そういった中では、そういう開発も一つではあるんですけれども、それぞれの技を組み合わせて、比較的手軽に手にとれるような商品の開発と、それをいろいろなところで売り込めるような販売促進の方法。市場も非常に狭いニッチな市場もあります。そういう市場の中で、トップをとっていくということを目指して、区のほうも支援し、販路拡大等につなげていくということでやっております。","voiceIndex":364,"id":"exchange-151"},{"speaker":"本多委員","kind":"質問","question":"伝統のほうも、ものづくりと同じように後押しをお願いしますという意味で、ちょっとお聞かせいただきました。この実現等、例えば旅行会社の企画で日帰りバスツアーなどでの一コマに実演を見てもらうような、タイムスケジュールの一コマに入れてもらうとか、そういった区としてできる働きかけ、あと外国人への日本でのお土産とか、現状と今後の発展性について、働きかけについてはいかがでしょうか。","respondent":"米田商業・観光課長","answer":"こういうものも少しクリアしながら、少しでも観光の一側面として、展開できないかということは、外国人のいわゆる体験ということも、外国人の方は興味がおありになるということですので、そういう部分も含めて、さらなる伝統工芸の発展につながるような形での振興策を。","voiceIndex":367,"id":"exchange-152"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば伝統工芸品なんですけれども、全国で１,５００品目ぐらいあって、国が２１５ぐらい、昭和４９年に法律をつくってから指定されておりますけれども、例えば神奈川県の箱根ですと寄せ木細工ということで昭和５９年に国指定を受けておりますけれども、こういったものも世界に配送するようなことがもう既に定着しておりますけれども、品川の伝統産業ですとか、個別の工芸品の発展性ですね。","respondent":"米田商業・観光課長","answer":"今、ご提案のありましたようなことも、今後展開が図れればますます、伝統的工芸品の普及、発展にもつながるところもありますので、こちらについては十分研究してまいりたいと考えています。","voiceIndex":369,"id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1378#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2013-01-01&TermEnd=2013-12-31"}],"sourceMeta":{"pages":0,"characters":109251,"voices":371}}]);
